window.__Q=window.__Q||{};window.__Q["clin/3/A1"]=[{"q":"患者患SIADHS（抗利尿激素分泌失调综合征），当其ADH分泌过多时，患者的","o":["血钠浓度高于正常","细胞内液量高于正常","尿量多于正常","血浆胶体渗透压高于正常","血浆总渗透压高于正常"],"a":1,"e":"ADH分泌过多使肾集合管水重吸收增加，水潴留致细胞外液渗透压降低、水向细胞内转移，细胞内液量增多，并出现稀释性低钠血症和尿量减少。"},{"q":"内源性凝血途径的始动因子是","o":["FⅫ","FⅪ","FⅩ","FⅦ","FⅢ"],"a":0,"e":"内源性凝血途径由FⅫ接触带负电荷的胶原表面而被激活为FⅫa所启动，FⅫa再激活FⅪ。FⅪ是内源性途径中FⅫ的下游因子，并非始动因子。"},{"q":"从精原细胞有丝分裂开始到发育成为精子大约需要","o":["14天","28天","36天","48天","64天"],"a":4,"e":"各级生精细胞须突破支持细胞间连接向管腔方向迁移，此过程约需70天，教材所述生精全程与之相当，选项中64天最接近。"},{"q":"跨肺压是指","o":["大气压与胸廓回缩压之差","大气压与肺回缩压之差","大气压与胸膜腔内压之差","肺内压与胸膜腔内压之差","肺内压与大气压之差"],"a":3,"e":"跨肺压是使肺扩张的压差，等于肺内压与胸膜腔内压之差。肺内压与大气压之差反映的是呼吸道气流驱动压。"},{"q":"压力感受性反射的生理意义是","o":["减慢心率","增加冠脉血流量","降低平均动脉压","重新分配各器官血流量","稳定快速波动的血压"],"a":4,"e":"压力感受性反射是典型负反馈调节，能缓冲运动、体位改变等引起的快速血压波动，故传入神经又称缓冲神经。该反射对血压长期调节不起重要作用。"},{"q":"室性期前收缩之后常出现代偿间歇的原因是","o":["窦房结传来的节律性兴奋落在室性期前兴奋的有效不应期内","窦房结的节律性兴奋少发放一次","窦房结的节律性兴奋延迟发放","室性期前兴奋的有效不应期特别长","窦房结的节律性兴奋传出速度大大减慢"],"a":0,"e":"期前兴奋有自身的有效不应期，紧接其后的窦房结兴奋若落在此期内则不能引起心室兴奋收缩，出现一次脱失，形成代偿间歇。"},{"q":"下列药物能阻断心迷走神经的作用的是","o":["普萘洛尔","阿托品","酚妥拉明","肾上腺素","乙酰胆碱"],"a":1,"e":"心迷走神经通过释放ACh作用于心肌M受体发挥抑制作用，阿托品为M受体拮抗剂，可阻断该作用使心率加快。普萘洛尔阻断的是β受体。"},{"q":"下列哪项不是血浆蛋白的主要功能","o":["运输物质","参与机体的免疫","缓冲pH值","参与生理止血","维持血浆晶体渗透压"],"a":4,"e":"血浆晶体渗透压主要由Na+、Cl-等晶体物质形成，与血浆蛋白无关；血浆蛋白主要维持胶体渗透压，并具有运输、免疫、缓冲pH和参与止血等功能。"},{"q":"第一心音特点为","o":["在心尖搏动处听诊，音调较低，持续时间较长","在心尖搏动处听诊，音调较高，持续时间较短","在心尖搏动处听诊，音调较低，持续时间较短","在主动脉瓣听诊区听诊，音调较低，持续时间较长","在主动脉瓣听诊区听诊，音调较高，持续时间较短"],"a":0,"e":"第一心音标志心室收缩开始，由房室瓣关闭及心室射血引起振动产生，在心尖搏动处听诊最清楚，特点为音调较低、持续时间较长。"},{"q":"胆汁的主要作用是","o":["激活胰蛋白酶原","促进淀粉水解","促进脂肪的消化和吸收","中和胃液","杀灭细菌"],"a":2,"e":"胆汁的主要作用是促进脂肪的消化和吸收。胆盐、卵磷脂作为乳化剂将脂肪乳化成微滴，增加胰脂肪酶作用面积，并形成微胶粒促进吸收。激活胰蛋白酶原的是肠激酶。"},{"q":"某运动员比赛时大量出汗（1L），此时该运动员会出现","o":["细胞外液量降低，细胞内液量降低和血浆胶体渗透压升高","细胞外液量降低、细胞内液量不变和晶体渗透压升高","细胞外液量降低、细胞内液量不变和胶体渗透压升高","细胞外液量降低、晶体渗透压升高和胶体渗透压不变","细胞外液量降低、细胞内液量升高和晶体渗透压升高"],"a":0,"e":"大量出汗丢失低渗液，细胞外液量减少且晶体渗透压升高，水由细胞内向细胞外转移致细胞内液减少；失水使血浆蛋白浓度相对升高，血浆胶体渗透压升高。"},{"q":"血中哪种物质浓度升高刺激醛固酮的分泌","o":["氯离子浓度","氢离子浓度","钠离子浓度","钾离子浓度","ACTH"],"a":3,"e":"血K+浓度升高可直接刺激肾上腺皮质球状带分泌醛固酮，且醛固酮分泌对血K+变化更为敏感。血Na+浓度降低也刺激醛固酮分泌，但敏感性低于K+。"},{"q":"下列各项中，不是冠脉循环特点的是","o":["平静状态下冠脉血流量可占心输出量的4%～5%","心肌的摄氧率可比其他器官高30%","剧烈运动时，心肌主要依靠提高从单位血液中摄氧的潜力来满足心肌对氧的需求","心肌深层的冠脉血管可由于心脏的收缩而出现断流甚至逆流","左心室的冠脉血流量一般大于右心室"],"a":2,"e":"心肌摄氧率高，动用心力储备时提高摄氧的潜力小，主要依靠扩张冠脉增加血流量满足氧需求，而非提高摄氧率。"},{"q":"不需要蛋白质辅助的跨膜转运方式为","o":["出胞","原发性主动转运","单纯扩散","继发性主动转运","易化扩散"],"a":2,"e":"单纯扩散是脂溶性物质顺浓度差经脂质分子间隙的跨膜转运，无转运蛋白参与、不耗能。易化扩散及各类主动转运均需膜蛋白介导。"},{"q":"血浆与组织液各种成分浓度的主要区别是","o":["钠离子","钾离子","蛋白质","有机酸","血细胞"],"a":2,"e":"血浆与组织液的主要差别是蛋白质含量，血浆蛋白分子大，不易透过毛细血管壁，故组织液中蛋白甚少。两者离子成分基本相同，Na+、K+、有机酸、尿素浓度无显著差异。"},{"q":"下列哪种物质不属于第二信使","o":["cAMP","ACh","钙离子","三磷酸肌醇","二酰甘油"],"a":1,"e":"第二信使包括cAMP、IP3、DG、cGMP、Ca2+等。ACh是神经递质，作用于受体后经G蛋白等产生第二信使，其本身不属于第二信使。"},{"q":"下列哪种因素将导致静脉血氧分压降低、呼吸增强","o":["贫血","CO中毒","亚硝酸盐中毒","剧烈运动","过度通气"],"a":3,"e":"剧烈运动时组织耗氧增加，静脉血氧分压降低，同时CO2升高、H+增多刺激呼吸增强。贫血和CO中毒时动脉血氧分压正常，不引起静脉血氧分压降低。"},{"q":"促进肾脏分泌肾素的因素不包括","o":["位于入球小动脉壁的牵张感受器受到的刺激减少","流经致密斑处的小管液中NaCl量减少","急性大出血导致的血压下降","心房钠尿肽","低盐饮食"],"a":3,"e":"心房利尿钠肽抑制肾素、醛固酮和抗利尿激素的合成与分泌，故不促进肾素分泌。入球小动脉牵张感受器刺激减少、致密斑NaCl减少、血压下降及低盐饮食均促进肾素释放。"},{"q":"心室舒张功能障碍的患者","o":["舒张速率减慢，等容舒张期延长","舒张速率减慢，等容舒张期不变","舒张速率加快，等容舒张期延长","舒张速率减慢，等容舒张期缩短","舒张速率加快，等容舒张期缩短"],"a":0,"e":"舒张功能障碍时心肌舒张速率减慢，等容舒张期延长，舒张早期左心室压力较高、抽吸作用变小，e波变小。"},{"q":"关于兴奋性突触后电位的描述，正确的是","o":["即突触后神经元处于兴奋状态","经一中间神经元的中介而产生","由突触后膜钾电导增加而产生","由突触后膜钙电导增加而产生","可随突触前递质释放增多而增大"],"a":4,"e":"兴奋性突触后电位由突触前膜释放兴奋性递质作用于突触后膜产生，递质释放量随进入末梢的Ca²⁺增多而增加，故递质释放增多时该电位增大。它使突触后神经元兴奋性升高，并非处于兴奋状态。"},{"q":"慢波睡眠的特征是","o":["脑电呈去同步化的慢波","多梦","生长激素分泌减少","促进生长和体力恢复","促进神经系统发育成熟"],"a":3,"e":"慢波睡眠即NREM睡眠，此期腺垂体分泌生长激素明显增多，有利于体力恢复和促进生长发育。脑电呈同步化慢波，多梦见于异相睡眠。"},{"q":"某人的血浆中只含有抗A凝集素，则该人的血型不可能是","o":["A型","B型","O型","AB型","Rh型"],"a":0,"e":"血浆中只含抗A凝集素者为B型血，其红细胞含B抗原。A型血者血清含抗B抗体，与“只含抗A”不符。"},{"q":"为气体医学研究拉开序幕的诺奖分子是","o":["CO","H2S","N2","NO","H2"],"a":3,"e":"NO是首个被发现的气体信号分子，Furchgott等三位科学家因发现NO获1998年诺贝尔生理学或医学奖，为气体医学研究拉开序幕。"},{"q":"胰岛素缺乏时，一般不出现","o":["多尿","多饮","高血糖","高血压","高血脂"],"a":3,"e":"胰岛素缺乏导致糖尿病，出现高血糖、多尿、多饮及脂代谢紊乱所致高血脂。高血压主要与胰岛素抵抗相关，并非胰岛素缺乏的直接表现。"},{"q":"细胞内能使蛋白质磷酸化的酶是","o":["磷脂酶C","蛋白激酶","磷酸二酯酶","乙酰胆碱酯酶","蛋白磷酸酶"],"a":1,"e":"蛋白激酶是将ATP上的磷酸基团转移到底物蛋白质、使其磷酸化的酶。蛋白磷酸酶则催化去磷酸化，作用相反。"},{"q":"当过度通气时，呼吸会出现暂停的原因是","o":["血液PO2过高","血液PCO2过高","血液PO2过低","血液PCO2过低","血液pH值过低"],"a":3,"e":"过度通气排出过多CO₂，动脉血PCO₂下降至低于40mmHg，对呼吸中枢的刺激减弱，出现呼吸暂停。"},{"q":"血凝块形成后回缩的原因是","o":["纤维蛋白收缩","红细胞叠连","白细胞变形","血小板收缩蛋白收缩","红细胞破裂"],"a":3,"e":"血凝块回缩依赖血小板内收缩蛋白系统，血小板活化后胞质Ca2+升高，分解ATP引起收缩，使血块回缩。纤维蛋白本身不收缩，红细胞叠连、白细胞变形、红细胞破裂均与血块回缩无关。"},{"q":"调节体温的基本中枢在","o":["脊髓","延髓","下丘脑","脑干网状结构","大脑皮质"],"a":2,"e":"视前区-下丘脑前部是体温调节的基本中枢，存在温度敏感神经元；只要下丘脑及以下神经结构完整，动物即可维持体温相对稳定。脊髓、延髓仅为整合的较低部位。"},{"q":"哇巴因抑制甲状腺激素的产热效应是通过","o":["抑制腺苷酸环化酶","抑制脱碘酶","抑制溶酶体酶","抑制Na+-K+-ATP酶","抑制磷酸二酯酶"],"a":3,"e":"甲状腺激素产热通过上调线粒体数量、UCP表达及Na+-K+-ATP酶转录使代谢率增加，哇巴因抑制Na+-K+-ATP酶，从而阻断其产热效应。"},{"q":"纤溶酶的主要作用是","o":["激活因子Ⅻ","激活补体系统","抑制激肽系统","水解凝血酶及因子Ⅴ、Ⅶ","水解纤维蛋白原和纤维蛋白"],"a":4,"e":"纤溶酶属丝氨酸蛋白酶，最敏感的底物是纤维蛋白和纤维蛋白原，将其分解为可溶性小肽即纤维蛋白降解产物。纤溶酶对多种凝血因子也有降解作用，但主要作用是降解纤维蛋白（原）。"},{"q":"下列关于淋巴回流意义的描述，错误的是","o":["回收蛋白质","调节血管内外水分交换","回收部分组织液","清除细菌","运输被吸收的脂质"],"a":1,"e":"淋巴回流可回收部分组织液和蛋白质、清除细菌、运输被吸收的脂质；血管内外水分交换由毛细血管血压与血浆胶体渗透压决定，不属淋巴回流的意义。"},{"q":"听觉感受器是","o":["螺旋器","耳蜗","椭圆囊斑","球囊斑","壶腹嵴"],"a":0,"e":"基底膜上的螺旋器（科蒂器）由内、外毛细胞及支持细胞组成，是听觉感受器。椭圆囊斑、球囊斑和壶腹嵴属前庭器官，感受平衡觉。"},{"q":"运动神经纤维末梢释放ACh属于","o":["单纯扩散","易化扩散","主动转运","出胞作用","入胞作用"],"a":3,"e":"运动神经末梢释放ACh是以囊泡为基本单位的量子式释放，囊泡与接头前膜融合将递质排出细胞，属出胞作用，需Ca2+内流触发并消耗能量。"},{"q":"关于突触前易化的产生，下列哪一项描述是正确的","o":["结构基础与突触前抑制完全不同","到达突触前末梢的动作电位频率高","有多个兴奋同时到达突触前末梢","进入突触前末梢内的钙离子增多","突触后膜有多个EPSP发生总和"],"a":3,"e":"突触前易化由突触前末梢Ca2+内流增多、递质释放量增加所致，使突触后EPSP幅度增大。动作电位频率高、多个末梢同时兴奋只是引起钙内流增多的条件，EPSP总和属突触后过程。"},{"q":"衡量可兴奋组织兴奋性常用的指标是","o":["阈强度","阈电位","静息电位","动作电位幅值","动作电位传导速度"],"a":0,"e":"阈强度是能引起活组织细胞产生反应的最小刺激强度，阈值越小表示兴奋性越高，故常用阈强度衡量兴奋性高低。阈电位是触发动作电位的膜电位临界值，并非衡量兴奋性的指标。"},{"q":"反射活动所表现的后放现象的结构基础是神经元间的","o":["辐射式联系","聚合式联系","链锁状联系","环状联系","单线式联系"],"a":3,"e":"后放现象指刺激停止后反射仍持续一段时间，其结构基础是神经元间的环状联系，兴奋经环路反复传递使活动延续。链锁状联系使兴奋在空间上扩大范围，不产生后放。"},{"q":"突触后神经元活动取决于","o":["EPSP的总和","IPSP的总和","EPSP和IPSP的代数和","大脑皮层的下行冲动","小脑皮层的下行冲动"],"a":2,"e":"突触后神经元的活动取决于EPSP和IPSP总合后的代数和，去极化达阈电位即爆发动作电位，超极化则抑制。EPSP与IPSP可相互叠加或抵消，单一电位总和不能决定最终效应。"},{"q":"与窦房结细胞动作电位0期去极化有关的离子跨膜流动是","o":["因Na+内流而产生","因Ca2+内流而产生","因Cl-内流而产生","因K+内流而产生","因K+外流而产生"],"a":1,"e":"窦房结P细胞属慢反应细胞，其动作电位0期去极化由L型钙通道介导的Ca2+内流产生，可被维拉帕米阻断。Na+内流产生的是快反应细胞（如心室肌）的0期去极化。"},{"q":"下列关于基础代谢的叙述，错误的是","o":["在基础状态下单位时间内的能量代谢","基础代谢一般在餐后12～14小时检测","检测基础代谢的室内温度在20～25℃","精神状态一般不影响基础代谢","肌肉活动明显影响基础代谢"],"a":3,"e":"基础代谢指基础状态下的能量代谢，要求空腹（餐后12～14小时）、清醒静卧、室温20～25℃、精神安宁，精神紧张可使代谢率增高10%以上，故精神状态影响基础代谢。"},{"q":"人类处于清醒、安静并闭眼状态时，脑电活动的主要表现为","o":["α波","β波","θ波","δ波","棘慢波"],"a":0,"e":"α波频率8～13Hz，在成年人清醒、安静并闭眼时出现，枕叶最显著；睁眼或受刺激时α波消失而呈现β波，即α阻断。β波是新皮层紧张活动状态的标志。"},{"q":"自主神经系统对内脏活动调节的重要特点是","o":["所有脏器均有双重神经支配","均为双重神经支配拮抗作用","具有持久紧张性作用","调节作用与效应器本身机能状态无关","副交感神经系统兴奋时作用广泛"],"a":2,"e":"自主神经系统对内脏活动的调节具有持久紧张性作用，源于其中枢神经元的紧张性活动，如压力感受器传入维持心交感和心迷走紧张性。并非所有脏器均受双重支配，如多数血管仅受交感缩血管神经支配。"},{"q":"下列关于神经递质的描述，正确的是","o":["神经系统内凡能与受体结合的化学物质都是递质","其功能是调节突触传递效率","一个神经元的全部末梢均释放同一种递质","一种神经递质只作用于一种特定的受体","递质作用于受体产生效应后很快被消除"],"a":4,"e":"递质释放后与受体结合产生效应的同时，即被酶促降解和突触前末梢重摄取迅速消除，如乙酰胆碱酯酶水解ACh。能与受体结合的化学物质还包括调质和激素，且一种递质可作用于多种受体。"},{"q":"凝血酶的主要作用是","o":["加速FⅦ复合物的形成","加速凝血酶原酶复合物的形成","使纤维蛋白原转变为纤维蛋白","激活FⅫ","促进血小板聚集"],"a":2,"e":"凝血酶使纤维蛋白原从N端脱下A肽和B肽，转变为纤维蛋白单体，并激活FⅩⅢ，最终形成交联纤维蛋白凝块完成凝血。凝血酶原酶复合物是激活凝血酶原的上一环节，并非凝血酶的作用。"},{"q":"“Rh阳性”是指红细胞膜上有","o":["C抗原","A抗原","D抗原","E抗原","B抗原"],"a":2,"e":"D抗原抗原性最强、临床意义最重要，红细胞含D抗原者为Rh阳性，缺乏D抗原者为Rh阴性。A、B抗原属ABO血型系统，与Rh分型无关。"},{"q":"全血的比重主要决定于","o":["血浆蛋白含量","渗透压的高低","红细胞数量","白细胞数量","NaCl的浓度"],"a":2,"e":"全血比重为1.050～1.060，红细胞数量越多全血比重越大。血浆比重才主要取决于血浆蛋白含量。"},{"q":"刺激支配唾液腺的副交感神经，可引起","o":["量多、固体成分少的唾液分泌","量少、固体成分少的唾液分泌","量少、固体成分多的唾液分泌","量多、固体成分多的唾液分泌","唾液量不变"],"a":0,"e":"副交感神经兴奋通过M受体引起量多而固体成分少的稀薄唾液分泌；交感神经兴奋则引起量少而固体成分多的黏稠唾液。"},{"q":"关于胰岛素受体的描述，错误的是","o":["由两个α亚单位和两个β亚单位组成","属于酪氨酸激酶受体家族成员","不同细胞胰岛素受体的数量无显著差异","α亚单位起着抑制β亚单位酪氨酸激酶的作用","胰岛素受体底物介导细胞内的多种生物效应"],"a":2,"e":"不同组织细胞胰岛素受体数量差异显著，如肝细胞和脂肪细胞可达（2～3）×10⁴个，而红细胞仅40多个，这决定了对胰岛素敏感性的差异。"},{"q":"下列关于牵张反射的叙述，错误的是","o":["牵张反射的感受器是肌梭","只有快速牵拉肌腱时才会发生牵张反射","牵张反射是维持姿势的基本反射","牵张反射在抗重力肌表现最为明显","在脊髓突然与高位中枢离断后，牵张反射可暂时消失"],"a":1,"e":"牵张反射包括快速牵拉肌腱的腱反射和缓慢持续牵拉肌腱的肌紧张，后者是维持姿势的基本反射，故并非只有快速牵拉才发生。"},{"q":"关于心动周期的论述，下列说法错误的是","o":["舒张期大于收缩期","左、右心室的搏出血量相等","等容舒张期末左心室容积最大","等容收缩期末主动脉压力最低","快速射血期末主动脉和左心室压力最高"],"a":2,"e":"等容舒张期心室容积不变，至快速充盈期末心室容积才迅速增大，故等容舒张期末并非容积最大。等容收缩期末主动脉压最低、快速射血期末压力最高均正确。"},{"q":"正常成人的血液总量约相当于体重的","o":["8%","15%","20%","60%","40%"],"a":0,"e":"正常成人血液总量相当于体重的7%～8%，即每千克体重70～80ml，60kg者约4.2～4.8L。"},{"q":"生物活性最高的甲状腺激素是","o":["四碘甲腺原氨酸","三碘甲腺原氨酸","逆-三碘甲腺原氨酸","DIT和MIT","酪氨酸"],"a":1,"e":"三碘甲腺原氨酸（T3）的生物活性最高。T3与受体的亲和力远高于T4，约为T4的10倍以上，虽分泌量仅占9%，却是发挥生理作用的主要形式。"},{"q":"交感和副交感神经的作用不表现对抗效应的器官是","o":["小肠腺","膀胱逼尿肌","唾液腺","心脏","消化道平滑肌"],"a":2,"e":"唾液腺接受交感和副交感神经双重支配，两者均促进唾液分泌，仅分泌量及黏稠度不同，不表现对抗效应。副交感引起大量稀薄唾液，交感引起少量黏稠唾液。"},{"q":"促进腺垂体TSH分泌的下丘脑调节肽是","o":["CRH","GHRH","GnRH","PRF","TRH"],"a":4,"e":"下丘脑合成的促甲状腺激素释放激素（TRH）经垂体门脉运至腺垂体，促进TSH的合成与释放。TRH从量和质两方面调节TSH分泌，1分子TRH可使腺垂体释放约1000分子TSH。"},{"q":"心交感神经节前纤维释放的神经递质是","o":["乙酰胆碱","去甲肾上腺素","血管升压素","谷氨酸","γ-氨基丁酸"],"a":0,"e":"心交感神经节前纤维属胆碱能纤维，末梢释放乙酰胆碱，作用于节后神经元胞体膜的N1受体。所有自主神经节前纤维均以乙酰胆碱为递质。"},{"q":"促进脂肪分解代谢的激素不包括","o":["胰岛素","胰高血糖素","生长素","甲状腺激素","肾上腺素"],"a":0,"e":"胰岛素促进脂肪合成与储存、抑制脂肪分解，故不属促进脂肪分解的激素。胰高血糖素、生长素、甲状腺激素和肾上腺素均促进脂肪分解。"},{"q":"与运动调节有关的基底神经节结构不包括","o":["旧纹状体","黑质","丘脑底核","新纹状体","杏仁核"],"a":4,"e":"基底神经节由纹状体（新、旧纹状体）、黑质和丘脑底核等构成，参与运动调节。杏仁核属边缘系统，与情绪和摄食调节有关，不属基底神经节。"},{"q":"影响骨骼、肌肉生长发育的最主要的激素是","o":["糖皮质激素","生长激素","盐皮质激素","肾上腺素","甲状腺激素"],"a":1,"e":"生长激素对几乎所有组织和器官的生长均有促进作用，尤其对骨骼、肌肉和内脏器官作用最为显著，是影响骨骼、肌肉生长发育最主要的激素。"},{"q":"近髓肾单位的主要功能是","o":["分泌肾素","分泌醛固酮","浓缩与稀释尿液","排泄钠和氯离子","分泌血管升压素"],"a":2,"e":"近髓肾单位髓袢长，可深入内髓部甚至达肾乳头，与直小血管共同构成逆流系统，是尿液浓缩与稀释的结构基础。"},{"q":"下列关于传入侧支性抑制的描述，正确的是","o":["神经元传入侧支与自身形成负反馈回路","传入纤维的主干与侧支释放不同的递质","通过交互性突触而产生交互抑制的作用","这种抑制形式仅发生于脊髓，脑内不存在","作用意义在于保证伸肌和屈肌活动的协调控制"],"a":4,"e":"传入侧支抑制是传入纤维的侧支经抑制性中间神经元抑制拮抗肌运动神经元，保证伸肌与屈肌活动的协调控制。其并非对自身抑制，对自身抑制的是回返性抑制。"},{"q":"红细胞表面积与体积比值的下降可引起红细胞","o":["变形性增强","渗透脆性增大","悬浮稳定性增强","对低渗盐溶液的抵抗力增强","血红蛋白含量增加"],"a":1,"e":"红细胞表面积与体积之比降低时变形能力减弱，在低渗盐溶液中更易膨胀破裂，即渗透脆性增大。遗传性球形红细胞增多症即因双凹圆碟形丧失而脆性变大。"},{"q":"进行物质交换的血液不流经下列哪个微循环血管","o":["微动脉","后微动脉","通血毛细血管","真毛细血管","微静脉"],"a":2,"e":"直捷通路经通血毛细血管直接连通微动脉与微静脉，血流快，主要保证静脉回心血量，不进行物质交换。物质交换主要经真毛细血管完成。"},{"q":"下列关于回返性抑制的描述，正确的是","o":["经自身受体抑制递质释放而实现","通过串联性突触而起抑制作用","细胞内共存兴奋性和抑制性递质","能使同一中枢内许多神经元的活动同步化","效应是使兴奋神经元周边的神经元抑制"],"a":3,"e":"回返性抑制是神经元经轴突侧支兴奋抑制性中间神经元，再抑制自身，意义在于及时终止神经元活动并使同一中枢内许多神经元的活动同步化。"},{"q":"肌梭感受器的适宜刺激是","o":["梭外肌收缩","梭外肌松弛","梭外肌受牵拉","梭内肌紧张性降低","梭内肌受压迫"],"a":2,"e":"肌梭与梭外肌纤维呈并联关系，当梭外肌受牵拉时肌梭随之被牵拉而兴奋，故其适宜刺激是梭外肌受牵拉。肌梭是长度感受器，感受肌肉长度的变化。"},{"q":"感受器能把刺激所包含的环境变化信息，转移到新的电信号系统中，感受器的这种生理特性称为","o":["感受器适宜刺激","感受器换能作用","感受器编码作用","感受器适应现象","感受器的启动电位"],"a":2,"e":"感受器把刺激所包含的环境变化信息转移到动作电位的序列中，称为感受器的编码功能。换能作用仅指将刺激能量转换为感受器电位。"},{"q":"主动脉在维持舒张压中起主要作用，主要是由于主动脉的以下特点","o":["主动脉管腔口径大，管壁压力高","主动脉管壁受交感缩血管神经的支配","主动脉管壁有可扩张性和弹性","心室射血期短，血流速度快","主动脉管径大，对血流的摩擦阻力小"],"a":2,"e":"主动脉管壁富含弹性纤维，具有可扩张性和弹性，射血期储存弹性势能，舒张期弹性回缩推动血液继续流向外周，从而维持舒张压。"},{"q":"某青年男性在剧烈运动之后心率超过180次/分，心输出量减少。请问是以下哪个时相缩短","o":["快速充盈相","减慢充盈相","等容收缩相","减慢射血相","心房收缩相"],"a":0,"e":"心率超过180次/分时心室舒张期明显缩短，充盈量减少使搏出量下降。静脉回心血量大部分在快速充盈期进入心室，故该时相缩短是充盈减少的关键。"},{"q":"保持脑脊液中H+浓度不变而升高脑脊液PCO2，呼吸将会发生什么改变","o":["呼吸变快加深","呼吸变浅变慢","呼吸没有明显变化","呼吸暂停","长吸式呼吸"],"a":2,"e":"脑脊液H+是中枢化学感受器的主要刺激因素，PCO2需先转变为H+才起作用。保持H+浓度不变而仅升高PCO2，呼吸无明显变化。"},{"q":"骨骼肌收缩时释放到肌浆中的钙离子，主要被何处的钙泵转运","o":["横管","肌膜","线粒体膜","肌质网膜","高尔基体膜"],"a":3,"e":"骨骼肌舒张时胞质Ca²⁺主要被肌质网膜上的钙泵（SERCA）回收，该泵集中分布于肌质网和内质网膜上。横管和肌膜上的钙泵为质膜钙ATP酶，并非回收收缩释放钙的主要部位。"},{"q":"肺气肿患者","o":["肺弹性阻力增大","吸气困难明显","呼气困难明显","吸气时程延长","呼气时程缩短"],"a":2,"e":"肺气肿时肺弹性成分大量破坏，肺回缩力减小、顺应性增大，弹性阻力减小，患者表现为呼气困难。肺充血、纤维化或表面活性物质减少时顺应性降低，才表现为吸气困难。"},{"q":"1位病人检查发现其右心室后负荷明显加重，可能由以下哪个疾病引起","o":["高血压病","心肌梗死","严重贫血","肺梗死","心脏瓣膜关闭不全"],"a":3,"e":"右心室后负荷取决于肺动脉压，肺梗死时肺血管阻力增大、肺动脉压升高，使右心室后负荷加重。高血压病主要加重左心室后负荷，贫血和瓣膜关闭不全属容量负荷或前负荷因素。"},{"q":"第二心音的产生主要由于","o":["房室瓣开放","房室瓣关闭","动脉瓣开放","动脉瓣关闭","乳头肌及腱索的振动"],"a":3,"e":"第二心音主要因主动脉瓣和肺动脉瓣关闭，血流冲击大动脉根部引起振动而产生，标志心室舒张期开始。房室瓣关闭产生第一心音。"},{"q":"人体在运动状态下的主要产热器官是","o":["心脏","肝脏","肾脏","平滑肌","骨骼肌"],"a":4,"e":"运动时骨骼肌成为主要产热器官，其产热量可增至总产热量的73%，剧烈运动时可达90%。安静状态下主要产热器官为内脏，骨骼肌紧张度稍增强即可明显增加产热。"},{"q":"受体阻断剂阻断突触传递的效应，是通过以下何种途径实现的","o":["抑制突触前神经末梢神经递质的释放","抑制DNA转录","与受体结合进而占据受体或改变受体的空间构型","在突触后膜上诱发超极化电位","增强神经递质的降解"],"a":2,"e":"受体阻断剂与受体特异结合后不改变受体生物活性，反因占据受体而对抗激动剂效应，即通过占据受体或改变受体空间构型阻断传递。抑制递质释放、增强递质降解均非受体阻断剂的作用机制。"},{"q":"支配气道平滑肌的副交感神经兴奋将使","o":["平滑肌舒张，气道阻力降低","平滑肌舒张，气道阻力增加","平滑肌舒张，气道阻力不变","平滑肌收缩，气道阻力增加","平滑肌收缩，气道阻力降低"],"a":3,"e":"副交感神经末梢释放ACh作用于气道平滑肌M受体，使平滑肌收缩、气道阻力增加。交感神经末梢释放NE作用于β₂受体则引起气道平滑肌舒张、阻力降低。"},{"q":"当人在紧张的情况下，会出现口干舌燥的感觉，这可能是因为","o":["交感神经兴奋抑制唾液的分泌","交感神经兴奋促进黏稠唾液的分泌","副交感神经兴奋抑制唾液的分泌","前列腺素分泌增加","副交感神经兴奋促进稀薄唾液的分泌"],"a":1,"e":"紧张时交感神经兴奋，促使少量黏稠唾液分泌，故出现口干舌燥感。副交感神经兴奋引起量多而稀薄的唾液分泌，阿托品阻断M受体可抑制唾液分泌。"},{"q":"对冠脉血流量调节的叙述，错误的是","o":["对其调节最重要的是心肌本身的代谢水平","心肌提高从单位血液中摄取氧的潜力小","在代谢产物中腺苷作用最重要","迷走神经兴奋使冠脉扩张","交感神经兴奋只能使冠脉收缩"],"a":4,"e":"交感神经兴奋既激活冠脉平滑肌α受体使之收缩，又通过增强心肌代谢继发性引起冠脉舒张，整体上冠脉血流增高，故“只能使冠脉收缩”错误。冠脉血流主要受心肌代谢水平调节，腺苷是最重要的代谢产物。"},{"q":"当去甲肾上腺素与α受体结合时，下列哪一种肌肉舒张","o":["血管平滑肌","子宫平滑肌","虹膜辐射状肌","胃肠括约肌","小肠平滑肌"],"a":4,"e":"去甲肾上腺素与α2受体结合可使小肠平滑肌舒张。血管、子宫、虹膜开大肌及胃肠括约肌的α受体介导收缩效应。"},{"q":"产生抑制性突触后电位（IPSP）的主要机制是","o":["突触前末梢递质释放减少","突触后膜Ca2+电导降低","突触后膜Na+电导降低","中间神经元受抑制","突触后膜发生超极化"],"a":4,"e":"IPSP是抑制性递质使突触后膜氯通道开放、Cl-内流，引起突触后膜超极化。其本质为超极化突触后电位。"},{"q":"颗粒细胞的主要功能是","o":["感受小管液氢离子浓度的变化","感受小管液NaCl浓度的变化","参与球-管平衡","释放血管紧张素原","释放肾素"],"a":4,"e":"颗粒细胞即球旁细胞，能合成、储存和释放肾素。感受小管液NaCl浓度变化的是致密斑。"},{"q":"下列关于肌梭的描述，正确的是","o":["与梭外肌纤维呈串联关系","适宜刺激是骨骼肌张力的变化","接受α运动神经元的支配","传入纤维有Ⅰa和Ⅰb两类纤维","感受并传入有关肌肉活动状态的信息"],"a":4,"e":"肌梭是长度感受器，其Ⅰa和Ⅱ类传入纤维感受并传入肌肉长度及活动状态的信息。肌梭与梭外肌纤维呈并联关系，受γ运动神经元支配。"},{"q":"女性的基础体温随月经周期而升高，与下列激素可能有关的是","o":["甲状腺激素","肾上腺激素","雌激素","孕激素","糖皮质激素"],"a":3,"e":"排卵后黄体分泌的孕激素作用于下丘脑体温调节中枢，使体温调定点上移，基础体温升高0.3～0.6℃。"},{"q":"与浦肯野细胞相比较，窦房结细胞的跨膜电位的特点是","o":["阈电位绝对值大","0期去极化幅度高","0期去极化速度快","最大复极电位绝对值大","4期自动去极化速度快"],"a":4,"e":"窦房结细胞4期自动去极化速度快，是自律性高的基础。其0期去极化幅度和速度均低于浦肯野细胞，最大复极电位绝对值较小。"},{"q":"肾小管超滤液中氨基酸全部被重吸收的部位是","o":["近曲小管","髓袢降支","髓袢升支","远曲小管","集合管"],"a":0,"e":"氨基酸在近曲小管被全部重吸收。近端小管是重吸收的主要部位，葡萄糖、氨基酸等几乎全部在此重吸收。"},{"q":"急性胰腺炎患者，因持久剧烈腹痛而行禁食和胃肠减压，主要目的是","o":["减少胃蛋白酶分泌","减少胰液分泌","减少胆汁反流","防止胃扩张","防止呕吐"],"a":1,"e":"禁食和胃肠减压可减少胃酸、蛋白质消化产物及脂肪酸对促胰液素和缩胆囊素的刺激，从而减少胰液分泌，使胰腺休息。"},{"q":"阈刺激的概念是","o":["引起组织兴奋的最小刺激强度","引起组织兴奋的最小刺激作用时间","引起组织抑制的最小刺激","引起膜去极化达到阈电位的最小刺激","引起组织抑制的最小刺激作用时间"],"a":3,"e":"阈刺激是强度刚好能使膜由静息电位去极化达到阈电位水平的刺激，故阈刺激即引起膜去极化达阈电位的最小刺激。刺激强度只决定膜电位能否达到阈电位，达到后动作电位幅度与刺激强度无关。"},{"q":"关于分节运动的叙述，错误的是","o":["是一种以环形肌为主的节律性舒缩活动","是小肠所特有的","空腹时即有明显分节运动","分节运动存在频率梯度","不明显的推进食糜"],"a":2,"e":"分节运动在空腹时几乎不存在，食糜进入小肠后才逐步加强，故“空腹时即有明显分节运动”错误。分节运动是以环形肌为主的节律性舒缩，存在由上而下的频率梯度，对食糜推进作用很小。"},{"q":"以下哪项属于负反馈调节的生理过程","o":["分娩","排尿反射","降压反射","动作电位形成","血液凝固"],"a":2,"e":"压力感受性反射是典型的负反馈调节，血压升高时反射性引起血压下降，维持动脉血压稳定。分娩、排尿反射和血液凝固均为正反馈，动作电位形成不属负反馈。"},{"q":"为什么胰液中的蛋白水解酶不会消化胰腺自身","o":["胰液中的胰蛋白水解酶以酶原的形式存在于腺泡细胞及通过导管","磷脂酶A2的激活","碳酸氢盐的分泌","胃蛋白酶原的分泌","缩胆囊素释放"],"a":0,"e":"胰液中的胰蛋白酶和糜蛋白酶均以无活性的酶原形式分泌，进入小肠后由肠激酶激活，故不会消化胰腺自身。磷脂酶A2、碳酸氢盐及缩胆囊素均不涉及此保护机制。"},{"q":"兴奋性突触后电位是发生在","o":["突触前膜上的去极化电位","突触前神经上的锋电位","突触后膜上的去极化电位","突触后神经元上的锋电位","突触后膜上的超极化电位"],"a":2,"e":"兴奋性突触后电位是突触传递在突触后膜引起的去极化电位，由兴奋性递质使Na+内流为主产生。抑制性突触后电位则为突触后膜超极化。"},{"q":"关于糖皮质激素分泌调节的叙述，错误的是","o":["给摘除腺垂体的动物连续注射ACTH可引起肾上腺皮质增生与肥厚","正常情况下，血浆中ACTH和糖皮质激素的水平相平行","长期服用皮质醇可使ACTH分泌增多","应激时ACTH分泌增加几乎全部受控于下丘脑室旁核释放的CRH","应激情况下，ACTH和糖皮质激素的分泌量明显增多"],"a":2,"e":"长期服用皮质醇使血浆糖皮质激素水平升高，通过负反馈抑制腺垂体ACTH分泌，ACTH减少而非增多。正常时ACTH与糖皮质激素水平平行，应激时CRH-ACTH-GC系统活动增强。"},{"q":"依据前列腺素的五碳环构造，目前可以分几种主型","o":["5","6","7","8","9"],"a":4,"e":"依据五碳环构造，前列腺素可分成A～I共九种主型，并含多种亚型。"},{"q":"抑制抗利尿激素释放的主要原因是","o":["血浆晶体渗透压增加","大量出汗","情绪紧张","大量饮水","血浆胶体渗透压升高"],"a":3,"e":"大量饮清水后血液被稀释，血浆晶体渗透压降低，抗利尿激素释放减少，尿量增加。血浆晶体渗透压升高、大量出汗则促进抗利尿激素释放。"},{"q":"基础体温在月经周期中发生变动，这可能与下列哪种激素有关","o":["促肾上腺皮质激素","胰岛素","孕激素","雌激素","甲状腺激素"],"a":2,"e":"孕激素可作用于下丘脑体温调节中枢，使体温调定点水平提高，排卵后孕激素分泌增加使基础体温升高0.2～0.5℃，故基础体温的双相变化与孕激素有关。"},{"q":"脊髓灰质炎患者出现肢体肌肉萎缩的主要原因是","o":["失去神经冲动的影响","因肌肉瘫痪使血供减少所致","肌肉受到病毒的侵害","失去了运动神经的营养作用","失去了神经营养因子的作用"],"a":3,"e":"脊髓灰质炎患者因脊髓前角运动神经元变性死亡，对肌肉失去营养性作用，导致肌肉内糖原合成减慢、蛋白分解加速而逐渐萎缩。"},{"q":"球-管平衡指的是哪一段小管的重吸收规律","o":["近端小管","髓袢","远端小管","集合管","所有肾脏小管节段"],"a":0,"e":"近端小管对Na+和水的重吸收率总是占肾小球滤过率的65%～70%，即定比重吸收，此现象称为球-管平衡，故球-管平衡指近端小管的重吸收规律。"},{"q":"下列关于腱器官的叙述，正确的是","o":["梭外肌纤维发生等长收缩时，腱器官传入冲动发放频率不变","梭外肌纤维发生等张收缩时，腱器官传入冲动发放频率增加","其传入冲动对同一肌肉的α运动神经元起抑制作用","传入神经纤维为Ⅱ类纤维","是一种长度感受器"],"a":2,"e":"腱器官传入神经为Ⅰb类纤维，其传入冲动经抑制性中间神经元对支配同一肌肉的α运动神经元起抑制作用。腱器官感受肌肉张力，与梭外肌纤维呈串联关系。"},{"q":"十二指肠-结肠反射可以","o":["抑制胃液分泌","抑制胃窦运动","抑制结肠运动","增强十二指肠运动","增强结肠运动"],"a":4,"e":"十二指肠-结肠反射由胃内食糜进入十二指肠引起，主要通过内在神经丛传递，可增强结肠运动，常引发集团蠕动。"},{"q":"发热开始时，病人常自感发冷、寒战，最可能的原因是","o":["产热量不足","散热量不足","调定点上移","体温调节机制障碍","皮肤血流量增加"],"a":2,"e":"发热由致热原使体温调定点上移引起，此时实际体温低于调定点，机体出现畏寒、寒战等产热增加、散热减少的反应。"},{"q":"血液中的I-向甲状腺滤泡细胞内转运的方式是","o":["单纯扩散","载体易化扩散","继发性主动转运","原发性主动转运","入胞"],"a":2,"e":"碘捕获由滤泡上皮细胞基底膜的钠碘同向转运体介导，依赖钠泵活动提供的势能，以1I-∶2Na+同向转运方式将I-转运入细胞，属继发性主动转运。"},{"q":"Rh阴性母亲，怀第二胎Rh阳性胎儿时，胎儿最易发生的危险是","o":["血友病","白血病","红细胞增多症","新生儿溶血病","巨幼红细胞性贫血"],"a":3,"e":"Rh阴性母亲第二次妊娠Rh阳性胎儿时，母体内抗Rh抗体可经胎盘进入胎儿体内，引起胎儿红细胞破坏，发生新生儿溶血病。"},{"q":"去极化过程中，Na＋的电化学驱动力","o":["持续增大","持续减小","没有变化","先增大，后变小","先减小，后增大"],"a":1,"e":"去极化时膜电位向Na+平衡电位靠近，Na+的电-化学驱动力绝对值减小。教材示静息时Na+驱动力为-130mV，膜去极化至+30mV时减小为-30mV，故持续减小。"},{"q":"下列关于记忆的描述，哪一项是正确的","o":["陈述性记忆与意识无关","反射性记忆容易遗忘","长时程记忆与海马对信息的加工处理有关","影像记忆属于长时程记忆","非陈述性记忆依赖于海马的功能活动"],"a":2,"e":"长时程记忆的形成是在海马和其他脑区内对信息进行分级加工处理的动态过程，海马受损则短时程记忆不能转变为长时程记忆。陈述性记忆需大脑皮层联络区及海马回路参与，与意识有关。"},{"q":"神经纤维动作电位去极化过程中，膜电位值超过0mV的部分称为","o":["去极化","超极化","复极化","超射","极化"],"a":3,"e":"动作电位去极化超过0mV以上的部分称为超射。神经细胞动作电位升支可上升至约+30mV，该部分即超射。"},{"q":"急性和慢性肾脏损伤时，尿中可出现白蛋白，称白蛋白尿，其出现的原因是","o":["大量的白蛋白从肾小球滤过膜滤过到肾小管","近端小管对白蛋白的重吸收明显减少","远端小管和集合管分泌白蛋白的量明显增加","钠离子主动重吸收障碍，导致其他物质的协同转运降低，包括白蛋白","白蛋白在集合管的重吸收减少"],"a":0,"e":"滤过膜通透性取决于膜孔大小和所带电荷，病理时基底膜负电荷减少或消失，带负电荷的血浆白蛋白可被滤过，出现白蛋白尿。"},{"q":"心脏的重要潜在起搏点是","o":["窦房结","浦肯野细胞","心室肌","左心房肌","右心房肌"],"a":1,"e":"窦房结自律性最高，是正常起搏点；末梢浦肯野细胞自律性最低（约25次/分），是心脏的重要潜在起搏点。"},{"q":"血红蛋白水平为10g/100ml血液，其携氧能力约为","o":["10mlO2 /100ml血液","13mlO2 /100ml血液","16mlO2 /100ml血液","20mlO2 /100ml血液","25mlO2 /100ml血液"],"a":1,"e":"Hb氧容量按每克Hb结合1.34ml O2计算，10g/100ml血液的携氧能力约为13ml O2/100ml血液。"},{"q":"支配汗腺的交感神经末梢释放的神经递质是","o":["乙酰胆碱","去甲肾上腺素","肾上腺素","γ-氨基丁酸","多巴胺"],"a":0,"e":"支配汗腺的交感神经节后纤维末梢释放乙酰胆碱，属交感胆碱能纤维。多数交感节后纤维释放去甲肾上腺素，但汗腺为例外。"},{"q":"神经调节的基本方式是","o":["正反馈","负反馈","前馈","反射","神经-体液调节"],"a":3,"e":"反射是神经调节的基本方式，其结构基础为反射弧。神经调节通过神经反射活动调节机体功能，具有反应迅速、持续时间短、调节精确的特点。"},{"q":"肺通气的直接动力来自","o":["肺内压与跨壁压之间的压力差","胸膜腔内压与跨壁压之间的压力差","胸膜腔内压与大气压之间的压力差","肺内压与大气压之间的压力差","肺内压与胸膜腔内压之间的压力差"],"a":3,"e":"肺泡气与外界大气之间的压力差是实现肺通气的直接动力，呼吸肌运动引起胸廓容积改变是原动力。"},{"q":"胃肠平滑肌收缩的强度主要取决于","o":["慢波频率","慢波的幅度","动作电位的幅度","动作电位的频率","动作电位的时程"],"a":3,"e":"正确答案是动作电位的频率。平滑肌收缩继动作电位之后产生，动作电位频率越高，进入胞质的Ca2+越多，收缩越强；慢波仅为起步电位，决定节律而非收缩强度。"},{"q":"铁被吸收最快的部位是","o":["胃","十二指肠","结肠","回肠","直肠"],"a":1,"e":"正确答案是十二指肠。铁主要在十二指肠及空肠上段以主动转运方式被吸收，十二指肠黏膜吸收能力最强；回肠主要吸收胆盐和维生素B12。"},{"q":"心室肌细胞与浦肯野细胞动作电位的主要区别在于","o":["0期去极化速度与幅度不同","1期复极化的机制不同","平台期复极化的机制不同","3期复极化的机制不同","4期自动去极化的有无"],"a":4,"e":"心室肌细胞无4期自动去极化，浦肯野细胞具有4期自动去极化而具自律性，这是两者动作电位的主要区别。"},{"q":"成年人甲状腺激素分泌不足，可出现下列哪种疾病或症状","o":["呆小症","侏儒症","黏液性水肿","肢端肥大症","水中毒"],"a":2,"e":"正确答案是黏液性水肿。成年人甲状腺激素分泌不足时蛋白质合成减少、组织间黏蛋白沉积并结合大量水和阳离子，引起黏液性水肿；呆小症发生于胚胎期及婴幼儿期。"},{"q":"在蛙坐骨神经-腓肠肌标本的刺激神经观察肌肉收缩实验中，若给予连续刺激，则肌肉收缩容易出现疲劳，其原因是","o":["神经传导的AP幅度越来越小","神经传导AP的频率越来越低","神经-肌接头处兴奋传递的能力越来越弱","肌纤维疲劳，产生AP的能力越来越弱","肌细胞三联管结构的兴奋-收缩耦联能力越来越弱"],"a":2,"e":"正确答案是神经-肌接头处兴奋传递的能力越来越弱。连续刺激时神经纤维可长时间传导兴奋而不易疲劳，疲劳主要发生在化学传递的神经-肌接头，因递质释放能力逐渐减弱。"},{"q":"如果某受试者24小时的耗氧量500L，二氧化碳生成量为390L，尿氮排出量15g。请根据这些数据，计算该受试者1小时的能量代谢量","o":["342、28kJ/h","385、82kJ/h","389、21kJ/h","412、59kJ/h","425、12kJ/h"],"a":3,"e":"正确答案是412.59kJ/h。呼吸商为390/500=0.78，查表得氧热价约19.99kJ/L，500L÷24h×19.99kJ/L≈416kJ/h，与412.59kJ/h最接近。"},{"q":"下列关于胃酸分泌的描述，错误的是","o":["由壁细胞分泌","分泌过程是耗能过程","质子泵在H+分泌中起关键作用","壁细胞分泌HCl增多时，血浆pH将下降","质子泵可被奥美拉唑抑制"],"a":3,"e":"正确答案是壁细胞分泌HCl增多时血浆pH将下降。H+由壁细胞质子泵逆浓度梯度主动分泌，同时HCO3-经基底侧膜入血，故胃酸分泌增多时血浆呈碱性而非pH下降。"},{"q":"血液中二氧化碳的含量主要取决于","o":["二氧化碳分压","氧分压","血液的pH","血液的温度","血红蛋白浓度"],"a":0,"e":"正确答案是二氧化碳分压。CO2在血液中的溶解量及化学结合量均随PCO2升高而增加，PCO2是决定血液CO2含量的主要因素。"},{"q":"关于激素的信息传递作用，下列哪项是正确的","o":["加强或减弱靶组织的生理生化过程","为靶组织活动提供额外能量","为靶组织代谢添加新成分","内分泌系统的信息是电信号","激素可以作为第二信使发挥作用"],"a":0,"e":"正确答案是加强或减弱靶组织的生理生化过程。激素作为化学信使将信息传递给靶细胞，调节其固有的生理生化过程，既不提供额外能量，也不添加新成分。"},{"q":"以下几个方面，哪个方面是动脉血压形成的必要条件","o":["足够的血液充盈","心脏射血","外周阻力","主动脉和大动脉的弹性贮器作用","循环血量与血管容积的比例"],"a":1,"e":"心脏射血是动脉血压形成的必要条件。心室收缩释放的能量一部分推动血液流动，一部分转化为大动脉扩张储存的压强能，故心脏射血是形成动脉血压的必要条件。足够的血液充盈是前提，外周阻力与大动脉弹性贮器作用影响血压数值。"},{"q":"迷走神经对胰腺分泌的调节是","o":["引起酶多、水和碳酸氢根少的分泌","引起水、碳酸氢根多而酶少的分泌","引起水、碳酸氢根和酶均多的分泌","无明显的促进作用","起明显的抑制作用"],"a":0,"e":"迷走神经兴奋引起胰液分泌的特点是水和碳酸氢盐含量很少，而酶的含量却很丰富。迷走神经主要作用于胰腺腺泡细胞，对小导管细胞作用较弱，故酶多而水和HCO3-少。"},{"q":"生理情况下，对收缩压的影响最大的是","o":["心率的变化","每搏输出量的变化","外周阻力的变化","循环血量的变化","大动脉管壁弹性的变化"],"a":1,"e":"每搏输出量的改变主要影响收缩压。搏出量增加时收缩期射入主动脉的血量增多，收缩压明显升高，故收缩压高低主要反映每搏输出量的多少。"},{"q":"在骨骼肌细胞兴奋-收缩耦联过程中，胞质内的钙离子来自","o":["横管膜上电压门控钙离子通道开放引起的胞外钙离子内流","细胞膜上NMDA受体通道开放引起的胞外钙离子内流","肌质网上钙离子释放通道开放引起的胞内钙离子释放","肌质网上钙离子泵的反向转运","线粒体内钙离子的释放"],"a":2,"e":"骨骼肌兴奋-收缩耦联时，肌膜去极化经L型钙通道电压敏感肽段位移，触发肌质网RyR1释放Ca2+，胞质Ca2+主要来自肌质网释放。心肌则依赖细胞外Ca2+内流。"},{"q":"平静呼吸时，无论吸气或呼气，胸膜腔内压均为负值，主要因为","o":["肺的生长速度比胸廓快","胸廓自然容积大于肺的自然容积","肺的回缩力小于胸廓回缩力","肺表面活性物质的作用","胸廓的弹性阻力大于肺内压"],"a":1,"e":"胸廓自然容积大于肺的自然容积，肺始终处于扩张状态，其弹性回缩力使胸膜腔内压保持负值。平静呼吸时肺弹性回缩力一直存在，故胸膜腔内压总为负值。"},{"q":"外界声音通过中耳时，可使声压增加约","o":["1、3倍","3、2倍","17、2倍","22、4倍","55倍"],"a":3,"e":"中耳增压效应由鼓膜面积比与前庭窗面积比（17.2倍）及听骨链杠杆比（1.3倍）共同构成，声波在整个中耳传递过程中增压22.4倍。"},{"q":"红细胞的主要功能是","o":["提供营养","缓冲H＋","运输激素","运输氧气和二氧化碳","运输铁"],"a":3,"e":"红细胞的主要功能是运输O2和CO2。红细胞内富含血红蛋白，能与氧和二氧化碳结合并运输，缓冲H+由血红蛋白等参与但非主要功能。"},{"q":"以下关于真毛细血管特点的叙述错误的是","o":["管壁很薄","管壁通透性大","血流缓慢","管壁内皮细胞有吞饮功能","周期性收缩和舒张"],"a":4,"e":"真毛细血管管壁薄、通透性大、血流缓慢，是血液与组织液进行物质交换的主要场所。周期性收缩和舒张是微动脉及毛细血管前括约肌的特性，真毛细血管本身无此活动。"},{"q":"某人由于外伤导致耳蜗底部受损，出现听力障碍主要是","o":["高频听力","低频听力","中频听力","中、低频听力","高、中频听力"],"a":0,"e":"耳蜗底部受损主要影响高频听力。基底膜不同部位感受不同频率声波，耳蜗底部感受高频、顶部感受低频，故底部受损时高频听力障碍最明显。"},{"q":"治疗中长期大量应用糖皮质激素类制剂对腺垂体的负反馈影响是","o":["LH分泌减少","FSH分泌减少","TSH分泌减少","PRL分泌减少","ACTH分泌减少"],"a":4,"e":"长期大量应用糖皮质激素可通过长反馈抑制下丘脑CRH神经元及腺垂体ACTH细胞，使ACTH合成和分泌减少。ACTH减少进而致肾上腺皮质萎缩、分泌功能减退。"},{"q":"成年人脑电图α波在","o":["安静闭目时出现阻断现象","糖皮质激素血浓度高时频率减慢","高血糖时频率减慢","发热时频率减慢","动脉血二氧化碳分压高时频率减慢"],"a":4,"e":"动脉血PCO2升高时α波频率减慢。血糖、体温、糖皮质激素处于低水平时α波频率也减慢，而安静闭目时α波出现而非阻断。"},{"q":"关于甲状旁腺激素作用的叙述，下列说法错误的是","o":["动员骨钙入血","促进肾小管对Ca2+的重吸收","抑制肾小管对磷的重吸收","抑制1，25-二羟维生素D3的生成","促进小肠对钙磷的吸收"],"a":3,"e":"PTH可诱导肾小管上皮细胞1α-羟化酶基因转录，促进1，25-二羟维生素D3生成，而非抑制。PTH动员骨钙入血、促进肾小管重吸收钙、抑制磷重吸收，并间接促进小肠钙磷吸收。"},{"q":"下列选项的描述不是“膜泡运输”特征的是","o":["批量运输","转运过程不消耗能量","包括入胞和出胞两个过程","转运的是大分子和颗粒物质","运输过程有多种蛋白质参与"],"a":1,"e":"膜泡运输是主动过程，需消耗能量并需多种蛋白质参与，包括出胞和入胞，转运大分子和颗粒物质，属批量运输。"},{"q":"下列哪种情况能使肺的静态顺应性增加","o":["呼吸膜增厚","气道阻力减小","肺惯性阻力减小","肺弹性阻力减小","肺表面活性物质减少"],"a":3,"e":"肺静态顺应性与肺弹性阻力呈反变关系，弹性阻力减小则顺应性增大。呼吸膜增厚、表面活性物质减少均使顺应性降低，气道阻力与惯性阻力不影响静态顺应性。"},{"q":"下列关于肌紧张的叙述，错误的是","o":["缓慢持续牵拉肌肉时发生的牵张反射","是维持躯体姿势的最基本的反射活动","其感受器为肌梭","主要是屈肌表现明显","是多突触反射"],"a":3,"e":"肌紧张是缓慢持续牵拉肌肉时发生的牵张反射，感受器为肌梭，属多突触反射，是维持躯体姿势最基本的反射。肌紧张在伸肌表现明显，而非屈肌。"},{"q":"下列各项中，不属于神经纤维兴奋传导特征的是","o":["完整性","绝缘性","双向性","衰减性","相对不疲劳性"],"a":3,"e":"神经纤维兴奋传导具有完整性、绝缘性、双向性和相对不疲劳性。衰减性传导是局部电位和电紧张电位的特征，不属于神经纤维兴奋传导特征。"},{"q":"红细胞悬浮稳定性降低是由于红细胞出现","o":["聚集","黏着","叠连","凝集","凝固"],"a":2,"e":"红细胞悬浮稳定性降低表现为红细胞叠连，即红细胞以凹面相贴，使总表面积与总体积之比减小、摩擦力减小而沉降加快。叠连快慢取决于血浆成分变化而非红细胞本身。"},{"q":"某患者血沉增快，主要是由于","o":["红细胞脆性增大","血浆中球蛋白和纤维蛋白原含量增多","血浆中白蛋白和卵磷脂含量增多","红细胞内血红蛋白浓度降低","血细胞比容减小"],"a":1,"e":"血浆中纤维蛋白原和球蛋白带正电荷，可中和红细胞表面负电荷而促进叠连，使血沉加快。白蛋白和卵磷脂则抑制叠连、减慢血沉。"},{"q":"酸中毒时远端小管的","o":["钾离子分泌增多，钠离子重吸收增多","钾离子分泌减少，钠离子重吸收减少","钾离子分泌增多，钠离子重吸收减少","钾离子分泌减少，钠离子重吸收增多","钠-氢交换增多，钾-氢交换减少"],"a":1,"e":"酸中毒时肾小管上皮细胞内H+浓度升高，Na+-H+交换增强而Na+-K+交换减弱，故K+分泌减少；同时Na+重吸收随H+分泌增多而减少。"},{"q":"肾脏球旁器的作用包括","o":["选择性地滤过大分子物质","参与血压的调节","主动转运和被动扩散","重吸收（90%溶质）和分泌功能","建立肾脏髓质的渗透梯度"],"a":1,"e":"球旁细胞分泌肾素，启动肾素-血管紧张素系统参与动脉血压和循环血量的调节。滤过、重吸收及髓质渗透梯度分别由滤过膜、肾小管和髓袢完成。"},{"q":"在体内主要依靠糖的无氧酵解供能的组织细胞是","o":["肝细胞","脑细胞","红细胞","骨骼肌","心肌"],"a":2,"e":"成熟红细胞缺乏有氧氧化的酶系，主要依靠糖的无氧氧化供能。脑组织主要依赖葡萄糖有氧氧化供能，缺氧或低血糖时出现功能障碍。"},{"q":"肾小球滤过分数是指","o":["肾小球滤过率和体表面积的比值","肾小球滤过率和肾血流量的比值","肾血浆流量和体表面积的比值","肾小球滤过率和肾血浆流量的比值","肾血流量和体表面积的比值"],"a":3,"e":"滤过分数是肾小球滤过率与肾血浆流量的比值，正常约19%，表示流经肾脏的血浆约有1/5被滤出形成超滤液。"},{"q":"肺活量等于","o":["潮气量＋补吸气量","潮气量＋补呼气量","潮气量＋补吸气量＋补呼气量","潮气量＋功能余气量","余气量＋补吸气量"],"a":2,"e":"肺活量是尽力吸气后尽力呼出的最大气体量，等于潮气量、补吸气量与补呼气量之和，反映肺一次通气的最大能力。"},{"q":"对基础代谢的下列叙述，错误的是","o":["指“基础状态”下的能量代谢","在清晨、清醒、空腹、静卧时测定","在20～25℃环境中，能量代谢最稳定","基础代谢率与体表面积成正比","基础代谢是机体最低的代谢水平"],"a":4,"e":"基础代谢是基础状态下的能量代谢，而人体最低代谢水平出现在熟睡时，故“最低代谢水平”表述错误。基础代谢率与体表面积成正比。"},{"q":"当血流流经下列哪一部分时，血压降落最大","o":["主动脉和大动脉","小动脉和微动脉","微静脉和小静脉","大静脉和腔静脉","毛细血管"],"a":1,"e":"血液流经小动脉和微动脉时血压降落最大。微动脉处血流阻力最大，血压降幅也最显著，是外周阻力的主要部位。"},{"q":"精子在女性生殖道内其功能活性可以保持约","o":["4~8小时","12~24小时","16~36小时","24~48小时","48~72小时"],"a":3,"e":"精子在女性体内或体温环境下功能活性可保持24～48小时，此期间与卵子相遇可发生受精。"},{"q":"在If电流中最重要的跨膜离子流是","o":["逐渐衰减的外向钾离子电流","逐渐增强的内向钠离子电流","通过T型钙离子通道的内向钙离子电流","通过L型钙离子通道的内向钙离子电流","通过由ACh控制的钾离子通道的外向钾离子电流"],"a":1,"e":"If电流即超极化激活的内向离子电流，主要由Na+内流形成，表现为逐渐增强的内向钠电流，参与窦房结P细胞4期自动去极化。"},{"q":"调节呼吸运动最重要的生理因素是","o":["CO2","O2","H＋","2，3-DPG","CO"],"a":0,"e":"CO2是调节呼吸最重要的生理性化学因素，动脉血必须保持一定PCO2，呼吸中枢才能维持正常兴奋性。"},{"q":"交感神经的“紧张性活动”是指它在","o":["精神紧张时产生的一定频率的冲动","身体剧烈运动时产生的电位改变","内脏平滑肌受牵拉时产生的电位改变","血管平滑肌受牵拉时产生的一定频率的冲动","在安静状态下自主神经系统持续发放一定频率的冲动"],"a":4,"e":"紧张性活动指安静状态下自主神经系统持续发放一定频率冲动，使所支配器官处于一定程度的活动状态。"},{"q":"糖类、蛋白质和脂肪的消化产物大部分被吸收的部位是","o":["十二指肠","空肠及回肠","十二指肠和空肠","十二指肠、空肠及回肠","回肠"],"a":2,"e":"糖类、蛋白质和脂肪的消化产物大部分在十二指肠和空肠被吸收，回肠是吸收功能的储备部分。"},{"q":"下列关于胰岛激素相互作用的叙述，错误的是","o":["胰岛素抑制胰高血糖素的分泌","胰高血糖素抑制胰岛素的分泌","生长抑素抑制胰高血糖素的分泌","促胰液素、抑胃肽促进胰岛素分泌","生长抑素抑制胰岛素的分泌"],"a":1,"e":"胰高血糖素可直接作用于β细胞促进胰岛素分泌，并非抑制。胰岛素和生长抑素均直接抑制α细胞分泌胰高血糖素。"},{"q":"引起生长激素分泌作用最强的因素是","o":["高血糖","低血糖","高血脂","低血脂","血中氨基酸浓度增高"],"a":1,"e":"低血糖是刺激生长激素分泌作用最强的因素，其通过降低血糖反射性促进生长激素释放。"},{"q":"下列属于快适应感受器的是","o":["肌梭","关节囊感受器","环层小体","颈动脉体化学感受器","颈动脉窦压力感受器"],"a":2,"e":"环层小体属于快适应感受器，受到持续刺激时仅在短时间内发放传入冲动，随后冲动频率迅速降低甚至消失。肌梭、关节囊感受器、颈动脉体化学感受器和颈动脉窦压力感受器均属慢适应感受器。"},{"q":"下列关于壁细胞质子泵的叙述，错误的是","o":["存在于顶端膜内凹的分泌小管膜上","是一种氢-钾依赖式的ATP酶","抑制质子泵不影响胃酸的分泌","分泌氢离子同时伴有钾离子进入细胞","分泌氢离子同时伴有碳酸氢根移出细胞"],"a":2,"e":"壁细胞顶端分泌小管膜上的质子泵即H⁺，K⁺-ATP酶，可逆浓度梯度分泌H⁺并摄入K⁺，是胃酸分泌的关键环节。奥美拉唑等质子泵抑制剂特异性抑制该泵，从而阻断胃酸分泌。"},{"q":"患者血浆白蛋白低于30g/L，出现水肿，其主要原因是","o":["毛细血管的通透性增加","组织液胶体渗透压下降","血浆胶体渗透压下降","血浆晶体渗透压下降","淋巴回流增加"],"a":2,"e":"血浆胶体渗透压主要取决于血浆蛋白尤其是白蛋白浓度。白蛋白低于30g/L时血浆胶体渗透压降低，有效胶体渗透压下降，有效滤过压增大，组织液生成增多而出现水肿。"},{"q":"关于Na＋泵生理作用的描述，不正确的是","o":["产生内向电流","将Na＋移出膜外，将K＋移入膜内","建立势能储备","细胞外高Na＋可维持细胞内外正常渗透压","细胞内高K＋可保证细胞代谢反应的正常进行"],"a":0,"e":"Na⁺泵每分解一分子ATP将3个Na⁺移出膜外、2个K⁺移入膜内，属生电性泵，产生外向电流而非内向电流。其转运建立Na⁺、K⁺跨膜浓度势能储备，并维持细胞内外渗透压和细胞代谢。"},{"q":"孕妇使用PGE2易导致流产，主要原因是由于","o":["PGE2会增加子宫收缩","PGE2会增加胎盘主动脉收缩","PGE2可以刺激催产素的释放","PGE2可以增加孕酮的分泌","PGE2可以增加雌激素的分泌"],"a":0,"e":"PGE2对子宫平滑肌有兴奋作用，可增强子宫收缩，妊娠期使用易引起流产。教材指出PGE2舒血管、抑制胃酸分泌、增加肾血流量，未提及其刺激催产素或孕、雌激素分泌。"},{"q":"以下心肌组织中，不具有自动节律性的细胞是","o":["窦房结P细胞","心房肌细胞","浦肯野细胞","房室结细胞","房室束细胞"],"a":1,"e":"心房肌细胞属工作细胞，无自动节律性；窦房结P细胞、房室结细胞、房室束细胞和浦肯野细胞均属特殊传导系统自律细胞，具有自动节律性。"},{"q":"肺表面活性物质减少将导致","o":["肺难以扩张","小肺泡内压小于大肺泡内压","肺弹性阻力减小","肺泡表面张力降低","肺顺应性增加"],"a":0,"e":"肺表面活性物质降低肺泡表面张力，增大肺顺应性、减小弹性阻力。其减少时表面张力升高，肺回缩力增大、顺应性降低，肺泡趋于萎陷，肺难以扩张。"},{"q":"在下列类型心肌细胞中，属于快反应自律细胞的是","o":["窦房结P细胞","心房肌细胞","心室肌细胞","浦肯野细胞","房室结细胞"],"a":3,"e":"浦肯野细胞兴奋时产生快反应动作电位，0期由快钠通道介导、去极化速率快，同时具有4期自动去极化，属快反应自律细胞。窦房结和房室结细胞为慢反应自律细胞，心房肌、心室肌为快反应工作细胞。"},{"q":"正常人心率超过180次/分时，心输出量减少的原因主要是","o":["快速射血期缩短","减慢射血期缩短","心室充盈期缩短","心室肌氧气供应不足","经减压反射调节后心肌收缩能力减弱"],"a":2,"e":"心率超过180次/分时，心室舒张期明显缩短，充盈量显著减少，搏出量随之下降，心输出量减少。教材指出心率过快使心室舒张期明显缩短、充盈量明显减少是心输出量下降的原因。"},{"q":"红细胞所需的能量主要来自","o":["葡萄糖的有氧氧化","糖异生","糖原分解","糖酵解","脂肪酸氧化"],"a":3,"e":"成熟红细胞无线粒体，不能进行有氧氧化，糖酵解是其获得能量的唯一途径，所产ATP用于维持钠泵活动和细胞形态。"},{"q":"高浓度降钙素迅速降低血钙水平的作用环节是","o":["抑制肾小管对钙的重吸收","抑制破骨细胞溶骨活动","刺激骨细胞的分化","甲状旁腺激素分泌减少","减少小肠吸收钙"],"a":1,"e":"降钙素与破骨细胞受体结合后，经AC-cAMP通路迅速抑制破骨细胞活动，减弱溶骨过程，减少骨钙释放，从而快速降低血钙。抑制肾小管重吸收钙和减少小肠吸收钙并非其快速降钙的主要环节。"},{"q":"体内调节血钙水平最重要的激素是","o":["甲状旁腺激素","甲状腺激素","醛固酮","糖皮质激素","生长素"],"a":0,"e":"甲状旁腺激素是调节血钙水平最重要的激素，通过促进肾小管重吸收钙和促进骨钙入血升高血钙，血钙降低又可促进其分泌。甲状腺激素、醛固酮、糖皮质激素和生长素均非血钙调节的主要激素。"},{"q":"终尿中的钾离子主要是由","o":["肾小管滤过","近曲小管分泌","髓袢降支分泌","髓袢升支分泌","远曲小管和集合管分泌"],"a":4,"e":"终尿中的钾离子主要由远曲小管和集合管主细胞分泌，该部位对Na+、K+、Cl-通透性低，分泌的K+不易返回小管液。近曲小管和髓袢主要重吸收钾，滤过的钾绝大部分被重吸收。"},{"q":"神经干中许多纤维同时传导兴奋时互不干扰的主要原因是","o":["髓鞘的绝缘作用","细胞膜电阻很大","细胞外液的短路作用","跨膜电流很小","不同纤维的传导速度不等"],"a":2,"e":"神经干内多条纤维同时传导兴奋互不干扰，是因为局部电流在细胞外液中均匀分散并迅速衰减，效应如同接地，即细胞外液的短路作用。髓鞘绝缘作用只存在于有髓纤维，并非神经干内各纤维互不干扰的主要原因。"},{"q":"声波经过鼓膜时","o":["改变进入中耳的声波频率","可减小声波的声压","若咽鼓管阻塞，鼓膜将趋于向外凸出","鼓膜实际振动面积与前庭窗大致相等","几乎与声波振动同始同终"],"a":4,"e":"鼓膜具有较好的频率响应和较小失真度，当频率低于2400Hz的声波作用时，其振动与声波振动同始同终。鼓膜本身不改变声波频率，也不减小声压。"},{"q":"下列哪项不是甲状腺激素的作用","o":["分泌过多时，蛋白质合成增加","提高神经系统的兴奋性","促进骨骼和脑的生长发育","使心跳加快加强","生理剂量可以促进蛋白质合成"],"a":0,"e":"甲状腺激素分泌过多时促进蛋白质分解，表现为负氮平衡，而非蛋白质合成增加。生理剂量促进蛋白质合成，并提高神经系统兴奋性、促进骨骼和脑发育、使心跳加快加强。"},{"q":"在体内，主要用于供能的营养物质是","o":["糖、脂肪与蛋白质","糖与蛋白质","脂肪与蛋白质","脂肪与核酸","糖与脂肪"],"a":4,"e":"糖和脂肪是体内主要的供能物质，蛋白质主要在长期不能进食等特殊情况下分解供能，故主要用于供能的是糖与脂肪。"},{"q":"下列哪一项不符合终板电位的特性","o":["没有“全或无”现象","由ACh受体激活引起","可以总和","呈电紧张性扩布","由钙离子内流形成"],"a":4,"e":"终板电位由骨骼肌终板膜ACh受体激活引起，属局部电位，无全或无现象、可总和、呈电紧张性扩布。其形成是Na+内流（兼有K+外流）所致，并非钙离子内流。"},{"q":"当流经致密斑的小管液流量增加时，管-球反馈使得","o":["同一肾单位的肾小球滤过率下降","同一肾单位的肾小球血流量增加","肾素分泌增加","近端小管对水和溶质的重吸收减少","肾交感神经兴奋"],"a":0,"e":"流经致密斑的小管液流量增加时，致密斑感受到NaCl浓度升高，通过管-球反馈使入球小动脉收缩，同一肾单位的肾小球滤过率下降。肾素释放减少而非增加。"},{"q":"生物活性最高的维生素D3是","o":["24，25-(OH)2-D3","1，25-(OH)2-D3","25-(OH)-D3","7-脱氢胆固醇","25-脱氢胆固醇"],"a":1,"e":"维生素D3需经肝25-羟化生成25-(OH)-D3，再经肾1α-羟化酶作用生成1，25-(OH)2-D3，后者生物活性最高。"},{"q":"如果窦房结突然停止起搏，最先恢复起搏的部位是","o":["心房肌","心室肌","房室结","房室束","浦肯野细胞"],"a":2,"e":"窦房结自律性最高（约100次/分），房室结次之（约50次/分），故窦房结停搏后房室结最先恢复起搏。浦肯野细胞自律性最低。"},{"q":"抑制性突触后电位导致突触后神经元活动减弱的原因在于","o":["突触前神经元活动减弱","兴奋性突触释放递质量减少","后膜电位超极化","轴丘始段去极化","后膜电位去极化"],"a":2,"e":"抑制性突触后电位是抑制性递质使突触后膜氯通道开放、Cl-内流引起的超极化，使突触后神经元兴奋性降低、活动减弱。"},{"q":"不属于第二信使的物质是","o":["cGMP","cAMP","ADP","DG","Ca2+"],"a":2,"e":"ADP是血小板致密体释放的致聚剂，不属于第二信使；cGMP、cAMP、DG和Ca2+均为细胞内第二信使。"},{"q":"去甲肾上腺素与β受体结合后引起收缩或收缩加强的肌组织是","o":["心房肌","子宫平滑肌","小肠平滑肌","血管平滑肌","支气管平滑肌"],"a":0,"e":"去甲肾上腺素与心肌β1受体结合产生正性变力作用，使心房肌收缩加强。β2受体介导支气管和血管平滑肌舒张，α受体介导血管收缩。"},{"q":"关于耳蜗微音器电位，正确的是","o":["其电位随着刺激强度的增加而减小","是多个毛细胞在接受声音刺激时所产生的感受器电位的复合表现","有较长的潜伏期和不应期","易疲劳","在人和动物的听域范围内无法重复声波的频率"],"a":1,"e":"耳蜗微音器电位是多个毛细胞受声音刺激时产生的感受器电位的复合表现，无真正阈值、无潜伏期和不应期、不易疲劳，并能重复声波频率。"},{"q":"髓袢升支粗段对钠离子、氯离子和钾离子主动重吸收的比例是","o":["2∶1∶1","1∶2∶1","1∶1∶1","1∶1∶2","3∶2∶1"],"a":1,"e":"髓袢升支粗段顶端膜上的Na+-K+-2Cl-共转运体按1∶2∶1的比例主动重吸收Na+、Cl-和K+。"},{"q":"突触后神经元兴奋时，动作电位首先在轴突始段爆发的原因是","o":["此处的EPSP幅度大","EPSP总和仅发生于此处","此处的细胞膜电阻小","此处阈电位靠近静息电位","此处电压门控钠通道密度大"],"a":4,"e":"轴突始段膜上电压门控钠通道分布密度极高，较小的去极化即可形成较大Na+电流，使该处阈电位明显低于其他部位，最易爆发动作电位。胞体和树突膜钠通道密度低，其EPSP一般不能引起动作电位。"},{"q":"Na+重吸收受醛固酮调节的部位是","o":["近端小管","髓袢降支粗段","远端小管、集合管","髓袢升支粗段","髓袢降支细段"],"a":2,"e":"醛固酮作用于远端小管和集合管上皮细胞，促进Na+重吸收并增加K+分泌。近端小管重吸收约65%～70%的Na+，但不受醛固酮调节。"},{"q":"正常人在下列各种情况下能量代谢水平最低的是","o":["安静状态","心算","散步","劳动","基础状态"],"a":4,"e":"基础状态下的能量代谢即基础代谢，是人体清醒时的最低能量代谢水平，低于一般安静状态。心算、散步、劳动均使代谢率升高。"},{"q":"关于人在单位时间内的能量代谢率，下列哪项叙述是错误的","o":["与体表面积成正比","随着劳动强度的加大而增加","始终随着外界温度的升高而减少","与年龄有关","与性别有关"],"a":2,"e":"能量代谢率随外界温度变化呈先降后升的关系，在20～30℃时最低，寒冷和高温均使其升高，并非始终随温度升高而减少。能量代谢率与体表面积成正比，并受劳动强度、年龄和性别影响。"},{"q":"当肺容量小于肺总量的67%时","o":["胸廓以其弹性向外扩展，肺的弹性回缩力消失","胸廓以其弹性向内回缩，肺的弹性回缩力向内","胸廓以其弹性向外扩展，肺的弹性回缩力向内","胸廓以其弹性向内回缩，肺的弹性回缩力消失","胸廓的弹性作用消失，肺的弹性回缩力向内"],"a":2,"e":"肺容量小于肺总量的67%时，胸廓被牵引向内缩小，其弹性阻力向外，成为吸气的动力；肺始终处于扩张状态，弹性回缩力向内。"},{"q":"以下属于运动单位概念范畴的结构是","o":["α运动神经元","核袋纤维","核链纤维","γ运动神经元","β运动神经元"],"a":0,"e":"运动单位由一个α运动神经元及其所支配的全部肌纤维组成，是躯体运动反射的最后公路。γ运动神经元调节肌梭敏感性，核袋纤维和核链纤维属肌梭内结构。"},{"q":"可被胃黏膜吸收的物质是","o":["糖的消化产物","维生素","水和酒精","肽类物质","无机盐"],"a":2,"e":"胃黏膜可吸收水和酒精，酒精及少量水在胃内即被吸收。糖的消化产物、维生素和无机盐主要在小肠吸收。"},{"q":"神经细胞动作电位和局部兴奋的共同点是","o":["反应幅度都随刺激强度增大而增大","反应幅度都随传播距离增大而减小","都可以叠加或总和","都有不应期","都有钠离子通道的激活"],"a":4,"e":"动作电位和局部电位均由电压门控钠通道激活开放、Na+内流引起去极化而产生。局部电位幅度随刺激强度增大、随传播距离减小并可总和，动作电位则具有不应期。"},{"q":"一般情况下，神经细胞的阈电位绝对值较其静息电位绝对值","o":["小40～50mV","小10～20mV","接近静息电位水平","大10～20mV","大40～50mV"],"a":1,"e":"阈电位比静息电位小10～20mV，即其绝对值较静息电位绝对值小10～20mV，如神经细胞静息电位-70mV、阈电位约-55mV。"},{"q":"丘脑的特异投射系统的主要作用是","o":["协调肌紧张","维持觉醒","调节内脏功能","引起特定的感觉","引起牵涉痛"],"a":3,"e":"特异投射系统点对点投射至大脑皮层特定区域，引起特定感觉。非特异投射系统无专一感觉传导功能，其作用是维持和改变大脑皮层兴奋状态。"},{"q":"神经纤维中相邻两个锋电位，其中后一个锋电位最早见于前一次兴奋的","o":["绝对不应期","相对不应期","超常期","低常期","兴奋性恢复正常后"],"a":1,"e":"绝对不应期内任何刺激均不能引起新的动作电位，故后一锋电位最早见于相对不应期，此时给予足够强的阈上刺激可产生动作电位。"},{"q":"长期使用糖皮质激素治疗，停药时应注意","o":["检查患者血细胞","检查胃黏膜有无损伤","补充蛋白质","逐渐减量停药","避免各种伤害性刺激"],"a":3,"e":"长期使用糖皮质激素可致肾上腺皮质萎缩，突然停药会因体内GC骤减出现急性肾上腺皮质功能减退，故应逐渐减量停药或间断补充ACTH。"},{"q":"进食引起的唾液分泌属于","o":["神经调节","体液调节","神经和体液双重调节","正反馈调节","负反馈调节"],"a":0,"e":"唾液分泌主要依靠神经调节，包括条件反射和非条件反射；食物对口腔黏膜的机械、化学和温热刺激引起的分泌属非条件反射。"},{"q":"甲状腺激素合成过程中，由TSH调节的关键酶是","o":["脱碘酶","蛋白水解酶","过氧化物酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"甲状腺过氧化物酶（TPO）是催化甲状腺激素合成的关键酶，由TSH调节。脱碘酶参与碘回收，蛋白水解酶水解释放T4、T3。"},{"q":"正常人红细胞在不同浓度的低渗盐溶液中形态不同。在0、5%NaCl溶液中红细胞的形态是","o":["正常","膨胀","缩小","破裂","先缩小后破裂"],"a":1,"e":"红细胞在低渗NaCl溶液中水渗入细胞内而膨胀，0.5%NaCl低于0.9%等渗浓度但高于0.42%～0.46%的溶血阈值，故红细胞膨胀而不破裂。"},{"q":"生活在高原地区的人，检测其血红蛋白氧饱和度达到90%以上，该地区的PO2大于","o":["60mmHg","70mmHg","80mmHg","90mmHg","100mmHg"],"a":0,"e":"PO2降至60mmHg时Hb氧饱和度约为90%，只要动脉血PO2不低于60mmHg，Hb氧饱和度仍能维持在90%以上，故该地区PO2大于60mmHg。"},{"q":"下列关于心输出量的说法错误的是","o":["心肌收缩力增强会增加心输出量","心交感神经兴奋会增加心输出量","左心室壁运动异常会增加心输出量","心输出量是每分钟左心室所泵出的血量","最大心输出量与安静时心输出量之差等于心力贮备"],"a":2,"e":"左心室壁运动异常使心肌收缩力减弱、搏出量减少，心输出量降低。心输出量等于心率与搏出量之积，心肌收缩力增强和心交感神经兴奋均使搏出量增加；心力贮备即最大心输出量与安静时心输出量之差。"},{"q":"下列关于氯离子在近端小管重吸收的描述，正确的是","o":["主要发生在近曲小管","与碳酸氢根重吸收竞争转运体","主要通过细胞旁路重吸收","顺浓度和电位梯度而重吸收","优先于碳酸氢根的重吸收"],"a":2,"e":"近端小管后半段因Cl-被动扩散造成管内外电位差，驱使小管液中Na+和Cl-经细胞旁途径被动重吸收，故Cl-重吸收主要通过细胞旁路。近端小管对HCO3-的重吸收优先于Cl-，两者不竞争同一转运体。"},{"q":"下列哪项不是糖皮质激素的生理作用","o":["使血中嗜酸性粒细胞增加","促进肝外蛋白质分解","促进四肢脂肪分解","增强机体对有害刺激的耐受力","增加胃酸和胃蛋白酶的分泌"],"a":0,"e":"糖皮质激素使附着于血管壁的中性粒细胞入血而增多，同时促进淋巴细胞与嗜酸性粒细胞在脾和肺破坏，使嗜酸性粒细胞减少。GC促进肝外蛋白质分解、四肢脂肪分解，并增强机体对有害刺激的耐受力、增加胃酸和胃蛋白酶分泌。"},{"q":"胃黏膜长期处于高酸和胃蛋白酶的环境中，却不会被消化，这是由于存在着自我保护机制。这个机制主要是","o":["黏液屏障","黏液细胞保护","黏液凝胶层保护","黏液-碳酸氢盐屏障","碳酸氢盐屏障"],"a":3,"e":"胃黏膜非泌酸细胞分泌的HCO3-与表面黏液联合形成黏液-碳酸氢盐屏障，有效保护胃黏膜免受胃内盐酸和胃蛋白酶的损伤。胃黏膜屏障由上皮顶端膜与相邻细胞侧膜的紧密连接构成，防止H+向细胞内扩散。"},{"q":"葡萄糖在小肠黏膜上皮处的吸收是通过继发性主动转运实现的，抑制下列哪种功能活动可以影响该葡萄糖的吸收","o":["钠泵","钙泵","质子泵","钠钙交换体","钠氢交换体"],"a":0,"e":"小肠葡萄糖吸收由钠-葡萄糖同向转运体介导，属继发性主动转运，其能量来自钠泵活动造成的细胞内低Na+和跨膜电化学梯度。抑制钠泵后该梯度消失，葡萄糖吸收随之减弱。"},{"q":"静息心指数等于","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","每搏输出量/体表面积","心室舒张末期容积/体表面积","每分功/体表面积"],"a":1,"e":"以单位体表面积计算的心输出量称为心指数，安静空腹时测定的为静息心指数，正常约3.0～3.5L/(min·m²)。心输出量等于心率与搏出量的乘积。"},{"q":"神经激素是","o":["作用于神经细胞的激素","具有酶功能的神经递质","神经内分泌细胞分泌的激素","具有神经功能的激素","使神经兴奋的激素"],"a":2,"e":"神经激素指下丘脑神经内分泌细胞合成并分泌的激素，经垂体门脉或轴突运输作用于靶细胞。这类细胞具有神经元和内分泌细胞双重特征，将神经信号转变为化学信号。"},{"q":"cAMP作为第二信使主要是激活","o":["AC","PLC","PKA","PKC","PKG"],"a":2,"e":"cAMP作为第二信使主要激活cAMP依赖性蛋白激酶即蛋白激酶A（PKA），后者以丝氨酸/苏氨酸蛋白激酶方式使底物蛋白磷酸化而发挥效应。AC是cAMP的生成酶，PLC、PKC、PKG属其他信号通路。"},{"q":"以下按研究器官、系统划分的生理学科为","o":["植物生理学","人体生理学","电生理学","高原生理学","心血管生理学"],"a":4,"e":"按研究的器官、系统划分，生理学分为神经生理学、心血管生理学、消化生理学、肾脏生理学等，心血管生理学属此类。植物生理学、人体生理学按研究对象划分，高原生理学按环境状态划分。"},{"q":"下列关于经典突触的描述，正确的是","o":["属于非定向化学性突触","含各类递质的突触小泡无形态差异","各类递质均在激活区释放","激活区位于前膜上对应于后膜受体的位置","后膜受体都是化学门控通道"],"a":4,"e":"经典突触属定向化学传递，激活区位于前膜上正对后膜受体的部位，保证递质集中作用于受体。非定向突触才无经典结构；递质小泡形态因递质种类而异；后膜受体并非均为化学门控通道。"},{"q":"人类小脑损伤，不会出现的症状是","o":["小脑性共济失调","肌张力降低","安静时出现震颤，做精细运动时震颤消失","身体平衡失调","位置性眼震颤"],"a":2,"e":"小脑损伤表现为意向性震颤，即动作过程中及终末出现震颤，安静时减轻。小脑性共济失调、肌张力降低、平衡失调及位置性眼震颤均为小脑损伤表现。"},{"q":"临床上给患者补液时，容易被遗漏计入的体液丢失部分是","o":["腹泻","呕吐","不感蒸发","尿多","发汗"],"a":2,"e":"不感蒸发是皮肤和呼吸道黏膜不断渗出并汽化的水分，与汗腺活动无关，易被忽略。临床补液须计入这部分丢失量，婴幼儿不感蒸发速率大更易脱水。"},{"q":"缺乏肺泡表面活性物质的患者和肺纤维化的患者他们之间的不同点是","o":["肺顺应性降低","肺活量减少","肺泡稳定性降低","呼吸功增加","胸膜腔内压降低"],"a":2,"e":"肺表面活性物质密度随肺泡半径变化而改变，可稳定肺泡内压、防止萎陷或过度膨胀，故缺乏时肺泡稳定性降低。肺纤维化与表面活性物质缺乏均致肺顺应性降低、呼吸功增加。"},{"q":"缺氧使呼吸活动增强，主要通过刺激下列哪一部位而实现","o":["延髓呼吸中枢","中枢化学敏感区","颈动脉窦和主动脉弓","脑桥呼吸中枢","颈动脉体和主动脉体"],"a":4,"e":"缺氧刺激外周化学感受器颈动脉体和主动脉体，经窦神经和迷走神经传入，反射性增强呼吸。颈动脉体主要参与呼吸调节；中枢化学感受器对缺氧不敏感。"},{"q":"以下不属于本能行为的活动是","o":["咳嗽反射","饮水","摄食","性行为","睡眠"],"a":0,"e":"咳嗽反射是呼吸道黏膜受刺激引起的防御性呼吸反射，属后天获得的反射活动。饮水、摄食、性行为及睡眠均为本能行为。"},{"q":"下列关于受精的叙述，错误的是","o":["精子在雌性生殖道内完成获能反应","获能后的精子具有穿透卵透明带的能力","子宫腔内获能的精子释放出多种蛋白酶水解卵透明带","顶体反应是受精的关键环节","精子进入卵细胞激发卵细胞完成第二次减数分裂"],"a":2,"e":"顶体反应发生在输卵管壶腹部，获能精子与卵子相遇后释放顶体酶水解放射冠和透明带，而非在子宫腔内。精子获能于女性生殖道完成，进入卵子可激发卵细胞完成第二次减数分裂。"},{"q":"关于感觉的非特异投射系统功能的正确描述是","o":["维持和改变大脑皮层的兴奋状态","抑制大脑皮层的活动","提高大脑皮层特异感觉的阈值","对大脑皮层活动无影响","激动大脑皮层产生特定感觉"],"a":0,"e":"非特异性投射系统弥散投射至大脑皮层广泛区域，功能是维持和改变大脑皮层兴奋状态，不能引起特定感觉。特异性投射系统才产生特定感觉。"},{"q":"关于受体的叙述，下列哪一项是错误的","o":["胆碱能受体包括M型和N型","肾上腺素能受体包括α型和β型","N型受体与乙酰胆碱结合后使骨骼肌收缩","M型受体与乙酰胆碱结合后使心脏活动增强","α型受体与去甲肾上腺素结合后使血管平滑肌收缩"],"a":3,"e":"M型受体属胆碱能受体，乙酰胆碱与之结合产生副交感样效应，使心率减慢、心肌收缩力减弱，而非心脏活动增强。N2受体是骨骼肌终板膜的配体门控阳离子通道，ACh结合后开放引起终板电位而致骨骼肌收缩。"},{"q":"肾上腺皮质功能亢进时，可发生","o":["侏儒症","水中毒","向心性肥胖","肢端肥大症","呆小症"],"a":2,"e":"肾上腺皮质功能亢进或大剂量应用GC时，脂肪重新分布，沉积于面、颈、躯干和腹部而四肢减少，形成满月脸、水牛背及向心性肥胖。侏儒症与呆小症为生长发育障碍，肢端肥大症由GH过多引起。"},{"q":"分泌胰岛素的B细胞约占胰岛细胞总数的","o":["小于1%","0、05","0、2","0、6","0、75"],"a":3,"e":"胰岛β（B）细胞分泌胰岛素，约占胰岛细胞总数的60%。α（A）细胞分泌胰高血糖素，约占25%。"},{"q":"自身调节指组织、细胞在不依赖于神经或体液调节的情况下对刺激所产生的","o":["适应性反应","旁分泌反应","稳态反应","非自控调节","前馈调节"],"a":0,"e":"自身调节指某些细胞或组织器官凭借本身内在特性，不依赖神经和体液调节，对内环境变化产生特定适应性反应，如肾入球小动脉的肌源性调节。"},{"q":"肾脏髓质渗透压梯度的维持主要靠","o":["小叶间动脉","髓袢","弓形动脉","弓形静脉","直小血管"],"a":4,"e":"直小血管降支与升支并行形成逆流交换系统，仅将髓质间液中多余的溶质和水带回血液，使NaCl和尿素在升降支间循环，从而维持髓质间液高渗梯度。"},{"q":"下列哪种激素是神经激素","o":["抗利尿激素","肾上腺素","促甲状腺激素","催乳素","甲状腺激素"],"a":0,"e":"抗利尿激素由下丘脑视上核和室旁核神经元合成，经轴突运输至神经垂体释放，属神经激素。肾上腺素为肾上腺髓质激素，促甲状腺激素和催乳素为腺垂体激素，甲状腺激素为甲状腺滤泡上皮分泌。"},{"q":"肾上腺皮质功能减退时可出现","o":["血容量增多","血容量减少","血浆钠浓度升高","血浆钾浓度降低","血压升高"],"a":1,"e":"肾上腺皮质功能减退时醛固酮和糖皮质激素不足，肾小管保钠排钾作用减弱，钠和水排出增多，导致血容量减少、血浆钠降低、血钾升高及血压下降。"},{"q":"下列关于消化道平滑肌基本电节律的论述，错误的是","o":["在胃肠不收缩的情况下，也可记录到基本电节律","基本电节律的波幅和频率与平滑肌组织的种类无关","基本电节律起源于环行肌与纵行肌层之间的间质细胞","基本电节律的产生是肌源性的","动作电位是在基本电节律的基础上产生的"],"a":1,"e":"消化道不同部位平滑肌的慢波频率不同，胃约每分钟3次、十二指肠约12次、回肠末端8～9次，故波幅和频率与平滑肌组织种类有关。慢波为肌源性起步电位，不伴收缩时仍可记录到，动作电位在其去极化基础上产生。"},{"q":"下列哪种情况能使血管升压素释放增加","o":["高钾饮食","大量饮清水","刺激颈动脉窦","刺激颈动脉体","大量出汗"],"a":4,"e":"大量出汗使机体失水多于失钠，血浆晶体渗透压升高，刺激渗透压感受器，促进神经垂体释放血管升压素。大量饮清水则使血浆晶体渗透压降低，血管升压素释放减少。"},{"q":"平静呼吸时，肺内压在下列哪一时相内等于大气压","o":["吸气中和呼气中","吸气中和呼气末","吸气末和呼气中","吸气末和呼气末","呼气中和呼气末"],"a":3,"e":"吸气末和呼气末肺内压均与大气压相等，气流暂停。平静呼吸时吸气中肺内压低于大气压，呼气中高于大气压。"},{"q":"睾丸支持细胞合成分泌的（ ）与腺垂体FSH分泌的负反馈调节有关","o":["抑制素","激活素","雄激素","前列腺素","孕激素"],"a":0,"e":"睾丸支持细胞在FSH作用下分泌抑制素，选择性抑制腺垂体FSH的合成和分泌，对LH无显著影响。睾酮则负反馈抑制LH和GnRH。"},{"q":"下列关于胃黏液-碳酸氢盐屏障的叙述，错误的是","o":["与胃黏膜屏障是同一概念","由黏液及胃黏膜分泌的碳酸氢根组成","使胃黏膜表面处于中性或偏碱性状态","防止胃酸及胃蛋白酶对胃黏膜的侵蚀","保护胃黏膜免受食物的摩擦损伤"],"a":0,"e":"黏液-碳酸氢盐屏障由黏液与胃黏膜非泌酸细胞分泌的HCO3-构成，使黏膜表面呈中性或偏碱性，保护黏膜免受胃酸和胃蛋白酶侵蚀。胃黏膜屏障指上皮细胞间的紧密连接，两者并非同一概念。"},{"q":"丘脑特异感觉接替核中躯体感觉的中继站是","o":["内侧膝状体","外侧膝状体","后腹核","丘脑外侧核","丘脑前核"],"a":2,"e":"丘脑后腹核是躯体感觉的中继站，其中后外侧腹核接受躯干四肢传入纤维，第三级神经元由此投射到皮层躯体感觉区。内侧膝状体和外侧膝状体分别中继听觉和视觉。"},{"q":"近端小管重吸收的特点是","o":["重吸收的物质种类少","各种物质重吸收的量少","小管上皮管腔膜两侧电位差很大","是神经和体液因素调节的重要部位","小管液与上皮细胞内液体保持等渗"],"a":4,"e":"近端小管对水和溶质的重吸收为等渗性重吸收，小管液始终保持等渗。近端小管重吸收物质种类多、量大，且不受神经和体液因素调节。"},{"q":"窦房结细胞动作电位的主要特点是","o":["去极相有超射现象","去极化速度很快","复极化时间远远长于去极化时间","有明显的2期平台期","有4期自动去极化"],"a":4,"e":"窦房结P细胞动作电位4期自动去极化是自律细胞产生自动节律性兴奋的基础，也是其区别于心室肌细胞的主要特点。"},{"q":"通常认为，控制生物节律的主要中枢结构是","o":["视上核","下丘脑前核","视前核","视交叉上核","灰白结节"],"a":3,"e":"下丘脑视交叉上核是哺乳动物控制日节律的关键部位，毁损后可消除各种内源性昼夜节律。视上核主要参与水平衡和渗透压调节。"},{"q":"血中激素浓度虽低但生理作用很明显，其原因是","o":["激素随血液分布全身","激素的特异性很高","激素的半衰期很长","激素与受体结合的时间很长","细胞内存在高效能的生物放大系统"],"a":4,"e":"激素血浓度低但作用强，是因为激素与受体结合后经信号转导逐级放大，产生高效能的生物放大效应，如肾上腺素经cAMP-蛋白激酶A通路可放大上千万倍。"},{"q":"可阻断心室肌细胞的0期去极化的药物是","o":["河豚毒","四乙基胺","维拉帕米","阿托品","普萘洛尔"],"a":0,"e":"心室肌0期去极化由快钠通道介导，河豚毒可选择性阻断钠通道，故能阻断0期去极化。维拉帕米阻断L型钙通道，主要影响慢反应细胞。"},{"q":"躯体感觉不包括","o":["触压觉","温度觉","运动觉","位置觉","牵涉痛"],"a":4,"e":"躯体感觉包括浅感觉（触-压觉、温度觉、痛觉、痒觉）和深感觉（位置觉、运动觉等）。牵涉痛属内脏痛范畴，由内脏疾病引起远隔体表部位疼痛，不属于躯体感觉。"},{"q":"下列激素中化学性质属于固醇类的是","o":["皮质酮","醛固酮","睾酮","雌二醇","1,25-(OH)2-D3"],"a":4,"e":"1,25-(OH)2-D3即钙三醇，属维生素D3衍生物，化学本质为固醇类。皮质酮、醛固酮、睾酮、雌二醇均为类固醇激素，但属肾上腺皮质激素和性激素。"},{"q":"血浆晶体渗透压降低时可引起","o":["组织液减少","组织液增加","尿少","红细胞萎缩","红细胞膨胀和破裂"],"a":4,"e":"血浆晶体渗透压降低时，水向红细胞内转移，红细胞膨胀甚至破裂。晶体渗透压主要维持细胞内外水平衡，其降低使组织液生成增多而非减少，尿量增多而非减少。"},{"q":"对机体产热活动影响最重要的体液因素是","o":["去甲肾上腺素","肾上腺素","甲状腺激素","甲状旁腺激素","生长激素"],"a":2,"e":"甲状腺激素是调节非战栗产热活动最重要的体液因素，寒冷时经下丘脑-垂体-甲状腺轴大量分泌，可使代谢率增加20%～30%。"},{"q":"房室交界处传导速度较慢的生理意义在于","o":["有利于增强心肌收缩能力","有利于心房或心室同步收缩","有利于心室充盈和射血的交替","有效避免出现完全强直收缩","有效防止出现期前收缩"],"a":2,"e":"房室交界传导速度慢形成房室延搁，保证心室收缩发生在心房收缩完毕之后，有利于心室充盈和射血。"},{"q":"不引起尿量增加的情况是","o":["尿崩症","糖尿病","交感神经兴奋性升高","血管升压素受体缺乏","静脉输入甘露醇"],"a":2,"e":"交感神经兴奋使肾血管收缩、肾血流量减少，并促进肾素释放和血管升压素分泌，使尿量减少。尿崩症、糖尿病、血管升压素受体缺乏及甘露醇渗透性利尿均致尿量增加。"},{"q":"根据Laplace定律，大小不一的肺泡彼此相通，且表面张力相等，则导致","o":["小肺泡内压力大，大肺泡内压力小","小肺泡内压力小，大肺泡内压力大","大小肺泡内压力相等","吸气时气体主要进入小肺泡","呼气时气体主要出自大肺泡"],"a":0,"e":"按Laplace定律，表面张力系数不变时肺泡回缩压与半径成反比，故小肺泡内压力大、大肺泡内压力小，气体由小肺泡流入大肺泡。"},{"q":"下列哪种酶在TSH促进甲状腺激素合成的过程中起关键性作用","o":["脱碘酶","蛋白水解酶","过氧化酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"过氧化酶（TPO）是催化甲状腺激素合成的关键酶，在滤泡腔面微绒毛处分布最丰富，催化碘的活化及酪氨酸残基碘化。脱碘酶参与脱碘回收碘，并非激素合成关键酶。"},{"q":"脊髓半离断可能发生的症状是","o":["离断同侧痛觉障碍","离断同侧粗触压觉障碍","离断对侧温度觉障碍","离断对侧本体觉障碍","离断对侧精细触觉障碍"],"a":2,"e":"传导痛觉、温度觉的纤维先交叉后上行，故一侧脊髓半横断时损伤平面以下对侧出现痛觉、温度觉障碍。本体感觉和精细触-压觉纤维先上行后交叉，障碍在同侧。"},{"q":"关于静脉血压，下列叙述中错误的是","o":["站立时颅内静脉窦的压力低于大气压","正常成人在立正状态下，足背静脉压和主动脉平均压几乎相等","深吸气时中心静脉压升高","中心静脉压的高低与心脏的射血能力有关","足背静脉压在行走时比立正时低"],"a":2,"e":"深吸气时胸膜腔负压增大，腔静脉回心血量增多，中心静脉压应降低而非升高。中心静脉压取决于心脏射血能力与静脉回心血量的关系。"},{"q":"内分泌细胞分泌激素到组织液的过程属于","o":["入胞","易化扩散","出胞","主动转运","单纯扩散"],"a":2,"e":"内分泌细胞分泌激素以大分子物质经分泌囊泡排出细胞，属出胞过程，需消耗能量并伴细胞膜面积增加。"},{"q":"在我国引起急性胰腺炎最常见的病因是","o":["胆道疾病","大量饮酒和暴饮暴食","并发于流行性腮腺炎","高钙血症","手术创伤"],"a":1,"e":"官方答案为大量饮酒和暴饮暴食，但依据教材，正确答案为胆道疾病。我国急性胰腺炎最常见的病因是胆道疾病，胆石嵌顿致胆汁反流入胰管激活胰酶。大量饮酒和暴饮暴食为常见诱因但非我国首位病因。"},{"q":"产生兴奋性突触后电位（EPSP）的主要机制是","o":["突触前末梢递质释放增多","需由中间神经元中介","突触后膜K+电导降低","突触后膜Na+电导增加","突触后神经元受刺激而兴奋"],"a":3,"e":"兴奋性递质作用于突触后膜受体，使Na+和K+通道开放，以Na+大量内流为主，引起突触后膜去极化形成EPSP。慢EPSP才与K+电导降低有关。"},{"q":"下列关于胃排空的叙述，错误的是","o":["胃内食糜由胃排入十二指肠的过程称为胃排空","胃排空是连续进行的","胃排空决定于幽门两侧的压力差","胃排空受十二指肠内容物pH值的影响","混合食物需4～6小时方可完全排空"],"a":1,"e":"胃排空是间断进行的，胃运动加强使胃内压超过十二指肠内压时发生一次排空，随后十二指肠内因素抑制胃运动。混合食物完全排空需4～6小时。"},{"q":"某人因外伤损伤脊髓，经检查发现有痛温觉与轻触觉分离障碍，请问是哪种脊髓的损伤所致","o":["脊髓离断","脊髓空洞症","后角受损","前根病变","脊髓半离断"],"a":4,"e":"官方答案为脊髓半离断，但依据教材，正确答案为脊髓空洞症。痛温觉纤维先交叉后上行、粗略触-压觉纤维部分交叉，脊髓中央管周围前交叉纤维局限损害时出现痛温觉障碍而触-压觉保留的分离现象，见于脊髓空洞症。"},{"q":"腰骶部脊髓受损时，排尿功能障碍表现为","o":["尿失禁","尿频","尿痛","多尿","尿潴留"],"a":4,"e":"支配膀胱的盆神经或骶段脊髓受损时排尿反射弧中断，排尿反射不能发生，膀胱松弛扩张致尿潴留。高位脊髓受损则表现为尿失禁。"},{"q":"属于可兴奋细胞的是","o":["成纤维细胞","肝细胞","腺细胞","施万细胞","红细胞"],"a":2,"e":"腺细胞能产生动作电位，属于可兴奋细胞。可兴奋细胞指神经细胞、肌细胞和腺细胞等受刺激后能产生动作电位的细胞。"},{"q":"小儿排尿次数较多，且易发生夜间遗尿现象，最可能的原因是","o":["膀胱发育不完善","盆神经发育不完善","阴部神经发育不完善","骶髓初级排尿中枢发育不完善","大脑发育不完善"],"a":4,"e":"小儿大脑发育未完善，对骶髓初级排尿中枢的控制能力较弱，故排尿次数多且易夜间遗尿。"},{"q":"下列关于腱反射的描述，正确的是","o":["腱反射是多突触反射","腱反射减弱提示高位中枢有病变","腱反射亢进提示反射弧损害","是由于缓慢牵拉肌梭引起的反射","腱反射的感受器是肌梭"],"a":4,"e":"牵张反射的感受器是肌梭，腱反射属牵张反射。腱反射为单突触反射，减弱提示反射弧受损，亢进提示高位中枢病变，快速牵拉才引起。"},{"q":"与心室肌细胞动作电位3期复极化有关的离子跨膜流动是","o":["因Na+内流而产生","因Ca2+内流而产生","因Cl-内流而产生","因K+内流而产生","因K+外流而产生"],"a":4,"e":"心室肌细胞3期复极化主要由K+外流引起，K+外向电流随时间递增并呈再生性，使膜迅速复极。"},{"q":"下列关于波尔效应的描述正确的是","o":["主要是由于PaCO2和血液中pH改变使血红蛋白构象发生改变","使组织毛细血管中氧解离曲线左移","促进组织毛细血管血液摄取CO2，肺泡毛细血管血液释放CO2","增加红细胞中2，3-DPG含量","与Cl-在红细胞内外转运过程有关"],"a":0,"e":"波尔效应指血液pH和PCO2改变使Hb构象变化，从而改变Hb对O2的亲和力。酸度增加时Hb向T型转变，亲和力降低，氧解离曲线右移。"},{"q":"引起促胰液素释放的因素由强到弱的排列顺序为","o":["蛋白质分解产物、脂肪酸、盐酸","脂肪酸、蛋白质分解产物、盐酸","盐酸、蛋白质分解产物、脂肪酸","盐酸、脂肪酸、蛋白质分解产物","蛋白质分解产物、盐酸、脂肪酸"],"a":2,"e":"盐酸是刺激促胰液素释放的最强因素，其次为蛋白质分解产物和脂酸钠（脂肪酸），糖类几乎无刺激作用。"},{"q":"下列关于人体生理学的叙述，错误的是","o":["是生物科学的一个分支","研究人体功能活动及其规律","是1门连接基础和临床学科的桥梁学科","大多数资料来自人体实验","为临床实践提供思维方法和研究手段"],"a":3,"e":"人体生理研究受伦理学限制，多数资料来自动物实验，人体研究以无创性观察和参数记录为主。"},{"q":"心肌不会产生完全强直收缩，是因为","o":["心肌是机能上的合胞体","心肌肌浆网不发达，Ca2+贮存少","心肌有自律性","心肌呈“全或无”式收缩","心肌的有效不应期长"],"a":4,"e":"心肌有效不应期特别长，相当于整个收缩期和舒张早期，期内不能接受刺激产生兴奋收缩，故不发生完全强直收缩。"},{"q":"激素通过血液运输作用于远距离的靶细胞，称为","o":["外分泌","远距分泌","旁分泌","神经分泌","自分泌"],"a":1,"e":"激素经血液循环运送至远距离靶细胞发挥调节作用，称为远距分泌（telecrine）或血运分泌。旁分泌是化学物质经组织液扩散作用于邻近细胞，不依赖血液循环。"},{"q":"动物实验中，牵拉颈动脉，使颈动脉窦压力感受器的传入冲动增加时，引起的变化是","o":["心迷走神经的紧张性降低","心交感神经的紧张性增加","交感缩血管神经的紧张性降低","血容量增加，细胞外液量增加","心率加快，血压升高"],"a":2,"e":"牵拉颈动脉窦使压力感受器传入冲动增多，压力感受性反射增强，导致心迷走紧张加强、心交感紧张和交感缩血管紧张减弱，故交感缩血管神经紧张性降低。"},{"q":"压力感受性反射","o":["平时不起作用","只起降压作用而无升压效应","主要对动脉血压进行快速调节","随动脉血压水平升高而敏感性增强","对心率几乎没有影响作用"],"a":2,"e":"压力感受性反射属典型负反馈调节，对动脉血压的短期快速波动起缓冲作用，故又称缓冲神经反射。该反射对缓慢血压变化不敏感，在血压长期调节中不起重要作用。"},{"q":"下列关于突触前抑制特点的描述，正确的是","o":["以树突-树突式突触为结构基础","多见于运动传出通路中","潜伏期和持续时间均较长","因突触前膜发生超极化而产生","意义在于使神经元的活动及时终止"],"a":2,"e":"突触前抑制通过轴突-轴突式突触使突触前末梢递质释放减少，其潜伏期和持续时间均较长。其结构基础为轴突-轴突式突触，并非树突-树突式。"},{"q":"根据听觉的行波原理，临床上高频听力受损的病人，其受损的部位应更靠近","o":["蜗底部","蜗顶部","耳蜗中段","耳蜗全段","耳蜗前1/3"],"a":0,"e":"行波原理表明声波频率越高，行波传播越近，最大振幅部位越靠近蜗底，故耳蜗底部受损主要影响高频听力。蜗顶部受损则主要影响低频听力。"},{"q":"血液凝固的内源性与外源性激活途径的主要差别是","o":["FX激活物的形成过程","凝血酶激活过程","纤维蛋白形成过程","是否需要维生素K的参与","有无Ca2+的参与"],"a":0,"e":"内源性与外源性凝血途径的区别在于凝血酶原酶复合物（FX激活物）的形成过程，其后从FXa生成到纤维蛋白形成均经共同途径完成。"},{"q":"醛固酮的作用是促进","o":["Na+的重吸收和K+的排泄","Na+的重吸收和H+的分泌","K+的重吸收和Na+的排泄","H+的重吸收和Na+的排泄","K+的重吸收和H+的分泌"],"a":0,"e":"醛固酮作用于肾远曲小管和集合管上皮细胞，促进Na+重吸收和K+分泌，即保Na+排K+作用，同时伴水重吸收增多。"},{"q":"骨骼肌兴奋-收缩耦联的关键部位是","o":["肌膜","终板膜","横管系统","纵管系统","三联管结构"],"a":4,"e":"骨骼肌T管与其两侧终池形成三联体结构，是兴奋-收缩耦联的关键部位；心肌则为T管与单侧终池形成二联体。Ca2+是耦联的关键因子。"},{"q":"某患者肾上腺皮质功能亢进，血浆中醛固酮水平升高，可预期该患者会出现","o":["血钠升高，细胞外液量增加","血钾升高，细胞外液量增加","血钠升高，细胞外液量减少","血钾下降，细胞外液量减少","血钠下降，细胞外液量增加"],"a":0,"e":"醛固酮作用于肾远曲小管和集合管，促进Na+重吸收并增加K+排泄，同时水的重吸收增加，使血钠升高、细胞外液量增加。血钾应降低而非升高。"},{"q":"肥胖病人体内瘦素水平升高会导致以下哪种情况","o":["体重下降","心肌收缩力增强","食欲增加","能量消耗增加","胰岛素合成增多"],"a":4,"e":"瘦素由脂肪细胞分泌，肥胖者常存在瘦素抵抗，血清瘦素水平升高。教材指出胰岛素可刺激脂肪细胞分泌瘦素，瘦素与胰岛素间存在相互促进关系，故胰岛素合成增多。"},{"q":"产生生物电的跨膜离子移动主要属于","o":["单纯扩散","入胞","出胞","通道中介的易化扩散","载体中介的易化扩散"],"a":3,"e":"生物电的产生源于带电离子经离子通道顺电化学梯度跨膜移动，属经通道的易化扩散，不耗能。载体易化扩散转运的是水溶性小分子，不直接产生跨膜电流。"},{"q":"在近端小管后半段，部分钠离子通过细胞旁路重吸收的动力主要来自","o":["管腔内带正电，管腔外带负电","小管液钠离子浓度高于管周液钠离子浓度","小管液静水压高于管周液静水压","管周液胶体渗透压高于小管液胶体渗透压","管周液晶体渗透压低于小管液晶体渗透压"],"a":0,"e":"近端小管后半段Cl-经细胞旁途径被动重吸收后，小管液中正离子相对增多，管腔内带正电、管周带负电，此电位差驱使Na+经细胞旁途径被动重吸收。"},{"q":"关于肾小管葡萄糖重吸收的描述，正确是","o":["全部肾小管均能重吸收葡萄糖","葡萄糖重吸收属于易化扩散","只有近端小管能吸收葡萄糖，属于易化扩散","只有近端小管能吸收葡萄糖，顶端膜的转运属于继发性主动转运，基底侧膜的转运属于被动易化扩散","只有近端小管能吸收葡萄糖，顶端膜和基底侧膜的转运都属于继发性主动转运"],"a":3,"e":"滤过的葡萄糖仅在近端小管（尤其前半段）被重吸收。顶端膜经Na+-葡萄糖同向转运体（SGLT）以继发性主动转运入细胞，基底侧膜经GLUT2以易化扩散入细胞间液。"},{"q":"心脏的等长调节是通过下列哪个因素对心脏泵血功能进行调节的","o":["心肌初长度","肌小节初长度","粗、细肌丝间横桥结合数目","心脏收缩能力","心室舒张末期容积"],"a":3,"e":"等长调节指通过改变心肌收缩能力调节心脏泵血功能，不依赖初长度改变。心肌收缩能力增强使心室功能曲线左上移，同等前负荷下每搏功增加。"},{"q":"有关继发性主动转运描述，下列选项正确的是","o":["顺着转运物质的浓度梯度进行转运","转运动力均来自于钠离子的跨膜浓度梯度","Na+-Ca2+交换体是Ca2+顺着浓度梯度运出细胞","Na+-H+交换体主要分布在胃黏膜上皮细胞顶端膜","甲状腺上皮细胞的钠-碘转运体属于同向转运体"],"a":4,"e":"甲状腺滤泡上皮细胞基底膜的钠碘同向转运体（NIS）依赖钠泵提供的势能，以1I-∶2Na+比例同向转运碘，属继发性主动转运。Na+-H+交换体位于肾小管而非胃黏膜。"},{"q":"贫血患者呼吸幅度和频率未见明显异常变化，主要是因为","o":["化学感受器的敏感性降低","血液PO2正常","血液pH值正常","血液氧含量正常","血液PCO2正常"],"a":1,"e":"低氧对呼吸的刺激作用通过外周化学感受器实现，而贫血时动脉血PO2正常，仅氧含量降低，故不引起呼吸增强。化学感受器主要感受PO2、PCO2和H+变化。"},{"q":"下列哪种情况下GFR增加","o":["交感神经系统强烈兴奋","电刺激心迷走神经外周端","肾入球小动脉收缩","血浆白蛋白浓度降低","平均动脉压从100mmHg升高到130mmHg"],"a":3,"e":"血浆白蛋白浓度降低使血浆胶体渗透压下降，有效滤过压增大，GFR增加。交感强烈兴奋、入球小动脉收缩均使肾血流量减少、GFR降低；平均动脉压在此范围内经自身调节GFR基本不变。"},{"q":"胎盘合体滋养层细胞分泌的hCG在妊娠的哪个阶段达到高峰","o":["第3～4周","第5～6周","第7～8周","第8～10周","第10～12周"],"a":3,"e":"hCG由合体滋养层细胞分泌，受精卵着床后1天即可测出，妊娠8～10周达高峰，此后迅速下降，产后2周内消失。"},{"q":"分娩过程中，促进子宫节律性收缩最重要的激素是","o":["缩宫素","雌激素","孕激素","前列腺素","糖皮质激素"],"a":0,"e":"缩宫素是分娩中起重要作用的母体来源激素，反射性释放后引起子宫平滑肌强有力收缩，并构成正反馈调节。前列腺素参与分娩发动，但非促进宫缩最重要的激素。"},{"q":"兴奋在中枢传播的特征包括","o":["双向传播","不易疲劳","对内环境变化不敏感","兴奋节律的改变","兴奋在中枢传播速度快"],"a":3,"e":"中枢兴奋传播经多级化学突触接替，具有单向传播、突触延搁、兴奋总和、兴奋节律改变、对内环境变化敏感和易疲劳等特征。"},{"q":"甲状旁腺激素的主要靶器官是","o":["甲状旁腺","胃肠道","骨组织","肾上腺","甲状腺"],"a":2,"e":"PTH的靶器官主要是肾脏和骨，通过促进肾小管重吸收钙、抑制重吸收磷及促进骨钙入血调节血钙、血磷稳态。"},{"q":"副交感神经兴奋时，可引起","o":["瞳孔散大","汗腺分泌","胰岛素分泌","糖原分解增加","骨骼肌血管舒张"],"a":2,"e":"迷走神经兴奋释放乙酰胆碱，作用于β细胞膜M受体，促进胰岛素分泌。交感兴奋以α受体为主抑制胰岛素分泌，瞳孔散大、糖原分解增加亦属交感效应。"},{"q":"影响精子生成的因素不包括","o":["环境污染","过量饮酒","放射线照射","抗肿瘤药物","少量吸烟"],"a":4,"e":"吸烟可使卵泡池耗竭而提前绝经，过量饮酒、环境污染、放射线照射及抗肿瘤药物均损害生精功能，少量吸烟不构成影响精子生成的明确因素。"},{"q":"可由神经细胞分泌的激素是","o":["缩宫素","卵泡刺激素","促甲状腺激素","催乳素","甲状腺激素"],"a":0,"e":"缩宫素由下丘脑视上核和室旁核神经细胞合成，经轴突运输至神经垂体释放，属神经内分泌。卵泡刺激素、促甲状腺激素、催乳素由腺垂体细胞分泌，甲状腺激素由甲状腺滤泡上皮细胞分泌。"},{"q":"促胰液素能促进胰腺分泌","o":["大量水分和碳酸氢盐，酶含量较少","少量水分和碳酸氢盐，酶的含量也很少","少量水分和碳酸氢盐，酶的含量很丰富","大量水分，而碳酸氢盐和酶的含量很少","大量的碳酸氢盐，水分和酶含量也丰富"],"a":0,"e":"促胰液素主要作用于胰腺小导管上皮细胞，使其分泌大量水和HCO3⁻，胰液量大为增加而酶含量很低。迷走神经兴奋才是引起水和碳酸氢盐少、酶丰富的因素。"},{"q":"引起促胰液素释放作用最强的物质是","o":["蛋白质分解产物","HCl","脂酸钠","淀粉","葡萄糖"],"a":1,"e":"盐酸是引起促胰液素释放的最强刺激因素，其次为蛋白质分解产物和脂酸钠，糖类几乎无刺激作用。"},{"q":"青春期男性第二性征的表现不包括","o":["骨骼粗壮","肌肉发达","体态丰满","喉结出现","声音变粗"],"a":2,"e":"男性第二性征表现为骨骼粗壮、肌肉发达、胡须阴毛生长、喉结突出和声音变粗钝。体态丰满、骨盆宽大属女性第二性征表现。"},{"q":"引起快反应细胞0期去极化的主要电流是","o":["ICa","INa","IK1","Ito","If"],"a":1,"e":"快反应细胞0期去极化由钠内向电流（INa）引起，膜去极化达阈电位时钠通道大量开放，Na⁺快速内流形成再生性去极化。"},{"q":"动物血压调节实验中，牵拉颈总动脉时，下列哪项不是压力感受性反射的效应","o":["心交感紧张性减弱","心迷走紧张加强","交感缩血管紧张性减弱","交感舒血管紧张性加强","外周血管阻力降低"],"a":3,"e":"牵拉颈总动脉使压力感受器传入冲动增多，反射性引起心迷走紧张加强、心交感紧张和交感缩血管紧张减弱，外周阻力降低、血压下降。交感舒血管纤维不参与该反射效应。"},{"q":"有关神经纤维的动作电位，说法错误的是","o":["其传导为衰减性传导","其幅度具有“全或无”性质","在神经纤维上的传导是双向性的","升支与钠离子内流有关，降支与钾离子外流有关","具有不应期"],"a":0,"e":"动作电位具有“全或无”性质，在神经纤维上呈不衰减的局部电流传导，且具不应期和双向性。衰减性传导是电紧张电位和局部电位的特征。"},{"q":"下列维生素中不在小肠被吸收的是","o":["维生素K","维生素B12","维生素D","维生素E","维生素A"],"a":1,"e":"维生素B12需与胃壁细胞分泌的内因子结合，在回肠远端被吸收，不在小肠上段吸收。其余脂溶性维生素随脂类在小肠吸收。"},{"q":"循环系统对体温的调节主要通过改变下列哪一因素而实现","o":["血流速度","血液温度","心输出量","逆流交换效率","皮肤血流量"],"a":4,"e":"机体通过交感神经调节皮肤血管口径，改变皮肤血流量和皮肤温度，从而调节辐射、传导和对流散热量，使散热符合体热平衡需要。"},{"q":"在用哺乳类动物作为实验对象观察脊髓休克的实验中，通常最合理的脊髓横断水平至少应在","o":["第一段颈髓之下","第二段颈髓之下","第三段颈髓之下","第四段颈髓之下","第五段颈髓之下"],"a":4,"e":"正确答案是第五段颈髓之下。为研究脊髓本身功能又保留呼吸功能，需在第5颈髓水平以下横断脊髓制备脊动物，因此横断水平至少应在第五段颈髓之下。"},{"q":"长期使用大量糖皮质激素可引起肾上腺皮质萎缩，其原因是","o":["直接使束状带与网状带细胞凋亡","负反馈抑制腺垂体分泌ACTH","促进肾上腺皮质细胞蛋白质分解","抑制肾上腺皮质细胞蛋白质合成","促进肾上腺皮质细胞脂肪分解"],"a":1,"e":"正确答案是负反馈抑制腺垂体分泌ACTH。长期大剂量应用GC可通过长反馈抑制下丘脑CRH神经元及腺垂体ACTH细胞，使ACTH分泌减少，导致肾上腺皮质束状带和网状带萎缩、分泌功能减退。"},{"q":"甲状腺手术时误切甲状旁腺会引起","o":["肾结石","黏液水肿","骨质疏松","手足搐搦","消瘦"],"a":3,"e":"正确答案是手足搐搦。PTH总效应为升高血钙、降低血磷，误切甲状旁腺致PTH缺乏，血钙降低使神经肌肉兴奋性异常增高，发生手足搐搦。"},{"q":"窦房结细胞的起搏活动是由于","o":["递减性K＋外流","递增性净内向电流","递减性K＋外流与递增性Na＋内流","经T型Ca2＋通道的递增性内流","递减性K＋外流与L型Ca2＋通道的递增性内流"],"a":1,"e":"正确答案是递增性净内向电流。窦房结P细胞4期自动去极化由外向电流IK进行性衰减与If、ICa-T等内向电流增强共同形成，净内向电流递增使膜自动去极化达阈电位。"},{"q":"精子与卵子结合受精一般在何处完成","o":["输卵管伞部","输卵管壶腹部","输卵管峡部","输卵管子宫部","子宫底部"],"a":1,"e":"正确答案是输卵管壶腹部。受精一般发生于排卵后数小时内的输卵管壶腹部，精子经宫颈、宫腔、输卵管运行至此与卵子相遇并发生顶体反应。"},{"q":"窦房结能成为心脏正常起搏点的原因是","o":["静息电位仅为-70mV","阈电位为-40mV","0期去极化速度快","动作电位没有明显的平台期","4期自动去极化速度最快"],"a":4,"e":"正确答案是4期自动去极化速度最快。窦房结P细胞4期自动去极化速度在自律细胞中最快，达阈电位所需时间最短，自律性最高，故成为正常起搏点。"},{"q":"甲状腺激素对靶细胞的作用，是通过下列哪个信息传递途径而产生的","o":["cAMP-PKA系统","三磷酸肌醇/二酰甘油-蛋白激酶C系统","cGMP-PKG系统","PG的介导","进入核内调控DNA转录"],"a":4,"e":"正确答案是进入核内调控DNA转录。甲状腺激素为脂溶性激素，进入细胞后与核受体结合，以二聚体形式与靶基因HRE结合，调节基因转录和翻译产生基因组效应。"},{"q":"因胚胎期缺碘或甲状腺功能减退，儿童罹患的疾病是","o":["艾迪生病","侏儒症","肢端肥大症","呆小症","佝偻病"],"a":3,"e":"正确答案是呆小症。胚胎期及幼儿期缺乏TH可致不可逆的神经系统发育障碍和骨骼生长成熟延迟，出现智力与体格发育迟缓，即呆小症。"},{"q":"体外实验中，用葡萄糖逐渐替代浸浴液中的Na+，神经元或神经纤维动作电位的幅度将","o":["逐渐增大","逐渐减小","不发生改变","先增大后减小","先减小后增大"],"a":1,"e":"动作电位去极相由Na+内流形成，其幅度取决于细胞外Na+浓度。用葡萄糖替代浸浴液中的Na+使细胞外Na+浓度降低，Na+内流减少，动作电位幅度逐渐减小。"},{"q":"关于突触前易化的产生，正确的描述是","o":["突触前膜钾通道通透性增高","到达末梢的动作电位频率增高","多个兴奋同时到达突触前末梢","突触前末梢递质释放增多","突触后膜多个EPSP发生总和"],"a":3,"e":"突触前易化指由于突触前变化使突触效能增强，其本质是突触前末梢递质释放增多。到达末梢动作电位频率增高只是引起递质释放增多的因素之一，并非易化本身。"},{"q":"浦肯野细胞0期去极化过程中，Na+通道开始迅速失活的条件是当膜电位去极化到以下","o":["-70mV","-50mV","-30mV","0mV","0期去极化的峰值"],"a":3,"e":"0期去极的钠通道为快通道，激活快、失活也快，当膜去极化到0mV左右时钠通道开始失活而关闭，终止Na+内流。"},{"q":"机体内温度最高的器官是","o":["脑","肝脏","肾脏","胰腺","十二指肠"],"a":1,"e":"肝脏代谢最旺盛，产热量最高，其血液温度比主动脉血液温度高0.4～0.8℃，是机体内温度最高的器官。"},{"q":"以下哪种不是前列腺素主型","o":["PGA","PGC","PGE","PGG","PGJ"],"a":4,"e":"前列腺素依据五碳环构造可分为A～I等九种主型，包括PGA、PGC、PGE、PGG等，PGJ不属于其中。"},{"q":"引起抗利尿激素分泌的最重要的因素是","o":["循环血量减少","血浆晶体渗透压升高","血浆胶体渗透压升高","血浆晶体渗透压降低","血浆胶体渗透压下降"],"a":1,"e":"生理状态下血浆晶体渗透压是调节抗利尿激素分泌最重要的因素，渗透压升高1%～2%即可刺激渗透压感受器使抗利尿激素分泌增加。"},{"q":"Starling机制在生理状态下的主要功能在于","o":["使心输出量增加","使心指数下降","调节搏出量和回心血量的平衡","使射血分数增加","使每搏功增加"],"a":2,"e":"异长自身调节即Starling机制，主要意义是对搏出量微小变化进行精细调节，使心室射血量与静脉回心血量保持平衡。"},{"q":"褪黑素是由下列哪种内分泌细胞分泌的","o":["甲状腺C细胞","胰岛PP细胞","松果体细胞","肾上腺髓质嗜铬细胞","下丘脑的神经细胞"],"a":2,"e":"松果体主要合成和分泌褪黑素，其为色氨酸衍生物，参与生物节律调控。甲状腺C细胞分泌降钙素，肾上腺髓质嗜铬细胞分泌儿茶酚胺。"},{"q":"医学生在生理学实验中经静脉给家兔注射25%葡萄糖2ml，随后观察到尿量明显增加，其原因是","o":["血管升压素分泌减少","肾小球滤过率增加","肾血浆晶体渗透压增高","肾血流量增多","肾小管液溶质浓度增高"],"a":4,"e":"静脉注射高浓度葡萄糖使滤液中葡萄糖超过近端小管重吸收极限，小管液溶质浓度升高，渗透压增大，水重吸收减少而尿量增加，即渗透性利尿。"},{"q":"下列关于大脑皮层运动区的描述，正确的是","o":["人大脑皮层主要运动区位于中央后回","躯体骨骼肌运动为交叉性支配","头面部肌肉运动均为双侧性支配","躯体和头面部内部均为倒置性安排","肢体远端代表区在前，而近端代表区在后"],"a":1,"e":"皮层运动区对躯体骨骼肌的支配具有交叉性质，即一侧皮层支配对侧躯体肌肉；头面部肌肉多为双侧性支配，且代表区呈倒置安排（头面部内部为正立）。"},{"q":"精子获能的特点不包括","o":["暴露精子表面与卵子的识别部位","解除对精子顶体反应的抑制","精子细胞膜流动性增加","精子发生超激活反应","只能在女性生殖道内完成"],"a":4,"e":"精子获能指精子在女性生殖道停留期间发生形态和功能变化而获得受精能力，包括暴露识别部位、解除顶体反应抑制、膜流动性增加及超激活反应。获能也可在体外适宜培养条件下完成。"},{"q":"小肠对糖的选择性吸收最快的是","o":["果糖","甘露糖","半乳糖","木糖","核糖"],"a":2,"e":"己糖吸收中以半乳糖和葡萄糖最快，果糖次之，甘露糖最慢；半乳糖经SGLT-1继发性主动转运吸收。"},{"q":"血管升压素在肾脏主要作用于","o":["近球细胞","系膜细胞","肾小球上皮细胞","致密斑","远端小管和集合管上皮细胞"],"a":4,"e":"血管升压素作用于远端小管和集合管上皮细胞，增加管腔膜水通道AQP2，促进水重吸收，使尿液浓缩。"},{"q":"骨骼肌细胞中横管的功能是","o":["钙离子的贮存库","钙离子进出肌纤维的通道","营养物质进出肌细胞的通道","将兴奋传向肌细胞深部","使钙离子和肌钙蛋白结合"],"a":3,"e":"横管由肌膜向内凹陷形成，可将肌膜动作电位传向肌细胞深部，触发肌质网释放Ca2+完成兴奋-收缩耦联。"},{"q":"下列各因素中，哪一项不能引起促胃液素分泌增多","o":["刺激迷走神经","扩张刺激幽门部黏膜","肉汤灌注幽门部黏膜","盐酸灌注幽门部黏膜","食物刺激小肠上端黏膜"],"a":3,"e":"盐酸灌注幽门部黏膜不能刺激促胃液素分泌，盐酸是刺激小肠黏膜释放促胰液素的最强因素；迷走神经、幽门部扩张及蛋白质消化产物均可促进G细胞释放促胃液素。"},{"q":"由腺垂体分泌的激素是","o":["GH","CRH","GHRH","GHIH","GnRH"],"a":0,"e":"GH由腺垂体生长激素细胞合成和分泌；CRH、GHRH、GHIH（生长抑素）及GnRH均由下丘脑分泌，属下丘脑调节肽。"},{"q":"降钙素的主要作用是","o":["升高血钙和血磷","降低血钙和血磷","降低血钙，升高血磷","升高血钙，降低血磷","主要参与正常血钙的调节"],"a":1,"e":"降钙素作用于骨和肾，抑制破骨细胞活动、促进成骨并增强肾脏排出钙磷，使血钙和血磷均降低，与甲状旁腺激素作用相反。"},{"q":"全心舒张期时长为","o":["0、2s","0、3s","0、4s","0、5s","0、6s"],"a":2,"e":"全心舒张期为心室舒张期的前0.4秒，此时心房也处于舒张状态。教材明确该时长为0.4秒。"},{"q":"合成后在细胞外大量储存的激素是","o":["肾上腺素","甲状腺激素","胰岛素","皮质醇","生长激素"],"a":1,"e":"甲状腺激素以甲状腺胶质形式大量储存在细胞外的甲状腺滤泡腔，甲状腺是唯一能将激素大量储存于细胞外的内分泌腺。肾上腺素、胰岛素等均储存于细胞内。"},{"q":"排便感由下列哪种原因引起","o":["横结肠积聚粪便","降结肠积聚粪便","乙状结肠积聚粪便","粪便进入直肠","粪便刺激肛门"],"a":3,"e":"粪便进入直肠后扩张刺激直肠壁感受器，冲动传至初级排便中枢并上传大脑皮层引起便意。正常直肠内通常无粪便，乙状结肠储存粪便不产生便意。"},{"q":"在骨骼肌标本浸液中加入筒箭毒碱后，刺激支配该肌的运动神经纤维，肌细胞终板电位的变化是","o":["去极化加大","维持原水平","去极化减小","爆发动作电位","发生超极化"],"a":2,"e":"筒箭毒碱阻断骨骼肌终板膜N2受体，使ACh不能引起终板去极化，故终板电位去极化幅度减小。终板电位本身不能爆发动作电位。"},{"q":"肾内存在哪种细胞可参与血管紧张素原转化为血管紧张素Ⅰ的过程","o":["肾小囊上皮细胞","球旁细胞","致密斑细胞","球外系膜细胞","近端小管上皮细胞"],"a":1,"e":"肾素由球旁器的球旁细胞合成、储存和释放，可催化血浆中血管紧张素原转变为血管紧张素Ⅰ。致密斑为感受器，不分泌肾素。"},{"q":"水和尿素容易通透、而钠离子不容易通透的肾小管和集合管部位是","o":["近曲小管","远曲小管","髓袢降支细段","髓袢升支细段","集合管"],"a":2,"e":"髓袢降支细段对水易通透（经AQP1），对NaCl相对不通透，对尿素中等通透（经UT-A2）。升支细段对水不通透而对NaCl通透。"},{"q":"进食引起的胰液和胆汁分泌属于","o":["神经调节","体液调节","神经和体液双重调节","正反馈调节","负反馈调节"],"a":2,"e":"进食时胰液分泌受神经和体液双重控制，但以体液调节为主；胆汁分泌和排出同样受神经和体液因素调节，也以体液调节为主。"},{"q":"血样氧分压为100mmHg，血氧饱和度为98%，血红蛋白浓度为15g/100ml血。该血样中氧含量为","o":["10mlO2 /100ml血液","15mlO2 /100ml血液","20mlO2 /100ml血液","23mlO2 /100ml血液","25mlO2 /100ml血液"],"a":2,"e":"Hb浓度15g/100ml时Hb氧容量为20.1ml/100ml血液，PO2 100mmHg时Hb氧饱和度约97.4%，血氧含量约19.4ml/100ml，接近20ml。"},{"q":"影响能量代谢最显著的是","o":["食物的特殊动力效应","环境温度为30℃","环境温度为20℃","精神活动","肌肉活动"],"a":4,"e":"肌肉活动对能量代谢的影响最显著，机体任何轻微活动即可提高代谢率，持续运动时耗氧量可达安静时的10～20倍。食物特殊动力效应、环境温度和精神活动的影响均相对较小。"},{"q":"在影响能量代谢的因素中，描述错误的是","o":["肌肉活动对能量代谢的影响十分显著","当环境温度低于20℃或高于30℃时，人体能量代谢率开始逐渐增加","与睡眠状态相比，精神活动活跃时脑组织对葡萄糖的代谢率显著增加","安静状态下，每100g脑组织耗氧量为肌肉组织的20倍","食物特殊动力效应由强弱排序为蛋白质>糖>脂肪"],"a":2,"e":"精神活动活跃时脑组织葡萄糖代谢率并无显著增加，平静思考时产热量增加不超过4%，仅精神紧张时能量代谢率才增高10%以上。肌肉活动影响显著、环境温度低于20℃或高于30℃时代谢率增加、脑耗氧量为肌肉的20倍、食物特殊动力效应蛋白质>糖>脂肪均正确。"},{"q":"血液如果储存时间较长，可引起氧解离曲线由正常位置左移的原因是","o":["二氧化碳分压降低","2，3-DPG浓度降低","pH升高","温度降低","吸入气中CO含量增加"],"a":1,"e":"血液保存较久时红细胞糖酵解停止，2,3-DPG含量下降，减少Hb对O2亲和力的作用减弱，氧解离曲线左移，O2不易解离。2,3-DPG增多才使曲线右移。"},{"q":"对肾素-血管紧张素系统的描述，正确的是","o":["肾素由肾小球外系膜细胞合成和分泌","血浆中钠离子含量减少可刺激肾素分泌","肾素可转变血管紧张素Ⅰ为血管紧张素Ⅱ","血管紧张素Ⅱ主要刺激醛固酮分泌","血管紧张素Ⅲ主要使血管收缩"],"a":1,"e":"血Na+水平降低可刺激肾素分泌，进而激活RAAS。肾素由球旁细胞分泌，其作用是催化血管紧张素原转变为血管紧张素Ⅰ；生成AngⅡ的是血管紧张素转换酶。"},{"q":"肾小球毛细血管血压较高时会导致","o":["肾交感神经兴奋性升高","致密斑感受器兴奋","肾素释放增加","肾小球滤过增加","醛固酮释放增加"],"a":3,"e":"肾小球毛细血管血压是有效滤过压的驱动力，其升高时有效滤过压增大，肾小球滤过率增加。肾交感神经兴奋、致密斑兴奋及肾素、醛固酮释放增加均属血压降低时的继发反应。"},{"q":"下列说法正确的是","o":["吸气时腔静脉回到右心房的血量减少","呼气时右心室搏出量增多","吸气时肺静脉回到左心房的血量增加","呼气时肺循环血管扩张","动脉血压在呼气相中期达到最高点"],"a":4,"e":"动脉血压在呼气相前半期继续上升，中期达最高点，后半期下降。吸气时腔静脉回右心血量增加、肺静脉回左心血量减少，呼气时则相反。"},{"q":"乙型血友病是由于血浆中缺乏凝血因子","o":["Ⅱ","Ⅲ","Ⅷ","Ⅸ","Ⅹ"],"a":3,"e":"乙型血友病即血友病B，由凝血因子Ⅸ缺乏所致。血友病A为FⅧ缺乏，FⅪ缺乏曾称血友病C，出血症状较轻微。"},{"q":"骨髓中自我复制能力最强的细胞是","o":["造血干细胞","定向祖细胞","前体细胞","网织红细胞","淋巴细胞"],"a":0,"e":"造血干细胞具有对称性和非对称性有丝分裂能力，可自我更新并保持数量稳定；造血祖细胞已失去自我更新能力。"},{"q":"胰岛素的生物学作用不包括","o":["促进葡萄糖进入细胞","促进脂肪酸转变成葡萄糖","促进糖原合成","促进机体生长","抑制脂肪和蛋白质分解"],"a":1,"e":"胰岛素促进葡萄糖进入细胞、促进糖原合成、促进蛋白质与脂肪合成并抑制其分解，还通过促进蛋白质合成而参与机体生长。脂肪酸不能转变成葡萄糖，糖异生的原料为乳酸、氨基酸和甘油。"},{"q":"在做胆囊造影时，为检查胆囊的收缩功能，让受试者进食油煎荷包蛋是为了促进","o":["胆固醇合成","胆盐合成","迷走神经兴奋","缩胆囊素的分泌","胃泌素的分泌"],"a":3,"e":"油煎荷包蛋富含脂肪，进入小肠后刺激缩胆囊素释放，缩胆囊素促进胆囊强烈收缩、壶腹括约肌舒张，使胆汁排出，故用于检查胆囊收缩功能。胆盐虽刺激肝胆汁分泌，但对胆囊运动无明显影响。"},{"q":"血小板磷脂酶A2激活后可产生的物质是","o":["血小板活化因子","ADP","血栓烷A2","cAMP","组胺"],"a":2,"e":"血小板磷脂酶A2激活后花生四烯酸生成，经环氧合酶及血栓烷合成酶作用生成血栓烷A2。TXA2由血小板临时合成并即时释放，是促进血小板聚集和血管收缩的重要物质。"},{"q":"在下列哪个平面横断脑干后仍能保持正常的呼吸节律","o":["脊髓与延髓之间","延髓与脑桥之间","脑桥中、上部之间","脑桥与中脑之间","中脑与丘脑之间"],"a":3,"e":"在中脑与脑桥之间横切脑干，呼吸节律无明显变化，说明该平面以下结构足以维持基本呼吸节律。延髓为产生最基本呼吸节律的喘息中枢，脑桥上部含呼吸调整中枢。"},{"q":"对于丘脑非特异投射系统的特点，下列说法错误的是","o":["失去感觉传入的专一性","主要发自丘脑的髓板内核群","弥散性投射到大脑皮层广泛区域","主要与皮层第四层神经元的胞体形成突触联系","维持与改变大脑皮层的兴奋状态"],"a":3,"e":"非特异投射系统弥散投射到大脑皮层广泛区域，主要终止于皮层浅层，与皮层神经元胞体形成突触，维持和改变皮层兴奋状态；点对点终止于第Ⅳ层的是特异投射系统。"},{"q":"手术切除动物肾上腺皮质后血中ACTH浓度升高，说明糖皮质激素对腺垂体促激素分泌具有哪种调节作用","o":["神经调节","神经-体液调节","正反馈调节","负反馈调节","前馈调节"],"a":3,"e":"切除肾上腺皮质后糖皮质激素减少，对腺垂体的负反馈抑制减弱，ACTH分泌增多，说明糖皮质激素对腺垂体促激素分泌具有负反馈调节作用。"},{"q":"对心绞痛伴有肺通气不畅的病人进行治疗，应选用","o":["酚妥拉明","育亨宾","普萘洛尔","阿替洛尔","丁氧胺"],"a":3,"e":"阿替洛尔主要阻断β1受体，减慢心率、降低心肌耗氧，可治疗心绞痛，且对β2受体影响小，不加重肺通气不畅。普萘洛尔阻断β2受体可诱发支气管痉挛，不宜用于此病人。"},{"q":"具有亲脂特性的激素是","o":["甲状腺激素","生长激素","胰岛素","缩宫素","肾上腺素"],"a":0,"e":"甲状腺激素属亲脂性激素，可穿越细胞膜和核膜，与细胞核内甲状腺激素受体结合发挥作用。生长激素、胰岛素、缩宫素和肾上腺素均为水溶性激素，作用于膜受体。"},{"q":"关于静脉血压，下列叙述错误的是","o":["站立时颅内静脉窦的压力低于大气压","正常成人在立正状态时，足背静脉压和主动脉平均压几乎相等","深吸气时中心静脉压高","中心静脉压的高低与心脏的射血能力有关","足背静脉压在行走时比立正时低"],"a":2,"e":"深吸气时胸膜腔负压增大，中心静脉压降低而非升高。中心静脉压取决于心脏射血能力与静脉回心血量的关系，站立时足背静脉压受重力影响显著升高。"},{"q":"前庭器官的静纤毛向动纤毛一侧弯曲或偏转时","o":["毛细胞膜去极化，传入神经纤维放电频率增高","毛细胞膜超极化，传入神经纤维放电频率降低","毛细胞膜去极化，传入神经纤维放电幅度增高","毛细胞膜超极化，传入神经纤维放电幅度降低","毛细胞膜去极化，传入神经纤维放电频率降低"],"a":0,"e":"静纤毛向动纤毛一侧弯曲使毛细胞膜去极化，达阈电位后传入神经纤维放电频率增高，表现为兴奋。动纤毛向静纤毛侧偏转才引起超极化、放电减少。"},{"q":"某人的红细胞与B型血的血清不凝集，其血清与B型血的红细胞也不凝集，此人血型为","o":["A型","B型","O型","AB型","Rh型"],"a":1,"e":"红细胞与B型血清（含抗A抗体）不凝集，说明无A抗原；血清与B型红细胞不凝集，说明血清无抗B抗体，符合B型血。A型血清含抗B抗体，会凝集B型红细胞。"},{"q":"体外受精-胚胎移植的超排卵方案中，应用外源性FSH的目的不包括","o":["促进多个卵泡同步发育成熟","提供卵泡发育必需的激素支持，防止卵泡闭锁","促进卵泡颗粒细胞分泌雌激素","促进下丘脑分泌大量GnRH","防止卵泡过早黄素化"],"a":3,"e":"外源性FSH直接作用于卵巢，促进卵泡发育成熟及颗粒细胞分泌雌激素，并不促进下丘脑分泌GnRH；GnRH分泌受雌、孕激素负反馈抑制。"},{"q":"下列属于机体内环境的是","o":["细胞内液","唾液","尿液","脑脊液","汗液"],"a":3,"e":"脑脊液属于细胞外液，是机体内环境的组成部分。细胞内液不属于内环境，唾液、尿液、汗液均经管道排出体外，属外界环境。"},{"q":"下列符合机体在炎热环境下的表现的是","o":["肌紧张增强","皮肤血流量增加","交感神经的紧张度增强","机体表层的隔热器作用增强","四肢热量逆流交换作用加强"],"a":1,"e":"炎热环境中交感神经紧张性降低，皮肤小动脉舒张、动-静脉吻合支开放，皮肤血流量显著增多，皮肤温度升高以促进散热。"},{"q":"下列物质不容易通过血脑屏障的是","o":["CO2和O2","乙醇","甘露醇","NH3","氯霉素"],"a":2,"e":"甘露醇为脂溶性低的多羟基化合物，不易通过血-脑屏障，故静脉滴注可提高血浆渗透压治疗脑水肿。CO2、O2、乙醇、NH3均可较快通过血-脑屏障。"},{"q":"下列哪种状态下GH分泌明显增加","o":["觉醒","轻微运动","进餐","慢波睡眠","异相睡眠"],"a":3,"e":"GH分泌与慢波睡眠密切相关，进入慢波睡眠后GH分泌陡增，入睡后约1小时达高峰；转入异相睡眠后迅速减少。"},{"q":"目前已有临床研究采用小剂量、间歇性应用甲状旁腺激素治疗女性骨质疏松，是由于这种给药方法可以","o":["使破骨活动增强","促进骨的吸收","促进成骨细胞凋亡","抑制前成骨细胞继续分化为成骨细胞","使成骨细胞活动增强，促进骨形成，骨量增加"],"a":4,"e":"小剂量、间歇性应用PTH主要使成骨细胞活动增强，促进骨形成，可增加骨密度和骨机械强度。大剂量持续应用才使破骨细胞活动增强、促进骨吸收。"},{"q":"内脏痛最主要的特点是","o":["尖锐的刺痛","潜伏期和持续时间长","定位不明确","伴有情绪和心血管反应","对牵拉性刺激不敏感"],"a":2,"e":"内脏痛最主要的特点是定位不明确，痛觉感受器在内脏分布稀疏，患者常不能指明疼痛的明确位置。深部痛和内脏痛均可伴自主神经反应，但定位不明确是内脏痛最突出的特征。"},{"q":"通过轴突反射实现局部血管舒张的是","o":["脊髓背根舒血管纤维","交感舒血管纤维","副交感舒血管纤维","血管活性肠肽神经元","作用于β2受体的交感缩血管纤维"],"a":0,"e":"皮肤伤害性传入纤维在外周末梢发出分支，冲动沿分支到达邻近微动脉使其舒张充血，此仅通过轴突外周部分完成的局部反射即轴突反射，由脊髓后根舒血管纤维实现。副交感舒血管纤维经节后释放ACh作用于M受体，不属轴突反射。"},{"q":"严重哮喘患者肺通气指标降低最为显著的是","o":["潮气量","肺活量","一秒用力呼气量","功能余气量","肺总量"],"a":2,"e":"哮喘属阻塞性通气障碍，气道狭窄使呼气阻力增大，一秒用力呼气量（FEV1）下降最显著，FEV1/FVC减小。肺活量测定不限制呼气时间，早期可仍正常，不能敏感反映气道通畅程度。"},{"q":"体温调定点的高低主要决定于","o":["产热器官的功能状态","散热器官的功能状态","外周温度感受器的工作特性","体温调整中枢的功能状态","温度敏感神经元的工作特性"],"a":4,"e":"调定点水平主要取决于热敏神经元和冷敏神经元的温度敏感特性，即两类神经元放电频率随温度变化的特性。发热时致热原使调定点上移，正是通过改变这两种神经元的放电特性实现。"},{"q":"以下不具有舒张冠脉血管作用的是","o":["CO2","抗利尿激素","交感神经兴奋","氢离子","前列腺素E"],"a":1,"e":"抗利尿激素主要调节肾小管对水的重吸收，不具舒张冠脉作用。CO2、H+、前列腺素E及交感神经兴奋均可使冠脉舒张，其代谢产物是冠脉舒张的主要因素。"},{"q":"大肠内的细菌可利用肠内物质合成下列哪种维生素","o":["维生素A","维生素D","维生素E","维生素K","叶酸"],"a":3,"e":"大肠内细菌可利用肠内较简单的物质合成维生素B复合物和维生素K，并被人体吸收，以补充食物摄入不足。维生素A、D、E为脂溶性维生素，主要由肝脏储存，非大肠细菌合成。"},{"q":"血浆胶体渗透压的生理作用是","o":["影响毛细血管内外水的交换","影响细胞内外水的交换","维持细胞正常体积","维持细胞正常形态","决定血浆总渗透压"],"a":0,"e":"血浆蛋白不易通过毛细血管壁，其浓度变化改变毛细血管两侧胶体渗透压，从而影响血管内、外水的平衡。晶体渗透压才是维持细胞内外水平衡和细胞正常体积的主要因素。"},{"q":"在手术过程中不慎损伤食管下2/3部的肌间神经丛，不会出现的是下列哪一项","o":["吞咽困难","胸骨下疼痛","食物反流","食管下括约肌松弛","食管下括约肌痉挛"],"a":3,"e":"食管下2/3部肌间神经丛受损时，食管下括约肌不能松弛，食团入胃受阻，出现吞咽困难、胸骨下疼痛和食物反流，即食管失弛缓症。括约肌松弛是迷走抑制性纤维释放VIP和NO的正常反应，故不会出现松弛。"},{"q":"在心肌状态和大动脉压力保持恒定的情况下，在一定范围内增加静脉回流量可以增加心室肌的","o":["前负荷","后负荷","心率","代谢率","前负荷和后负荷"],"a":0,"e":"正确答案是前负荷。在一定范围内增加静脉回心血量，使心室舒张期末充盈量增多，心室肌初长度增大，即前负荷增加，经异长自身调节使搏出量增加。后负荷取决于大动脉血压，题干已设定其恒定。"},{"q":"促胃液素不具有的作用是","o":["促进胃酸分泌","促进胃蛋白酶原分泌","抑制胆囊收缩","促进胃的蠕动","刺激小肠黏膜组织的生长"],"a":2,"e":"正确答案是抑制胆囊收缩。促胃液素促进胃酸和胃蛋白酶原分泌，使胃窦和幽门括约肌收缩、延缓胃排空，促进胃肠运动和胃肠上皮生长；引起胆囊收缩的是缩胆囊素。"},{"q":"下列关于脊髓α运动神经元的描述，正确的是","o":["是躯体骨骼肌运动反射的最后公路","大α运动神经元及其支配的肌纤维组成大的运动单位","小α运动神经元及其支配的肌纤维组成小的运动单位","轴突末梢释放的递质是谷氨酸","兴奋性较高，常以较高的频率持续放电"],"a":0,"e":"正确答案是是躯体骨骼肌运动反射的最后公路。α运动神经元接受肌梭、高位中枢及脊髓中间神经元的信息，整合后发出冲动至梭外肌纤维，是躯体运动反射的最后公路。"},{"q":"对暗光敏感的区域是","o":["视网膜中央凹处","视盘处","视网膜周缘部分","整个视网膜","视盘"],"a":2,"e":"正确答案是视网膜周缘部分。视网膜周缘部分视杆细胞分布多，对暗光敏感；中央凹处视锥细胞密集，司明视觉和色觉。"},{"q":"胎儿和新生儿脑发育的关键激素是","o":["糖皮质激素","生长激素","甲状腺激素","肾上腺素","盐皮质激素"],"a":2,"e":"正确答案是甲状腺激素。甲状腺激素是胎儿、新生儿脑发育的关键激素，能促进神经元增殖分化、突触形成及髓鞘形成，妊娠中晚期及出生后第一年最为重要。"},{"q":"下列关于输血的叙述，错误的是","o":["再次输入同一相同血型个体的血液不需进行交叉配血","必要时O型血可输给其他血型的受血者","必要时AB型血的人可接受其他血型供血者的血液","Rh阴性的受血者不可接受Rh阳性的血液","Rh阳性的受血者可接受Rh阴性的血液"],"a":0,"e":"正确答案是再次输入同一相同血型个体的血液不需进行交叉配血。即使ABO血型相同，输血前也必须进行交叉配血试验，以检出其他不相容血型抗原或抗体。"},{"q":"安静时，机体产热的主要器官是","o":["肝脏","肾脏","大脑","骨骼肌","皮肤"],"a":0,"e":"正确答案是肝脏。安静时主要由内脏产热，约占总产热量的56%，内脏中肝脏代谢最旺盛、产热量最高；骨骼肌是运动时的主要产热器官。"},{"q":"衡量心肌自律性高低的指标是","o":["动作电位幅度","0期去极化速度","最大复极电位水平","4期自动去极化速度","复极化的时程"],"a":3,"e":"正确答案是4期自动去极化速度。自律性的高低取决于4期自动去极化速度、最大复极电位水平和阈电位水平，其中以4期自动去极化速度最为重要，速度越快自律性越高。"},{"q":"抑制性突触后电位","o":["由突触前末梢递质释放减少而产生","使突触后膜电位远离阈电位水平","由突触后膜钠电导增加而产生","由突触后膜钙电导增加而产生","是一种去极化抑制的突触后电位"],"a":1,"e":"抑制性突触后电位是突触后膜超极化，使膜电位远离阈电位，降低神经元兴奋性。教材指出IPSP由突触后膜超极化产生，故使突触后膜电位远离阈电位水平。"},{"q":"人幼年时期缺乏下列哪种激素可导致侏儒症","o":["T3","1,25-(OH)2-D3","GH","PRL","皮质醇"],"a":2,"e":"幼年期GH分泌不足导致生长停滞、身材矮小，称为侏儒症。教材明确幼年期GH分泌不足或GH受体缺陷均致生长障碍，rhGH治疗有效。"},{"q":"人体发烧时，体温每升高1℃，BMR将升高","o":["5%","13%","20%","25%","30%"],"a":1,"e":"发热时BMR升高，体温每升高1℃，BMR约升高13%。教材明确给出该数值，BMR测定是检测甲状腺功能的重要指标。"},{"q":"在横纹肌，引起肌丝滑行的始动步骤是","o":["肌质中Ca2+与肌钙蛋白结合","横桥ATP酶活性增高，使ATP分解","肌凝蛋白与肌动蛋白结合","横桥与肌动蛋白结合","钙泵活动增强"],"a":0,"e":"胞质Ca2+浓度升高后与肌钙蛋白TnC结合，引起肌钙蛋白构象变化，原肌球蛋白移开，暴露肌动蛋白横桥结合位点，是肌丝滑行的始动步骤。"},{"q":"大脑皮层调节内脏活动的主要结构是","o":["颞叶","边缘叶","枕叶","额叶","顶叶"],"a":1,"e":"边缘系统是调节内脏活动的高级中枢，边缘叶与岛叶、杏仁核、下丘脑等统称边缘系统。教材指出大脑皮层对内脏活动的调节主要基于边缘系统。"},{"q":"下列关于生理学的叙述，错误的是","o":["是生物科学的1个分支","是1门实验性科学","是1门重要的医学基础理论课程","其研究对象是生物体","研究水平仅包括系统器官和细胞分子两个方面"],"a":4,"e":"生理学研究水平包括细胞分子、器官系统、整体等多个层面，并非仅限系统器官和细胞分子两个方面。教材强调从细胞分子到整体水平的功能活动统一整合。"},{"q":"双侧海马功能的损失影响是","o":["丧失远程记忆","丧失工作记忆","丧失编码长期记忆中最近事件的能力","丧失回忆面孔和形态的能力，但不影响回忆印刷或口头文字","当回忆最近事件时产生不适当的情绪反应"],"a":2,"e":"长时程记忆的形成是在海马等脑区对信息分级加工的动态过程，双侧海马损伤导致丧失编码长期记忆中最近事件的能力，即顺行性遗忘。"},{"q":"下列哪一过程在神经末梢递质释放中起关键作用","o":["动作电位到达神经末梢","神经末梢去极化","神经末梢处的钠离子内流","神经末梢处的钾离子外流","神经末梢处的钙离子内流"],"a":4,"e":"递质释放量主要决定于进入突触前末梢的Ca2+量，Ca2+内流触发囊泡出胞释放递质，是递质释放的关键步骤。"},{"q":"下列关于食管下括约肌的叙述，正确的是","o":["由环行肌增厚而形成","括约肌部位压力低于胃内压","主要受激素调节而不受神经调节","血管活性肠肽引起括约肌紧张","功能障碍与反流性食管炎有关"],"a":4,"e":"食管下括约肌并非由环行肌增厚形成，而是食管下端近贲门处一段长3～5cm的高压区，其压力比胃内压高5～10mmHg，可阻止胃内容物反流。该括约肌受迷走神经抑制性和兴奋性纤维双重支配，VIP和NO引起其舒张。其张力降低时胃内容物反流入食管，与反流性食管炎发生有关。"},{"q":"左侧大脑皮层中央后回受损后，躯体感觉障碍的部位是","o":["左半身","右半身","左侧头面部","右侧头面部","双侧头面部"],"a":1,"e":"第一感觉区位于中央后回，躯体感觉投射呈交叉性，即一侧中央后回接受对侧半身的感觉传入。左侧中央后回受损，对侧即右半身的躯体感觉发生障碍。头面部感觉虽也投射至中央后回下部，但本题问的是半身感觉障碍部位。"},{"q":"调节血钙浓度最主要的激素是","o":["生长激素","降钙素","甲状腺激素","甲状旁腺激素","肾上腺皮质激素"],"a":3,"e":"甲状旁腺激素是调节血钙最主要的激素，其靶器官为肾脏和骨，通过促进肾小管对钙的重吸收和促进骨钙入血使血钙升高。血钙升高又可负反馈抑制甲状旁腺激素分泌，维持血钙稳态。降钙素作用相反，使血钙降低。"},{"q":"瘦素的分泌量主要反映体内哪种物质的储存量","o":["糖","蛋白质","脂肪","肌肉","ATP"],"a":2,"e":"瘦素主要由白色脂肪组织合成和分泌，体内脂肪储量是影响瘦素分泌的主要因素。在能量摄入与消耗平衡时，瘦素分泌量可反映体内储存脂肪量的多少，摄食时升高、禁食时降低。瘦素可抑制摄食、抑制脂肪合成并动员脂肪。"},{"q":"抵御化脓性细菌入侵的细胞是","o":["中性粒细胞","嗜碱性粒细胞","嗜酸性粒细胞","淋巴细胞","血小板"],"a":0,"e":"中性粒细胞是血液中主要的吞噬细胞，变形游走能力和吞噬活性均较强，是体内游走速度最快的细胞，也是首先到达炎症部位的效应细胞。其吞噬细菌后解体，释放溶酶体酶溶解周围组织而形成脓液，故是抵御化脓性细菌入侵的主要细胞。"},{"q":"右心室的每搏功为左心室每搏功的","o":["1/3","1/4","1/5","1/6","1/7"],"a":3,"e":"正常情况下左、右心室输出量基本相等，但肺动脉平均压仅为主动脉平均压的1/6左右，故右心室的做功量也只有左心室的1/6左右，每搏功亦为左心室的1/6。"},{"q":"通常所说的血型是指","o":["红细胞膜上的受体类型","红细胞表面特异凝集素的类型","红细胞膜上特异性抗原的类型","血浆中特异凝集素的类型","血浆中特异凝集原的类型"],"a":2,"e":"血型通常是指红细胞膜上特异性抗原的类型，这种抗原由种系基因控制，属多态性抗原，称为血型抗原。凝集素存在于血浆中，并非血型的定义依据。"},{"q":"胆汁中参与消化作用的主要成分是","o":["胆色素","胆盐","胆固醇","脂肪酸","卵磷脂"],"a":1,"e":"胆汁是唯一不含消化酶的消化液，其中最重要的成分是胆盐，主要作用是促进脂肪的消化和吸收。胆盐和卵磷脂可聚合成微胶粒，作为乳化剂降低脂肪表面张力，增加胰脂肪酶的作用面积。胆色素决定胆汁颜色，不参与消化。"},{"q":"自然呼吸情况下，PCO2升高对呼吸的刺激作用增强，其原因是","o":["血液H+浓度也升高","血液PO2降低","中枢化学感受器的敏感性增加","外周化学感受器的敏感性增加","CO2解离曲线的影响"],"a":0,"e":"PCO2升高时H+浓度也随之升高，两者对外周化学感受器的协同作用使肺通气反应比单纯PCO2升高时更强。血液H+不易进入细胞，故其单独刺激作用弱于CO2。"},{"q":"下列激素或因子中，可由下丘脑以外的组织产生的是","o":["催乳素释放因子","催乳素释放抑制因子","生长激素释放抑制激素","生长激素释放激素","促甲状腺激素释放激素"],"a":2,"e":"生长抑素即生长激素释放抑制激素，除下丘脑外还广泛存在于胃肠道、胰岛等组织。下丘脑调节激素中催乳素释放因子结构尚未明确，其余均由下丘脑产生。"},{"q":"关于神经胶质细胞生理作用的描述中，错误的是","o":["小胶质细胞可清除受损的神经组织碎片","星形胶质细胞可稳定细胞外钾离子浓度","星形胶质细胞参与构成血-脑屏障","施万细胞参与形成髓鞘","成熟的神经胶质细胞不具有增殖的能力"],"a":4,"e":"胶质细胞终身具有分裂增殖的能力，故“成熟胶质细胞不能增殖”错误。小胶质细胞可吞噬清除碎片，星形胶质细胞稳定细胞外K+并参与血-脑屏障，施万细胞形成周围神经髓鞘。"},{"q":"下列选项中，不属于下丘脑的功能的是","o":["调节体温","维持水平衡","协调随意运动","控制生物节律","调控摄食行为"],"a":2,"e":"协调随意运动是小脑的功能，小脑参与运动的策划与执行比较并纠正偏差。下丘脑是体温、水平衡、摄食行为和生物节律的重要调节中枢。"},{"q":"人眼暗适应过程的实质是","o":["视力的提高","视野的增大","光感受器的适应","视色素合成增加","色素上皮突起缩回"],"a":3,"e":"暗适应第二次明显下降是暗适应的主要阶段，与视杆细胞中视紫红质合成增强有关。最初5分钟的下降主要与视锥细胞视色素合成增加有关。"},{"q":"关于视力的叙述，下列哪一项是正确的","o":["色盲患者视力减弱","中央凹视力比周边区高","是测量视网膜对光的敏感度指标","单眼视物比双眼视物时的视力高","黄斑处视力最高是因为此处视锥细胞多而集中，呈聚合联系"],"a":1,"e":"中央凹处视锥细胞密度最高且与双极细胞、神经节细胞呈一对一单线联系，会聚程度低，故视敏度最高。色盲是色觉障碍，不影响视敏度。"},{"q":"下列各项调节中，属于自身调节的是","o":["动脉血压在80～160mmHg范围内变动时，肾血流量可保持相对恒定","全身动脉血压升高时，血压水平下降","过度通气后，呼吸暂停","水量摄入多时，尿量增加","机体酸中毒时，泌酸增加"],"a":0,"e":"肾血流量自身调节指动脉血压在一定范围内变动时肾血流量保持相对恒定，不依赖神经和体液因素。血压升高后降压属压力感受性反射，过度通气后呼吸暂停属化学感受性反射。"},{"q":"关于紧张性收缩的叙述，下面说法错误的是","o":["是胃肠共有的运动形式","有助于消化管保持正常的形态和位置","有助于消化液渗入食物中","当紧张性收缩减弱时，食物吸收加快","是其他运动形式的基础"],"a":3,"e":"紧张性收缩减弱时胃肠蠕动和混合减慢，消化液与食物混合不充分，食物消化吸收减慢而非加快。紧张性收缩是其他运动形式的基础，并维持消化管形态位置。"},{"q":"兴奋通过神经-肌接头时，乙酰胆碱与受体结合使终板膜","o":["对钠、钾离子通透性增加，发生超极化","对钠、钾离子通透性增加，发生去极化","仅对钾离子通透性增加，发生超极化","仅对钙离子通透性增加，发生超极化","对乙酰胆碱通透性增加，发生超极化"],"a":1,"e":"乙酰胆碱与终板膜N2型受体结合后，通道对Na+、K+高度通透，以Na+内流为主，使终板膜去极化产生终板电位。"},{"q":"在胚胎期对脑发育最为重要的激素是","o":["生长激素","胰岛素","甲状腺激素","糖皮质激素","绒毛膜生长素"],"a":2,"e":"甲状腺激素是胎儿、新生儿脑发育的关键激素，胚胎期促进神经元增殖分化及髓鞘形成。生长激素主要促进躯体生长。"},{"q":"血浆晶体渗透压主要来自血浆的","o":["NaCl","葡萄糖","白蛋白","球蛋白","纤维蛋白"],"a":0,"e":"血浆晶体渗透压由晶体物质形成，其中80%来自Na+和Cl-，故主要来自NaCl。"},{"q":"以下哪项抑制胰岛素的分泌","o":["交感神经兴奋","血中氨基酸及脂肪酸增加","抑胃肽分泌增加","迷走神经兴奋","血糖升高"],"a":0,"e":"交感神经兴奋释放去甲肾上腺素，主要经α受体抑制胰岛β细胞分泌胰岛素。血糖升高、氨基酸及抑胃肽均促进胰岛素分泌。"},{"q":"下列哪种激素促进胰岛素分泌的作用最为明显","o":["生长抑素","糖皮质激素","抑胃肽","甲状腺激素","生长激素"],"a":2,"e":"抑胃肽在血糖升高时刺激胰岛素释放，属生理性调节，是胃肠激素中促胰岛素分泌作用最明显者。"},{"q":"下列激素哪种不是类固醇激素","o":["糖皮质激素","雄激素","催乳素","皮质酮","雌激素"],"a":2,"e":"催乳素是含199个氨基酸的蛋白质激素，而糖皮质激素、雄激素、皮质酮、雌激素均属类固醇激素。"},{"q":"下列关于淋巴管及淋巴回流的描述，错误的是","o":["毛细淋巴管以盲端起始于组织","组织液中颗粒可进入毛细淋巴管，但不能倒流","组织液静水压升高时，淋巴回流将减少","组织液中的红细胞、细菌可经淋巴回流重吸收","正常成年人安静时的淋巴回流量约120ml/h"],"a":2,"e":"组织液静水压升高使组织液与毛细淋巴管间压力差增大，促进组织液进入淋巴管，淋巴回流增多而非减少。"},{"q":"异相睡眠所特有的表现是","o":["脑电呈现慢波","机体感觉增强","交感神经系统活动增强","骨骼肌肌紧张增强","眼球快速运动、躯体抽动等阵发性表现"],"a":4,"e":"异相睡眠（REM睡眠）的特征性表现为眼球快速运动、躯体抽动及血压升高、心率呼吸加快等阵发性表现，同时肌紧张进一步减弱。"},{"q":"实现胃的容受性舒张的途径是","o":["交感神经","迷走神经末梢释放的乙酰胆碱","迷走神经末梢释放的血管活性肠肽","壁内神经释放的生长抑素","内分泌细胞释放促胃泌素"],"a":2,"e":"容受性舒张通过迷走-迷走反射实现，其传出纤维为抑制性纤维，节后纤维释放的递质是血管活性肠肽和NO。乙酰胆碱作用于M受体引起消化道收缩而非舒张。"},{"q":"下列各体液中，不属于机体内环境范畴的是","o":["血浆","细胞内液","组织间液","淋巴液","脑脊液"],"a":1,"e":"内环境指细胞外液，包括血浆、组织液、淋巴液和脑脊液等。细胞内液分布于细胞膜内，不属于内环境范畴。"},{"q":"下列关于大肠功能的叙述，错误的是","o":["储存食物残渣，形成粪便","大肠液有保护黏膜、润滑粪便的作用","大肠内的细菌可合成B族维生素和维生素K","进食后往往可发生集团蠕动","大肠液中的消化酶对消化起重要作用"],"a":4,"e":"大肠液主要成分为黏液和HCO3-，起保护肠黏膜和润滑粪便作用，所含二肽酶和淀粉酶对物质分解作用不大。大肠内的细菌可合成B族维生素和维生素K。"},{"q":"神经元之间所存在的电突触结构基础是","o":["缝隙连接","曲张体","混合性突触","交互性突触","串联性突触"],"a":0,"e":"电突触以电流为传递媒质，其结构基础是缝隙连接，缝隙连接构成细胞间低电阻通道，使兴奋快速、双向传播。"},{"q":"下列关于心交感传入反射的叙述，错误的是","o":["交感传入末梢可感受化学刺激","交感传入末梢也可感受心室扩张引起的机械刺激","该反射可增强交感神经活动","该反射属于负反馈调节","该反射有利于在心肌缺血时维持血压"],"a":3,"e":"心交感传入反射反射性引起交感神经活动增强和动脉血压升高，属于正反馈调节。压力感受性反射才是典型的负反馈调节。"},{"q":"区分心肌快、慢反应细胞的依据是","o":["收缩力的大小","0期去极化的速率","平台期的长短","3期复极化的快慢","4期自动去极化的速度"],"a":1,"e":"快反应细胞0期去极化由钠通道介导，速度快、幅度大；慢反应细胞0期由L型钙通道介导，速度慢。0期去极化速率是区分二者的依据。"},{"q":"雄激素的生理作用不包括","o":["促进生殖器官的发育","促进附性器官发育","促进肌肉、骨骼蛋白质合成","促进肾脏Na＋、水排出","维持正常性行为"],"a":3,"e":"睾酮参与调节水电解质平衡，有类似肾上腺皮质激素的作用，导致体内钠、水潴留。促进肾脏Na+、水排出是心房利尿钠肽的作用。"},{"q":"下列关于肺牵张反射的叙述，正确的是","o":["感受器存在于肺实质中","正常人平静呼吸时，对呼吸节律起重要调节作用","传入神经是迷走神经","可促进呼气及时转入吸气","无明显的种属差异"],"a":2,"e":"肺牵张反射的感受器位于呼吸道平滑肌中，冲动经迷走神经传入延髓，其作用是加速吸气向呼气转换。该反射存在明显种属差异，正常人平静呼吸时作用很小。"},{"q":"当呼吸幅度减小而呼吸频率加快时，受影响最大的是","o":["肺通气量","无效腔气量","肺泡通气量","功能余气量","肺扩散容量"],"a":2,"e":"肺泡通气量等于潮气量减去无效腔气量后乘以呼吸频率，呼吸幅度减小使潮气量减少，其中无效腔气量相对固定，故肺泡通气量下降最明显。深慢呼吸比浅快呼吸更有利于肺泡气体更新。"},{"q":"关于瘦素的分泌特点，以下哪项是错误的","o":["具有昼夜节律","只有白色脂肪组织合成分泌","体脂量可影响瘦素的分泌","摄食时，瘦素分泌增多","大多肥胖者瘦素分泌增多"],"a":1,"e":"瘦素主要由白色脂肪组织合成和分泌，褐色脂肪组织、胎盘、肌肉和胃黏膜也可少量合成，故“只有白色脂肪组织合成分泌”错误。瘦素分泌有昼夜节律，受体内脂肪储量影响，肥胖者瘦素分泌增多。"},{"q":"特殊动力效应最为显著的食物是","o":["糖类","蛋白质","胆固醇","甘油三酯","混合性食物"],"a":1,"e":"进食蛋白质产生的特殊动力效应最显著，约为30%，即摄入可提供100kJ能量的蛋白质时额外耗能可达30kJ。糖类和脂肪的特殊动力效应分别为6%和4%。"},{"q":"脑桥呼吸调整中枢的主要功能是","o":["促使吸气转为呼气","促使呼气转为吸气","减慢呼吸频率","接受肺牵张反射的传入信息","使吸气缩短和呼气延长"],"a":0,"e":"脑桥上部为呼吸调整中枢，主要含呼气神经元，其作用是限制吸气，使吸气向呼气转换。切断迷走神经后该中枢仍可抑制长吸中枢，防止出现长吸式呼吸。"},{"q":"构成动态阻力的主要成分是","o":["黏滞阻力","惯性阻力","气道阻力","肺弹性阻力","胸廓弹性阻力"],"a":2,"e":"肺通气阻力分为弹性阻力和非弹性阻力，非弹性阻力即动态阻力，包括气道阻力、惯性阻力和黏滞阻力，其中气道阻力占主要成分。气道阻力主要发生在鼻、声门及气管支气管等大气道。"},{"q":"激素传递的方式不包括","o":["血液运送","经组织液扩散","神经轴浆运输","经腺体导管分泌","自分泌"],"a":3,"e":"激素分泌后经血液运送、组织液扩散、神经轴浆运输或自分泌等方式作用于靶细胞。经腺体导管分泌是外分泌腺的分泌方式，不属于激素传递途径。"},{"q":"含氮激素发挥作用的第一步是","o":["与细胞膜上的专一性受体结合","与胞浆受体结合","与核内受体结合","使细胞内的ATP转变为cAMP","与核内DNA结合"],"a":0,"e":"含氮激素多为水溶性，不能自由通过细胞膜，需先与靶细胞膜上的专一性受体结合，再经细胞内信号转导系统产生调节效应。类固醇激素才与胞浆或核内受体结合。"},{"q":"下列哪项属于雌激素的生理作用","o":["促进破骨细胞活动","刺激血管平滑肌增殖","促进神经细胞生长","降低高密度脂蛋白浓度","降低肾小管对Na+、水重吸收"],"a":2,"e":"雌激素可促进神经细胞的生长发育、突触形成，并调节神经肽和递质的合成与释放。雌激素还抑制破骨细胞活动、保护血管舒张功能、升高高密度脂蛋白并促进肾小管对Na⁺和水的重吸收。"},{"q":"能抑制血小板聚集的前列腺素是以下哪种","o":["PGA2","PGI2","PGE2","PGF2","PGA1"],"a":1,"e":"PGI2由血管内皮细胞合成，可提高血小板内cAMP含量，抑制血小板聚集并舒张血管。TXA2作用相反，促进血小板聚集；阿司匹林通过减少TXA2生成发挥抗聚集作用。"},{"q":"关于胰腺分泌HCO3-的叙述，错误的是","o":["由胰腺内小导管上皮细胞分泌","缩胆囊素可引起大量分泌","可防止盐酸对十二指肠黏膜的侵蚀","可为胰酶提供适宜的作用环境","迷走神经兴奋引起胰液分泌的特点是HCO3-较少"],"a":1,"e":"缩胆囊素主要促进胰液中各种酶分泌，对HCO3-分泌作用弱；促胰液素才刺激胰腺小导管上皮细胞大量分泌HCO3-。HCO3-可中和盐酸、保护十二指肠黏膜，并为胰酶提供适宜碱性环境。"},{"q":"人耳最敏感的声波频率范围是","o":["0～1000Hz","1000～3000Hz","3000～5000Hz","5000～10000Hz","8000～20000Hz"],"a":1,"e":"人耳最敏感的声波频率为1000～3000Hz，人的语言频率主要在300～3000Hz范围内，此频段听阈最低。"},{"q":"心脏交感神经节前神经元位于","o":["延髓腹外侧","颈段脊髓中央灰质侧角","胸腰段脊髓中央灰质前角","胸腰段脊髓中央灰质侧角","骶髓中央灰质侧角"],"a":3,"e":"心交感神经节前神经元胞体位于第1～5胸段脊髓中间外侧柱（侧角），属胸腰段脊髓中央灰质侧角。骶髓侧角为副交感节前神经元所在。"},{"q":"健康雄性8周龄Wistar大鼠，通过高脂、高糖、高盐饮食喂养16周，建立代谢综合征大鼠模型，并观察代谢综合征时动物的基本病理改变和相关代谢指标的变化，这种实验方法属于","o":["急性离体动物实验","慢性在体动物实验","急性在体动物实验","急性动物实验","实时在体监测实验"],"a":1,"e":"该实验在整体动物身上经16周长期喂养观察代谢指标变化，属慢性在体动物实验。急性实验是在短时间内对活体标本或整体动物观察干预。"},{"q":"能较好评价肺通气功能的指标是","o":["潮气量","补呼气量","余气量","用力肺活量","功能余气量"],"a":3,"e":"用力肺活量反映肺组织弹性状态和气道通畅程度，能较好评价肺通气功能；肺活量不限制呼气时间，在弹性降低或气道狭窄时仍可正常。"},{"q":"甘氨酸受体的阻断剂是","o":["4-羟基喹啉酸","氯胺酮","荷包牡丹碱","士的宁","印防己毒素"],"a":3,"e":"士的宁是甘氨酸受体的阻断剂，阻断后引起中枢神经系统过度兴奋而惊厥。破伤风毒素则阻断闰绍细胞释放甘氨酸。"},{"q":"营养物质在体内氧化所释放的能量，迅速转化为热能占总量的","o":["20%以上","30%以上","50%以上","70%以上","80%以上"],"a":2,"e":"营养物质在体内氧化分解释放的能量中，50%以上直接转化为热能，其余以化学能储存于ATP等高能化合物中供机体利用。"},{"q":"兴奋下丘脑内渗透压感受器可引起","o":["血管升压素释放增加","心房钠尿肽释放增加","血管紧张素Ⅱ合成增加","心肺感受器兴奋","肾素释放增加"],"a":0,"e":"正确答案是血管升压素释放增加。血浆晶体渗透压升高刺激下丘脑渗透压感受器，经渗透压感受性神经元调节视上核和室旁核大细胞神经元释放血管升压素。心房钠尿肽由心房肌细胞受牵张刺激释放。"},{"q":"下列有关等容舒张期的说法错误的是","o":["室内压下降","心房血液流向心室","发生在收缩期结束后","半月瓣处于关闭状态","房室瓣处于关闭状态"],"a":1,"e":"正确答案是心房血液流向心室。等容舒张期房室瓣与半月瓣均关闭，心室为封闭腔，室内压快速下降，无血液由心房流入心室。心房血液流向心室发生在快速充盈期，此时房室瓣开放。"},{"q":"具有促进青春期女性乳腺基础性发育作用的重要激素是","o":["甲状腺激素","生长激素","催乳素","雌激素","皮质醇"],"a":3,"e":"正确答案是雌激素。青春期女性乳腺的发育主要依赖生长激素对乳腺间质和脂肪组织的作用，而雌激素对乳腺基础性发育起促进作用，孕激素在雌激素作用基础上进一步促进腺泡发育。"},{"q":"关于消化道运动作用的描述，下列说法错误的是","o":["磨碎食物","使食物与消化液充分混合","使食物大分子水解成小分子","向消化道远端推送食物","和化学性消化同时进行"],"a":2,"e":"正确答案是使食物大分子水解成小分子。消化道运动属机械性消化，作用是磨碎食物、与消化液充分混合并推送食物；大分子水解为小分子由消化腺分泌的酶完成，属化学性消化。"},{"q":"渗透压感受器位于","o":["球旁器","下丘脑","延髓","右心房","颈动脉体"],"a":1,"e":"正确答案是下丘脑。血浆晶体渗透压改变刺激位于下丘脑前部室周器的渗透压感受器，进而调节血管升压素分泌。颈动脉体为化学感受器，右心房为容量感受器所在。"},{"q":"肾脏中尿素最容易通透的部位是","o":["近曲小管","髓袢升支","髓袢降支细段","远端小管和集合管","内髓集合管"],"a":4,"e":"正确答案是内髓集合管。内髓部集合管末端依赖抗利尿激素调控的尿素通道蛋白UT-A1和UT-A3，对尿素高度通透，使浓缩尿素扩散至内髓部组织。髓袢降支细段仅中等通透。"},{"q":"下列情况可引起颈动脉窦的传入神经冲动增加的是","o":["循环血量降低","PaO2降低","PaCO2升高","血液中H+增多","平均动脉压升高"],"a":4,"e":"正确答案是平均动脉压升高。颈动脉窦压力感受器感受血管壁机械牵张，动脉血压升高时管壁牵张加大，传入冲动增多。PaO2、PaCO2及H+变化由化学感受器感受。"},{"q":"严重营养不良引起的水肿的主要原因是","o":["毛细血管血压升高","组织液静水压降低","组织液胶体渗透压升高","血浆胶体渗透压降低","淋巴回流受阻"],"a":3,"e":"正确答案是血浆胶体渗透压降低。严重营养不良致血浆蛋白减少，血浆胶体渗透压降低，有效胶体渗透压下降，有效滤过压增大，组织液生成增多而发生水肿。"},{"q":"保钠排钾作用最强的肾上腺皮质激素是","o":["醛固酮","皮质醇","皮质酮","去氧皮质酮","可的松"],"a":0,"e":"醛固酮是肾上腺皮质球状带分泌的盐皮质激素，生物活性最强，主要作用于肾脏远曲小管和集合管，促进钠重吸收、钾排泄，保钠排钾作用最强。11-脱氧皮质酮作用次之。"},{"q":"人眼的调节功能主要是由下列哪个来实现的","o":["角膜的曲度变化","角膜和晶体的曲度变化","晶体的曲度变化","玻璃体的曲度变化","晶体和玻璃体的曲度变化"],"a":2,"e":"人眼调节主要通过改变晶状体曲度完成，视近物时睫状肌收缩、晶状体变凸以增强折光力。角膜曲度不可调节。"},{"q":"下列哪种激素可促进的1,25-(OH)2-D3的形成","o":["PTH","三碘甲腺原氨酸","四碘甲腺原氨酸","CT","TSH"],"a":0,"e":"PTH可诱导肾小管上皮细胞1α-羟化酶基因转录，促进25-羟维生素D3转化为1,25-二羟维生素D3。1,25-二羟维生素D3生成增多时负反馈抑制该酶活性。"},{"q":"下列哪种激素由非内分泌腺器官产生","o":["甲状旁腺素","降钙素","醛固酮","心房钠尿肽","胰高血糖素"],"a":3,"e":"心房肌细胞属非内分泌器官，可合成和分泌心房利尿钠肽，参与机体水平衡调节。甲状旁腺素、降钙素、醛固酮、胰高血糖素均由经典内分泌腺分泌。"},{"q":"下列生理过程中，属于正反馈调节的是","o":["降压反射","排尿反射","体温调节","肺牵张反射","血糖浓度的调节"],"a":1,"e":"排尿反射中尿液刺激尿道进一步反射性加强排尿中枢活动，属正反馈，直至膀胱排空。降压反射、体温调节、肺牵张反射和血糖调节均为负反馈。"},{"q":"关于温度感受神经元，下列描述中哪一项是错误的","o":["视前区-下丘脑前部中的热敏神经元，在温度信息的整合中起重要作用","视前区副下丘脑前部存在着冷敏神经元","局部脑组织温度变动在0、3℃以上，温度感受神经元的放电频率才会发生变化","此类神经元全部存在于中枢神经系统内","脑干网状结构中以冷敏神经元为主"],"a":2,"e":"温度敏感神经元对温度变化十分敏感，局部组织温度变动0.1℃时放电频率即发生变化，故“0.3℃以上才变化”的描述错误。此类神经元并非全部存在于中枢，皮肤等外周也有温度感受器。"},{"q":"能促进ACTH分泌的下丘脑调节肽是","o":["TRH","GnRH","GHRH","CRH","PRF"],"a":3,"e":"下丘脑室旁核分泌的CRH经垂体门脉到达腺垂体，与ACTH细胞CRH-R1结合促进ACTH分泌。TRH、GnRH、GHRH分别促进TSH、促性腺激素、GH分泌。"},{"q":"下列属于主动转运的是","o":["安静时K＋由细胞内向细胞外转运","兴奋时Na＋由细胞外进入细胞内","葡萄糖由细胞外液进入一般细胞","Na＋由细胞内向细胞外转运","肌质网终池内的Ca2＋流入胞质"],"a":3,"e":"Na+由细胞内向外转运是逆浓度梯度的主动转运，由钠泵耗能完成。安静时K+外流和兴奋时Na+内流均为经通道的易化扩散，葡萄糖进入一般细胞为经载体易化扩散。"},{"q":"以下情况中，可使静脉回流量减少的是","o":["体循环平均充盈压升高","心脏收缩力量加强","由卧位转为立位时","有节律的慢跑","吸气时相"],"a":2,"e":"由卧位转为立位时，身体低垂部分静脉跨壁压增大而扩张，可多容纳约500ml血液，回心血量减少。体循环平均充盈压升高和心脏收缩力加强均使回心血量增加。"},{"q":"恒定强度的刺激持续作用于一个感受器时，其传入神经纤维上动作电位的频率逐渐降低，这一现象称为感受器的","o":["适宜刺激","换能作用","编码功能","适应现象","特异现象"],"a":3,"e":"恒定强度刺激持续作用于感受器时，传入神经纤维动作电位频率逐渐降低，称为感受器的适应现象，是感受器的共同特点。"},{"q":"可不经细胞核受体介导调节靶细胞活动的激素是","o":["促甲状腺素","糖皮质激素","钙三醇","孕激素","睾酮"],"a":0,"e":"促甲状腺素属与膜受体结合的激素，经G蛋白耦联受体介导发挥作用，不经细胞核受体。糖皮质激素、钙三醇、孕激素、睾酮均与胞内受体结合。"},{"q":"影响CO2与Hb结合生成氨基甲酰血红蛋白的主要因素是","o":["血液PO2","血液PCO2","氧化作用","氧合作用","碳酸酐酶的活性"],"a":3,"e":"CO2与Hb氨基结合生成氨基甲酰血红蛋白无须酶催化，调节该反应的主要因素是氧合作用，而非碳酸酐酶活性。"},{"q":"动物实验中，静脉注射乳酸使动物的呼吸加深、加快与下列哪种感受器有关","o":["细支气管平滑肌中的牵张感受器","呼吸肌本体感受器","颈动脉窦、主动脉弓感受器","颈动脉体、主动脉体感受器","中枢化学感受器"],"a":3,"e":"乳酸使动脉血H+浓度升高，刺激颈动脉体和主动脉体外周化学感受器，反射性引起呼吸加深加快。颈动脉窦、主动脉弓为机械感受器。"},{"q":"在中脑上下丘之间切断动物脑干，将会出现","o":["脊休克","去大脑僵直","昏睡不醒","站立不稳","运动共济失调"],"a":1,"e":"在中脑上、下丘之间切断脑干，中断皮层与脑干网状结构的联系，抑制区活动减弱、易化区占优势，出现去大脑僵直。"},{"q":"下列关于脊髓γ运动神经元的描述，正确的是","o":["支配骨骼肌梭外肌纤维","轴突末梢释放甘氨酸递质","兴奋性较α运动神经元低","活动随α运动神经元活动增强而减弱","可调节肌梭对牵张刺激的敏感性"],"a":4,"e":"γ运动神经元支配梭内肌纤维，兴奋性较α运动神经元高，其作用是调节肌梭对牵拉刺激的敏感性。"},{"q":"有关肝脏血液供应的叙述，下列正确的是","o":["肝动脉含有来自于小肠吸收的营养物质","门静脉是肝细胞供O2的主要来源","进入肝脏进行解毒的有害物质来源于肝动脉","成年人肝每分钟血流量为1000～1500ml","肝静脉窦具有储存血液的作用"],"a":4,"e":"正常时肝内静脉窦可储存一定量血液，机体失血时从窦内排出补充循环血量。门静脉输送小肠吸收的营养物质，肝动脉是供O2的主要来源。"},{"q":"神经纤维的阈电位是","o":["Na＋通道大量开放的膜电位临界值","Na＋通道开始关闭的膜电位临界值","K＋通道开始关闭的膜电位临界值","K＋通道大量开放的膜电位临界值","Na＋通道少量开放的膜电位临界值"],"a":0,"e":"阈电位是刚好能触发膜去极化与钠通道激活之间正反馈、使Na+通道大量开放的膜电位临界值。刺激达此值即爆发动作电位，其幅度不再随刺激强度增大。"},{"q":"在异丙肾上腺素作用（只增强心室肌收缩力）下，心室功能曲线向哪个方向移位","o":["正上方","右上方","左上方","右下方","左下方"],"a":0,"e":"心肌收缩能力增强使心室功能曲线向左上方移位，在相同前负荷下每搏功增加。异丙肾上腺素增强心肌收缩力，故曲线向左上方移位。"},{"q":"关于胃的蠕动，下列说法正确的是","o":["空腹时基本不发生","起始于胃底部","蠕动波向胃底和幽门两个方向传播","发生频率约为12次/分","抑制胃的排空"],"a":0,"e":"胃的蠕动在食物入胃后约5分钟开始，空腹时基本不发生。蠕动始于胃中部向幽门推进，频率约每分钟3次，可推进食糜并使其磨碎。"},{"q":"交感舒血管纤维末梢释放的递质是","o":["去甲肾上腺素","乙酰胆碱","肾上腺素","阿片肽","谷氨酸"],"a":1,"e":"交感舒血管纤维末梢释放乙酰胆碱，作用于血管平滑肌M受体引起舒血管效应。多数交感缩血管纤维释放去甲肾上腺素。"},{"q":"使肛门外括约肌开放的是","o":["腹下神经兴奋","迷走神经兴奋","盆神经兴奋","阴部神经抑制","交感神经抑制"],"a":3,"e":"肛门外括约肌为骨骼肌，受阴部神经支配，阴部神经抑制时外括约肌舒张而开放。盆神经兴奋引起肛门内括约肌舒张。"},{"q":"可引起射血分数增大的因素是","o":["心室舒张末期容积增大","动脉血压升高","心率减慢","心肌收缩能力增强","快速射血相缩短"],"a":3,"e":"心肌收缩能力增强使每搏量增加而心室舒张末期容积不变或减小，射血分数增大。动脉血压升高增加后负荷，使射血分数减小。"},{"q":"下列关于动作电位的描述，正确的是","o":["刺激强度小于阈值时，出现低幅度动作电位","刺激强度达到阈值后，再增加刺激强度能使动作电位幅度增大","动作电位一经产生，便可沿细胞膜作电紧张式扩布","传导距离较长时，动作电位的大小不发生改变","动作电位在离体神经纤维上的传导是单向性的"],"a":3,"e":"动作电位具有“全或无”特征，其幅度由钠通道性状和离子驱动力决定，传导距离延长时大小不变。局部电流传导非电紧张扩布，离体神经纤维上传导是双向的。"},{"q":"关于呼吸商的叙述，错误的是","o":["糖的呼吸商为1.00","脂肪的呼吸商为0.71","任何情况下，呼吸商不能大于1.00","是指一定时间内呼出的CO2量和吸入的O2量的比值","从非蛋白呼吸商可以推测体内氧化的糖和脂肪量的比例"],"a":2,"e":"呼吸商是一定时间内CO2产生量与耗氧量的比值，糖为1.00、脂肪约0.70。在过度通气等情况下CO2排出增多，呼吸商可大于1.00。"},{"q":"胰高血糖素能直接刺激下列哪种激素的分泌","o":["生长激素","胰岛素","糖皮质激素","瘦素","甲状腺激素"],"a":1,"e":"胰岛α细胞分泌的胰高血糖素可直接作用于β细胞促进胰岛素分泌，也可通过升高血糖间接促进。胰岛素和生长抑素则直接抑制胰高血糖素分泌。"},{"q":"肾小球滤过率可作为衡量肾功能的重要指标，体表面积为1.73m2的个体，其肾小球滤过率约为","o":["50ml/min","80ml/min","125ml/min","180ml/min","300ml/min"],"a":2,"e":"肾小球滤过率指单位时间内两肾生成的超滤液量，体表面积1.73m²的个体约为125ml/min。"},{"q":"下列各项中，能使肾小球有效滤过压降低的是","o":["血浆晶体渗透压升高","肾小球毛细血管血压升高","肾小囊内静水压降低","血浆胶体渗透压升高","肾小囊内胶体渗透压升高"],"a":3,"e":"血浆胶体渗透压是对抗超滤液生成的力量，其升高使有效滤过压降低。肾小球毛细血管血压升高、囊内压降低均使有效滤过压升高。"},{"q":"合成血红蛋白的基本原料是","o":["铁和叶酸","钴和维生素B12","蛋白质和内因子","铁和蛋白质","钴和蛋白质"],"a":3,"e":"蛋白质和铁是合成血红蛋白的重要原料，铁为合成血红蛋白的必需原料。叶酸和维生素B12是红细胞成熟所必需的物质。"},{"q":"胰液中不含","o":["HCO3-","胰蛋白酶原","糜蛋白酶原","肠激酶","胰淀粉酶"],"a":3,"e":"肠激酶由小肠腺分泌，存在于小肠液中，能激活胰蛋白酶原，胰液中不含肠激酶。胰液含HCO3-、胰蛋白酶原、糜蛋白酶原和胰淀粉酶。"},{"q":"小肠特有的运动形式是","o":["紧张性收缩","分节运动","蠕动","容受性舒张","集团蠕动"],"a":1,"e":"分节运动是以环形肌为主的节律性收缩与舒张交替进行的运动，为小肠特有的运动形式，使食糜与消化液充分混合并促进吸收。集团蠕动为大肠特有。"},{"q":"正常情况下，声波由外耳传入内耳最主要的途径是","o":["外耳道→鼓膜→听骨链→卵圆窗膜→内耳外淋巴","外耳道→鼓膜→听骨链→卵圆窗膜→内耳内淋巴","外耳道→鼓膜→鼓室空气→圆窗膜→内耳外淋巴","外耳道→鼓膜→鼓室壁→内耳内淋巴","颅骨→耳蜗骨壁→内耳外淋巴"],"a":0,"e":"气传导是声波传导的主要途径：声波经外耳道引起鼓膜振动，再经听骨链和卵圆窗膜传入耳蜗外淋巴。骨传导仅在气传导障碍时发挥作用。"},{"q":"下列哪项不属于胆汁的作用","o":["分解脂肪","乳化脂肪","促进脂肪吸收","刺激胆汁分泌","中和进入十二指肠内的胃酸"],"a":0,"e":"胆汁中的胆盐、卵磷脂等作为乳化剂使脂肪乳化成微滴，促进脂肪消化和吸收，并中和胃酸、刺激胆汁自身分泌；脂肪的分解由胰脂肪酶完成。"},{"q":"当心室肌细胞在兴奋后复极至-55~-60mV时，若细胞膜受到外来的阈上刺激，膜电位的变化是","o":["不产生电位变化","产生局部电位","产生慢反应动作电位","产生快反应动作电位","产生超级化"],"a":1,"e":"复极至-55~-60mV为局部反应期，给予强大阈上刺激仅引起局部反应，不能产生新的动作电位。"},{"q":"下列选项中，属于人类小脑半球中间部受损所特有症状的是","o":["肌张力降低","腱反射增强","静止性震颤","意向性震颤","位置性眼震颤"],"a":3,"e":"小脑半球中间部受损出现意向性震颤，即精细动作终末出现震颤、把握不住方向。静止性震颤见于帕金森病。"},{"q":"盆神经受损后，排尿功能障碍的表现是","o":["多尿","少尿","尿失禁","尿潴留","尿频"],"a":3,"e":"盆神经为支配膀胱的传出神经，受损后排尿反射不能发生，膀胱松弛扩张，大量尿液滞留于膀胱内，表现为尿潴留。尿失禁见于高位脊髓受损后骶部排尿中枢失去高位中枢控制而反射弧完好时。"},{"q":"以下最可能使血压在生理范围内趋于下降的情绪类型是","o":["恐惧","发怒","愉快","焦虑","痛苦"],"a":2,"e":"愉快属积极情绪，常伴副交感神经活动相对增强，使血压在生理范围内趋于下降。恐惧、发怒、焦虑、痛苦均属消极情绪，伴交感神经兴奋，血压升高。"},{"q":"兴奋性是指活组织细胞接受刺激产生反应的能力，下列有关兴奋性及其特征的描述，正确的是","o":["刺激都能引起机体的反应","动作电位去极化速度常被用作反映组织的兴奋性大小的指标","引起肌肉组织收缩反应的最大刺激称为最适刺激","阈强度是指能引起可兴奋组织细胞产生反应的最小刺激强度","组织细胞的兴奋性越低，其阈值也较低。"],"a":3,"e":"阈强度是能引起活组织细胞产生反应的最小刺激强度，是衡量兴奋性高低的指标，阈值越小兴奋性越高。刺激须具备足够强度、时间和强度-时间变化率才能引起反应；动作电位去极化速度不反映兴奋性大小。"},{"q":"正常情况下肺弹性阻力的主要来源是","o":["肺泡表面张力","肺表面活性物质","气道阻力","肺组织本身的弹性阻力","惯性阻力"],"a":0,"e":"肺泡表面张力是肺弹性阻力的主要来源，约占肺总弹性阻力的2/3，肺组织本身弹性成分仅占1/3。肺表面活性物质的作用是降低表面张力，气道阻力与惯性阻力属非弹性阻力。"},{"q":"调节红细胞生成的主要体液因素是","o":["雄激素","雌激素","甲状腺激素","促红细胞生成素","生长激素"],"a":3,"e":"促红细胞生成素（EPO）是调节红细胞生成的主要体液因素，CFU-E是其作用的主要靶细胞，肾脏合成和释放EPO。雄激素等可促进EPO合成，属间接影响。"},{"q":"下列有关中枢化学感受器的描述，正确的是","o":["对低氧敏感","血液中CO2的变化可直接刺激中枢化学感受器","对血液中H＋浓度变化敏感","生理性刺激是脑脊液和局部细胞外液中的H+","中枢化学感受器位于延髓腹内侧"],"a":3,"e":"中枢化学感受器的生理性刺激是脑脊液和局部细胞外液中的H+，而非CO2本身；血液中CO2需通过血-脑屏障使局部H+升高才起作用。中枢化学感受器对低氧不敏感，对血液H+变化也不敏感。"},{"q":"在体温调节中起调定点作用的可能是","o":["脊髓温度敏感神经元","延髓温度敏感神经元","网状结构温度敏感神经元","丘脑温度敏感神经元","PO/AH中的温度敏感神经元"],"a":4,"e":"PO/AH是机体最重要的体温调节中枢，其热敏与冷敏神经元的温度敏感特性决定调定点的设置。破坏PO/AH后产热和散热反应明显减弱或消失。"},{"q":"下列不是唾液的生理作用的是","o":["部分消化淀粉","部分消化蛋白质","湿润与溶解食物","清洁和保护口腔","杀菌作用"],"a":1,"e":"唾液含唾液淀粉酶，可水解淀粉为麦芽糖，但不含消化蛋白质的酶。唾液可湿润溶解食物、清洁保护口腔，溶菌酶和免疫球蛋白具杀菌抗病毒作用。"},{"q":"最重要的消化液是","o":["胃液","胰液","胆汁","小肠液","唾液"],"a":1,"e":"胰液含水解糖、脂肪和蛋白质三类营养物质的消化酶，是最重要的消化液。胰液分泌障碍时脂肪和蛋白质不能完全消化吸收，可引起脂肪泻。"},{"q":"促胃液素的主要作用是","o":["促进胃酸分泌","刺激胰液中碳酸氢盐分泌","促进胰液中胰酶分泌","促进胆汁分泌","促进胃蛋白酶分泌"],"a":0,"e":"促胃液素的主要作用是促进胃酸和胃蛋白酶原分泌，并促进胃肠运动。刺激胰液中碳酸氢盐分泌是促胰液素的作用，缩胆囊素才促进胰酶分泌。"},{"q":"能使滤过分数增加的因素是","o":["肾血流量增加","入球小动脉阻力增大","血浆胶体渗透压升高","肾小囊内压升高","入球小动脉阻力不变，出球小动脉阻力增大"],"a":4,"e":"滤过分数为肾小球滤过率与肾血浆流量之比。入球小动脉阻力不变而出球小动脉阻力增大时，肾小球毛细血管血压升高、滤过率增加，肾血浆流量减少，滤过分数增加。"},{"q":"肾小管超滤液中葡萄糖被重吸收的部位是","o":["髓袢降支","近端小管","髓袢升支","远端小管","集合管"],"a":1,"e":"滤过的葡萄糖均在近端小管，特别是其前半段经Na+-葡萄糖耦联转运体以继发性主动转运方式被重吸收。"},{"q":"平静吸气主要由哪组肌肉收缩所致","o":["肋间外肌和肋间内肌","肋间外肌和膈肌","肋间内肌和膈肌","肋间外肌和腹肌","肋间内肌和腹肌"],"a":1,"e":"平静吸气是主动过程，由膈肌和肋间外肌收缩完成；平静呼气则靠二者舒张实现，呼气肌不参与。"},{"q":"当血钾逐步升高时，心肌的兴奋性","o":["逐步升高","逐步降低","先升高后降低","先降低后升高","不变"],"a":2,"e":"血钾轻度升高使膜电位轻度去极化，与阈电位靠近，兴奋性升高；血钾明显升高时膜电位显著减小，钠通道部分或完全失活，兴奋性降低或丧失。"},{"q":"心血管系统中，顺应性最大的血管是","o":["弹性贮器血管","分配血管","阻力血管","交换血管","容量血管"],"a":4,"e":"静脉数量多、管壁薄、口径大、可扩张性大，容量大，称为容量血管，兼具血液储存库作用，其顺应性最大。"},{"q":"PTH分泌后能迅速引起血钙升高的机制是","o":["促进肾小管重吸收钙","促进骨液中的钙转运至血液中","刺激破骨细胞，增强骨溶解，释放骨钙","刺激成骨细胞活动，促进骨盐沉积","促进肾内钙三醇形成，增强小肠钙吸收"],"a":1,"e":"PTH可迅速将骨液中的钙转运至血液，使血钙快速升高；刺激破骨细胞增强骨溶解需大剂量持续作用，起效较慢。"},{"q":"胰岛素对脂肪代谢的调节作用是","o":["促进脂肪组织释放脂肪酸","抑制葡萄糖进入脂肪细胞","促进脂肪的合成与储存","增强脂肪酶的活性","增加酮体的生成"],"a":2,"e":"胰岛素促进脂肪的合成与储存，抑制脂肪的分解与利用，其机制包括抑制激素敏感性脂肪酶活性，减少甘油三酯分解。"},{"q":"影响人胚胎脑发育的关键激素是","o":["胰岛素","生长激素","肾上腺素","甲状腺激素","绒毛膜生长激素"],"a":3,"e":"甲状腺激素是胎儿、新生儿脑发育的关键激素，在妊娠中晚期及出生后第一年最为重要，能促进神经元增殖分化、突触形成和髓鞘形成。生长激素主要促进出生后骨骼生长。"},{"q":"具有局部兴奋特征的电信号是","o":["神经纤维的动作电位","神经干的动作电位","锋电位","终板电位","后电位"],"a":3,"e":"终板电位由终板膜钠通道开放引起，属局部电位，以电紧张方式扩布，不能远距离传播。动作电位和锋电位均为可传播的再生性电位。"},{"q":"CO2在体循环静脉血中运输时，将出现","o":["CO2与水反应在红细胞中转变成H+和HCO3-","H+被氧合血红蛋白缓冲","HCO3-从血浆进入红细胞内，同时交换出Cl-","HCO3-与血红蛋白结合","红细胞碱化"],"a":0,"e":"CO2进入红细胞后经碳酸酐酶催化与水生成H2CO3，解离为H+和HCO3-，HCO3-顺浓度梯度扩散入血浆并换出Cl-。H+由去氧血红蛋白缓冲，红细胞内HCO3-增多并不碱化。"},{"q":"心血管的基本中枢位于","o":["脊髓","延髓","中脑","下丘脑","大脑"],"a":1,"e":"延髓是调节心血管活动最基本的中枢，保持延髓及以下中枢完整即可维持接近正常的血压和心血管反射。脊髓调节能力低且不完善。"},{"q":"体外受精-胚胎移植的辅助生育技术中，以下不属于应用高效GnRH激动剂目的的是","o":["使腺垂体FSH分泌大量增加","促进卵泡颗粒分泌大量雌激素","使卵泡颗粒细胞FSH受体表达增加","使腺垂体内源性FSH分泌减少","促进卵泡发育成熟"],"a":3,"e":"GnRH激动剂持续作用使腺垂体GnRH受体下调，内源性FSH、LH分泌减少，从而控制卵泡发育时机。其目的并非使FSH分泌大量增加。"},{"q":"中性粒细胞的主要功能是","o":["产生抗体","吞噬异物","参与止血","释放细胞毒素","释放组胺"],"a":1,"e":"中性粒细胞变形游走能力和吞噬活性强，是首先到达炎症部位吞噬细菌的效应细胞。产生抗体由B细胞完成，释放组胺为嗜碱性粒细胞功能。"},{"q":"下列关于前庭器官适宜刺激的叙述正确的为","o":["前庭器官各类毛细胞的适宜刺激都是与纤毛的生长面相垂直的机械力的作用","半规管壶腹嵴的适宜刺激是匀速旋转运动","椭圆囊囊斑的适宜刺激是水平方向的直线变速运动","球囊囊斑的适宜刺激是垂直方向的角加速度运动","当头部以冠状轴为轴心进行旋转时，水平半规管受到的刺激最大"],"a":2,"e":"椭圆囊和球囊囊斑的适宜刺激是直线加速度运动，椭圆囊囊斑平面与地面平行，感受水平方向直线变速运动。半规管壶腹嵴感受角加速度而非匀速旋转。"},{"q":"除了大量的水和无机盐外，下列哪项不属于唾液的成分","o":["唾液淀粉酶","黏蛋白","溶菌酶","尿素和尿酸","内因子"],"a":4,"e":"内因子由胃壁细胞分泌，与维生素B12结合并促进其在回肠吸收，不属于唾液成分。唾液含唾液淀粉酶、黏蛋白、溶菌酶及尿素、尿酸等。"},{"q":"人们提取重物时，发挥作用的骨骼肌的工作形式是","o":["单收缩","不完全强直收缩","完全强直收缩","等长收缩","等张收缩"],"a":2,"e":"正常人体内骨骼肌收缩几乎都以完全强直收缩形式进行，后一次收缩叠加在前一次收缩的收缩期，有利于完成躯体运动和外力做功。提重物需持续强力收缩，故为完全强直收缩。"},{"q":"心脏副交感神经的节前神经元位于","o":["延髓","颈髓","胸髓","腰髓","骶髓"],"a":0,"e":"心迷走神经节前神经元胞体位于延髓的迷走神经背核和疑核，其节前纤维行走于迷走神经干中。延髓是调节心血管活动最基本的中枢。"},{"q":"临床上多胎妊娠主要的因素是","o":["初级卵泡生长停滞","窦状卵泡生长过快","优势卵泡选择机制异常","垂体分泌卵泡刺激素减少","下丘脑分泌GnRH减少"],"a":2,"e":"优势卵泡选择机制异常时，多个卵泡可同时成熟排卵，导致多胎妊娠。正常时仅FSH阈值最低的一个卵泡发育成熟，其余闭锁。"},{"q":"诱发弗雷德里克·格兰特·班廷思考胰岛素提取方法的病例是","o":["胆囊结石","胰腺炎","胰导管结石","肠梗阻","胰腺肿瘤"],"a":2,"e":"班廷受胰导管结扎后胰腺外分泌部萎缩而胰岛保留的启发，想到用结扎胰导管方法提取胰岛素。该病例为胰导管结石致胰导管阻塞。"},{"q":"促进胃排空的因素是","o":["胃内的氨基酸和肽浓度升高","十二指肠内的酸刺激","十二指肠内的脂肪浓度升高","十二指肠内渗透压升高","机械扩张刺激十二指肠"],"a":0,"e":"食物对胃的扩张刺激和蛋白质消化产物可引起胃幽门部G细胞释放促胃液素，促进胃运动而加速胃排空。十二指肠内的酸、脂肪及高渗液则抑制胃排空。"},{"q":"能显著提高血钙水平的激素是","o":["ACTH","CRH","CT","PTH","TSH"],"a":3,"e":"PTH作用于骨促进Ca2+释放、促进肾小管重吸收钙，使血钙升高，是升高血钙的主要激素。CT作用相反使血钙降低。"},{"q":"下列哪种因素使冠脉血流量增加最为明显","o":["动脉血流速度加快","心率加快","心肌收缩力减弱","射血速度加快","动脉舒张压升高"],"a":4,"e":"冠脉血流量主要取决于动脉舒张压的高低和心室舒张期的长短。动脉舒张压升高使冠脉灌注压增大，冠脉血流量明显增加。"},{"q":"下列关于Na+-K+泵的描述，错误的是","o":["仅分布在可兴奋细胞的细胞膜上","是一种镶嵌在细胞膜上的蛋白质","能分解ATP获能","活动增强时使细胞静息膜电位增大","能将Na+移出细胞外，将K+移入细胞内"],"a":0,"e":"Na+-K+泵广泛分布于各类细胞膜上，并非仅见于可兴奋细胞；其为膜蛋白，分解ATP供能，将Na+移出、K+移入细胞，活动增强使静息膜电位增大。"},{"q":"在心动周期中，下列哪一时期的左心房压最大","o":["快速充盈期末","减慢充盈期末","等容舒张期末","快速射血期末","减慢射血期末"],"a":2,"e":"等容舒张期末左心房压达最大。此时房内压超过室内压，二尖瓣即将开放，随后血液快速充盈心室，房内压随之下降。"},{"q":"突触前抑制的产生机制是","o":["突触前膜阈电位水平抬高","突触前末梢递质释放减少","突触前末梢释放抑制性递质","抑制性中间神经元兴奋","突触后膜产生IPSP"],"a":1,"e":"突触前抑制通过突触前末梢递质释放减少实现。其机制是突触前末梢Ca2+内流减少，使兴奋性递质释放量降低，突触后EPSP幅度减小。"},{"q":"氧解离曲线由正常位置向左移","o":["表明血液在一定PO2时氧含量减少","可发生在贫血时","表明血液流经组织时释放氧量增加","可见于贮存了数周的血液","可见于组织代谢增加时"],"a":3,"e":"氧解离曲线左移表示Hb对O2亲和力增高、P50减小，不利于O2释放。贮存数周的红细胞2,3-DPG减少，使曲线左移。"},{"q":"胆碱能交感节后纤维支配的效应器是","o":["心肌","胃肠平滑肌","汗腺","冠状血管","肾血管"],"a":2,"e":"支配汗腺的交感节后纤维属胆碱能纤维，释放ACh作用于M受体。多数交感节后纤维为肾上腺素能纤维。"},{"q":"肺通气的原动力来自","o":["肺内压和胸膜腔内压之差","肺的扩大和缩小","胸廓的扩大和缩小","呼吸肌的收缩和舒张","胸膜腔内压的周期性变化"],"a":3,"e":"呼吸肌收缩和舒张引起胸廓节律性扩大和缩小，是实现肺通气的原动力。肺内压与胸膜腔内压之差是直接动力。"},{"q":"在自动控制系统中，从受控部分发出到达控制部分的信息称为","o":["偏差信息","干扰信息","控制信息","反馈信息","自控信息"],"a":3,"e":"受控部分发出、反过来影响控制部分活动的信息称为反馈信息，如体温升高后温度感受器回输至体温调节中枢的信号。"},{"q":"下列关于电突触传递的描述，正确的是","o":["结构基础是离子通道","传递速度慢，潜伏期长","允许所有带电物质通过","一般为单向传递","可促进神经元的同步电活动"],"a":4,"e":"电突触以缝隙连接为结构基础，电阻低、传递快、双向，可促进神经元同步化活动。"},{"q":"损伤后可发生平衡障碍的小脑部位是","o":["左侧小脑外侧部","右侧小脑外侧部","小脑蚓部","绒球小结叶","小脑半球中间部"],"a":3,"e":"绒球小结叶即前庭小脑，参与身体姿势平衡调节。损伤后出现步基宽、站立不稳、步态蹒跚，而随意运动协调不受影响。"},{"q":"某物质从肾小球滤过后又被全部重吸收，该物质的肾血浆清除率为","o":["大于肾小球滤过率","等于肾小球滤过率","小于肾小球滤过率","等于零","等于肾小球血浆流量"],"a":3,"e":"某物质滤过后被全部重吸收，则尿中排出量为零，其清除率等于零。清除率小于GFR提示净重吸收。"},{"q":"某患者急需大量输血，与B型供血者行交叉配血实验主次侧均发生凝集反应，该患者血型为","o":["A型","B型","O型","AB型","Rh型"],"a":0,"e":"主侧凝集说明受血者血清含抗供血者红细胞的抗体，次侧凝集说明供血者血清含抗受血者红细胞的抗体。B型供血者红细胞含B抗原、血清含抗A抗体，受血者红细胞既被抗B凝集又被抗A凝集，其红细胞含A、B两种抗原，即AB型。"},{"q":"人坐在飞机里面，当飞机在升降时，做吞咽动作有助于平衡（ ）两侧的压力，缓解耳部耳鸣、耳痛等不适感","o":["鼓膜","前庭窗膜","圆窗膜","前庭膜","基底膜"],"a":0,"e":"咽鼓管开放使鼓室内气压与外界大气压相等，以维持鼓膜两侧压力平衡和鼓膜正常位置与功能。飞机升降时做吞咽动作开放咽鼓管，可平衡鼓膜两侧压力，缓解耳痛、耳鸣。"},{"q":"静脉注射20%葡萄糖50ml，尿量增加的主要原因是","o":["肾小管液溶质浓度增高","肾小球滤过率增高","有效滤过压增高","醛固酮分泌增加","血浆晶体渗透压增高"],"a":0,"e":"静脉注射高渗葡萄糖使血糖超过肾糖阈，近端小管不能全部重吸收，小管液溶质浓度升高，渗透压增大使水重吸收减少，尿量增加，即渗透性利尿。"},{"q":"以下可以增加动作电位沿神经传导的速度的途径为","o":["刺激Na+-K+泵","抑制Na+-K+泵","减小轴突直径","神经纤维髓鞘化","增加神经纤维长度"],"a":3,"e":"神经纤维髓鞘化使动作电位只在郎飞结处发生，呈跳跃式传导，显著提高传导速度，直径4µm的有髓纤维即可达25m/s。减小轴突直径会增大传导阻力而减慢速度。"},{"q":"下列哪项不是导致子宫内膜功能层剥离、脱落出现月经的主要原因","o":["体内促性腺激素水平降低","体内雌激素水平降低","体内孕激素水平降低","体内催乳素水平降低","体内促性腺激素释放激素水平降低"],"a":3,"e":"月经期子宫内膜功能层剥脱出血，是因黄体退化使血中雌、孕激素水平骤降，螺旋小动脉痉挛收缩所致。催乳素水平降低并非月经来潮的触发因素。"},{"q":"影响血流阻力的最主要的因素是","o":["血液黏度","血管长度","小动脉口径","小静脉口径","大动脉的顺应性"],"a":2,"e":"血流阻力与血管半径的4次方成反比，与黏滞度和长度成正比。同一血管床内长度与黏滞度变化不大，口径是影响阻力的最主要因素，产生阻力的主要部位是微动脉。"},{"q":"肾上腺皮质功能不足的患者，排出水分的能力大为减弱，可出现“水中毒”，补充下列哪种激素可缓解症状","o":["胰岛素","糖皮质激素","醛固酮","肾上腺素","胰高血糖素"],"a":1,"e":"糖皮质激素具有允许作用，可降低肾小管对水的通透性、促进水排出，并维持循环血量。肾上腺皮质功能不足时排水能力减弱，补充糖皮质激素可缓解水中毒。"},{"q":"细胞膜对Na＋通透性增加时，静息电位将","o":["增大","减小","不变","先增大后减小","先减小后增大"],"a":1,"e":"静息电位主要由K+平衡电位决定，膜对Na+通透性增大时Na+内流增多，静息电位负值减小，即向ENa方向偏移。"},{"q":"细胞膜结构中，促使4,5-二磷酸磷脂酰肌醇（PIP2）分解生成IP3和DG的物质是","o":["磷脂酶C","乙酰胆碱酯酶","蛋白激酶C","腺苷酸环化酶","磷酸二酯酶"],"a":0,"e":"磷脂酶C是G蛋白效应器酶，可水解膜脂PIP2生成IP3和DG两种第二信使。腺苷酸环化酶催化cAMP生成，磷酸二酯酶则降解cAMP和cGMP。"},{"q":"小管液中的Na+浓度影响肾小球滤过是通过","o":["颗粒细胞","足细胞","髓袢","远端小管和集合管","致密斑"],"a":4,"e":"致密斑位于远曲小管起始部，能感受小管液中NaCl含量的变化，将信息反馈至球旁细胞调节肾素释放，参与管-球反馈。颗粒细胞是肾素合成释放部位，并非感受Na+浓度的结构。"},{"q":"O2的利用系数是指","o":["血液流经组织时所含O2量占血O2容量的百分数","血液流经组织释放出的O2容积占动脉血O2含量的百分数","血液流经组织释放出的O2容积占动脉血O2容量的百分数","血液流经组织时释放出的O2含量占动脉血O2含量的百分数","动脉血流经组织时释放出的O2含量占动脉血O2容量的百分数"],"a":1,"e":"O2利用系数指血液流经组织时释放出的O2容积占动脉血O2含量的百分数，反映组织对氧的利用程度。安静时该系数约为25%。"},{"q":"分泌钾的主要部位是","o":["近曲小管","髓袢降支细段","髓袢升支细段","髓袢升支粗段","远曲小管和集合管"],"a":4,"e":"K+的分泌主要发生在远曲小管和集合管，受醛固酮调节，与Na+重吸收相偶联。近端小管和髓袢以重吸收为主，分泌K+很少。"},{"q":"不属于原发性主动转运的物质是","o":["肌质网钙泵对钙离子的摄取","胃腺壁细胞分泌氢离子","钠-钾泵转运钠离子","质子泵转运氢离子","肾小管对葡萄糖的重吸收"],"a":4,"e":"肾小管对葡萄糖的重吸收经Na+-葡萄糖同向转运体完成，属继发性主动转运，能量来自Na+顺电化学梯度移动所释放的能量。钠泵、质子泵、钙泵均为原发性主动转运。"},{"q":"如果外周阻力不变，每搏输出量增大，则动脉血压的变化为","o":["收缩压升高，舒张压降低","收缩压不变，舒张压升高","收缩压升高，舒张压不变","收缩压升高比舒张压升高更明显","舒张压升高比收缩压升高更明显"],"a":3,"e":"每搏输出量增大时收缩压明显升高，因血流加快使舒张期存留血量增加不多，舒张压升高幅度较小，故脉压增大。收缩压高低主要反映每搏输出量的多少。"},{"q":"关于前庭自主神经反应的叙述，正确的是","o":["可见于前庭器官受到的刺激过弱时","主要表现为躯体运动神经功能失调","有皮肤苍白、恶心呕吐、心率加快、血压升高及唾液分泌增加等症状","前庭感受器不敏感的人，即使一般强度的前庭刺激也会导致明显的自主神经反应","晕船、晕车是前庭自主神经反应的表现"],"a":4,"e":"晕船、晕车是前庭器官受过度刺激引起的前庭自主神经反应。该反应表现为皮肤苍白、恶心、呕吐、出汗、心率加快、血压下降等自主神经功能失调，而非躯体运动神经障碍。"},{"q":"下列物质中属于类固醇激素的是","o":["促甲状腺激素","生长激素","生长激素介质","甲状旁腺素","糖皮质激素"],"a":4,"e":"糖皮质激素由肾上腺皮质束状带分泌，属类固醇激素，可进入细胞内与核受体结合调节基因转录。促甲状腺激素、生长激素、甲状旁腺素均为肽类激素。"},{"q":"触发骨骼肌细胞收缩的离子是","o":["钠离子","钾离子","钙离子","氯离子","镁离子"],"a":2,"e":"触发骨骼肌收缩的离子是Ca2+，其与肌钙蛋白结合启动横桥周期。钠、钾离子参与动作电位产生与复极，并非收缩触发因子。"},{"q":"当细胞膜上的电压门控Ca2+通道开放增加后，细胞的膜电位","o":["将向钾离子的平衡电位移动","细胞膜内外电位差增大","将远离钠离子的平衡电位","将远离钙离子的平衡电位","将发生去极化"],"a":4,"e":"电压门控Ca2+通道开放使Ca2+内流，正电荷进入细胞，膜内负电位减小，发生去极化。钙离子平衡电位为正，内流使膜电位趋近而非远离钙平衡电位。"},{"q":"下列物质的清除率最高的是","o":["肌酐","菊粉","葡萄糖","碘锐特","氨基酸"],"a":3,"e":"碘锐特经肾小球滤过和肾小管排泌后几乎全部从血浆清除，其清除率可代表有效肾血浆流量，约660ml/min，为所测物质中最高。菊粉清除率仅代表肾小球滤过率。"},{"q":"下列关于肌紧张的描述，正确的是","o":["由快速牵拉肌腱而引起","感受器是肌梭","人类以屈肌肌紧张为主要表现","为单突触反射","反射持久进行时易疲劳"],"a":1,"e":"肌紧张属牵张反射，其感受器为肌梭，肌梭感受肌肉长度变化，传入冲动兴奋同一肌肉的α运动神经元。肌紧张为多突触反射，以伸肌表现为主，持久进行不易疲劳。"},{"q":"体内交感-肾上腺髓质系统兴奋，心输出量增加是主要通过动用","o":["心率储备和收缩期储备","心率储备和舒张期储备","收缩期储备和舒张期储备","搏出量储备","舒张期储备"],"a":0,"e":"交感-肾上腺髓质系统兴奋时，机体主要通过动用心率储备和收缩期储备使心输出量增加。舒张期储备有限，并非主要动用途径。"},{"q":"心交感神经节后纤维释放的神经递质是","o":["乙酰胆碱","去甲肾上腺素","血管紧张素Ⅱ","血管升压素","缓激肽"],"a":1,"e":"心交感神经节后纤维释放去甲肾上腺素，作用于心肌β1受体产生正性变时、变力、变传导效应。乙酰胆碱为心迷走神经节后纤维的递质。"},{"q":"自律细胞与非自律细胞的区别是","o":["0期去极化的快慢","1期复极化的快慢","2期平台期的有无","3期复极化的快慢","4期自动去极化的有无"],"a":4,"e":"自律细胞与非自律细胞的根本区别在于4期有无自动去极化，4期自动去极化是产生自动节律性兴奋的基础。工作细胞4期膜电位稳定，无自动去极化。"},{"q":"临床上，因房水循环障碍引起眼内压升高、视力下降的疾病是","o":["近视眼","远视眼","散光眼","老视眼","青光眼"],"a":4,"e":"房水循环障碍致房水排出受阻、眼压病理性升高，称为青光眼，可压迫视神经致视力下降。近视、远视、散光属折光异常，老视属调节能力减退。"},{"q":"下列关于肺循环特征的描述，错误的是","o":["血流阻力低","平均动脉压低","循环血量少","血容量变化范围大","有效滤过压为负值"],"a":2,"e":"肺循环血容量约占全身血量的9%，并非“循环血量少”，且肺血管可扩张性大、血容量变化范围大。肺循环血流阻力低、平均动脉压低，有效滤过压为负值，均符合其特征。"},{"q":"关于中枢兴奋传播特征的描述，错误的是","o":["单向传递","对内环境变化敏感","不衰减传递","兴奋节律可发生变化","易发生疲劳"],"a":2,"e":"中枢兴奋传播需经多级化学突触接替，易受内环境变化影响、易疲劳，呈单向传递且兴奋节律可改变。不衰减传递是动作电位在同一细胞膜上传导的特征，并非突触传递特征。"},{"q":"下列属于内脏疼痛的特点是","o":["迅速短暂","定位准确","分辨力好","情绪反应重","对炎症缺血刺激不敏感"],"a":3,"e":"内脏痛定位不明确、分辨力差，对炎症缺血等刺激敏感，常伴明显不愉快的情绪反应及恶心、出汗等自主神经反应。迅速短暂、定位准确是体表痛的特点。"},{"q":"治疗“水中毒”应补充","o":["糖皮质激素","盐皮质激素","抗利尿激素","甲状腺激素","胰岛素"],"a":0,"e":"水中毒时细胞外液低渗、水潴留，糖皮质激素可抑制抗利尿激素分泌并促进水排出，故用以治疗。盐皮质激素主司保钠排钾，不能纠正稀释性低钠。"},{"q":"关于缩宫素的主要生理作用，描述正确的是","o":["刺激输卵管收缩，促进卵子运行","刺激催乳素分泌，促进乳汁分泌","刺激乳腺肌上皮细胞收缩，使乳汁排出","促进非孕子宫收缩","大剂量可引起子宫肌发生节律性收缩"],"a":2,"e":"缩宫素与乳腺肌上皮细胞受体结合，引起肌上皮细胞收缩，使腺泡内压升高、乳汁经输乳管排出，即射乳作用。缩宫素不刺激催乳素分泌，对非孕子宫作用弱。"},{"q":"下列关于微循环血流动力学的描述，正确的是","o":["毛细血管前后阻力比约为2∶1","毛细血管前括约肌对血流量控制起主要作用","毛细血管前括约肌交替收缩和舒张50次/分","安静状态下同一时间内约20%的毛细血管处于开放状态","毛细血管前括约肌的舒缩主要受血中儿茶酚胺调节"],"a":3,"e":"安静状态下骨骼肌同一时间内仅约20%～35%的毛细血管开放，与当时代谢水平相适应。毛细血管前括约肌的舒缩主要受局部代谢产物调节，而非血中儿茶酚胺。"},{"q":"关于简化眼模型的叙述正确的是","o":["正常人眼在视近物时成像情况的模型","简化眼的角膜前面至节点的距离为15mm","平行光线经过一次折射被聚焦于视网膜上","由曲率半径为15mm的单球面折光体构成","简化眼中单球面的曲率半径为20mm"],"a":2,"e":"简化眼将眼折光系统简化为一个折射率为1.333的单球面，平行光线经一次折射即聚焦于视网膜。该球面曲率半径为5mm，节点在折射界面后方5mm处。"},{"q":"可抑制血小板聚集的物质是","o":["ADP","TXA2","PGI2","胶原","凝血酶"],"a":2,"e":"PGI2由血管内皮细胞产生，可提高血小板内cAMP含量，具有较强抑制血小板聚集和舒张血管的作用。TXA2则降低血小板内cAMP而促进聚集，两者作用相反。"},{"q":"关于非特异感觉投射系统的描述，正确的是","o":["包括丘脑投向大脑皮层的所有纤维","自大脑皮层返回丘脑的纤维也可归入此系统","是各种不同感觉的共同上传通路","主要与大脑皮层第四层的神经元构成突触联系","电刺激该系统可引起皮层感觉区持续放电"],"a":2,"e":"非特异感觉投射系统经丘脑髓板内核群弥散投射至大脑皮层广泛区域，是各种不同感觉的共同上传通路，起维持和改变皮层兴奋状态的作用。其纤维主要终止于皮层浅层，而非第四层。"},{"q":"在肾素-血管紧张素系统中，具有极强缩血管效应的是","o":["肾素","血管紧张素Ⅰ","血管紧张素Ⅱ","血管紧张素Ⅲ","血管紧张素转换酶"],"a":2,"e":"血管紧张素Ⅱ是已知最强的缩血管活性物质之一，可直接收缩全身微动脉，使血压升高。肾素为蛋白水解酶，血管紧张素Ⅰ基本无缩血管活性，血管紧张素转换酶为生成血管紧张素Ⅱ的酶。"},{"q":"出现去大脑僵直现象是由于","o":["切除了大部分脑干网状结构抑制区","切除了大部分脑干网状结构易化区","切断了网状结构和皮层运动区及纹状体之间的联系","切断了网状结构和小脑之间的联系","切断了网状结构和前庭核之间的联系"],"a":2,"e":"去大脑僵直是在中脑水平切断脑干，中断了大脑皮层、纹状体等部位与脑干网状结构抑制区的功能联系，使抑制区活动减弱、易化区活动占优势所致。切断部位并未切除抑制区本身。"},{"q":"下列哪种维生素的激活形式，可作为一种能显著影响钙吸收与代谢的激素","o":["维生素A","维生素B复合体","维生素C","维生素D","维生素K"],"a":3,"e":"维生素D经肝、肾羟化生成1，25-二羟维生素D3，后者与核受体结合调节基因表达，促进小肠钙吸收和骨钙代谢，是发挥激素样作用的活性形式。维生素A、C、K不参与钙吸收调节。"},{"q":"在神经纤维发生动作电位期间，按照下图中的箭头所示给予一次阈上刺激后，会发生的情况是","o":["出现较小幅度的动作电位","出现正常幅度的动作电位","延迟发生动作电位","不会发生动作电位","出现局部电位"],"a":3,"e":"官方题库缺失图片"},{"q":"下列关于脂联素的生物学作用，哪项是错误的","o":["抑制外周组织对葡萄糖的摄取","增加靶细胞对胰岛素的敏感性","促进血浆中游离脂肪酸氧化","减少脂肪合成","抗炎、保护心肌"],"a":0,"e":"脂联素可增强外周组织对葡萄糖的摄取和利用，提高靶细胞对胰岛素的敏感性，促进脂肪酸氧化、减少脂肪合成，并具抗炎、保护心肌作用。抑制外周组织摄取葡萄糖是抵抗素等的作用。"},{"q":"肺换气是指","o":["外呼吸","机体与外界环境的气体交换","肺与外界环境的气体交换","血液与组织细胞之间O2和CO2的交换","肺泡与肺毛细血管血液之间O2和CO2的交换"],"a":4,"e":"肺换气指肺泡与肺毛细血管血液之间的气体交换，O2由肺泡扩散入血、CO2由血扩散入肺泡。肺通气是肺泡与外界环境的气体交换，组织换气发生在血液与组织细胞之间。"},{"q":"γ-运动神经元的机能是","o":["使梭外肌兴奋收缩","降低肌梭的敏感性","使梭内肌收缩","使梭内肌弛缓","使梭外肌弛缓"],"a":2,"e":"γ运动神经元发出纤维支配骨骼肌梭内肌纤维，其兴奋使梭内肌收缩，调节肌梭对牵拉刺激的敏感性。梭外肌由α运动神经元支配。"},{"q":"下列关于胆汁分泌与排出的叙述，正确的是","o":["肝细胞分泌胆汁是间断的","胆汁是持续进入十二指肠的","在食物消化期的头期和胃期胆囊收缩由CCK引起","在食物消化的肠期胆囊收缩主要由迷走神经兴奋引起","进食开始后数分钟胆囊便开始收缩排放胆汁"],"a":4,"e":"进食开始后数分钟，通过迷走神经反射及促胃液素等作用，胆囊即开始收缩并排放胆汁。非消化期肝胆汁持续分泌并储存于胆囊，并非间断分泌，也不持续进入十二指肠。"},{"q":"利用动物实验，如何来证明颈动脉窦压力感受性反射是负反馈调节","o":["注射去甲肾上腺素，引起血压升高","注射肾上腺素，引起心率加快","注射ACh，引起血压下降","刺激迷走神经，引起血压下降","分离颈动脉窦，改变窦内压，观察动物血压的变化"],"a":4,"e":"分离颈动脉窦并改变窦内压，体循环血压随窦内压升高而降低，说明窦内压升高经压力感受性反射引起血压回降，构成负反馈调节。该窦内压与动脉血压变化的关系曲线即压力感受性反射功能曲线。"},{"q":"第二信使是指激素、神经递质、细胞因子等第一信使分子作用于","o":["胞膜受体后产生的细胞内信使分子","胞浆受体后产生的信使分子","核受体后产生的信使分子","胞膜受体及核受体后产生的信使分子","胞膜受体及胞浆受体后产生的信使分子"],"a":0,"e":"第二信使是激素、神经递质、细胞因子等细胞外第一信使作用于膜受体后产生的细胞内信使分子，cAMP为其典型代表。胞内受体介导的激素作用不产生第二信使。"},{"q":"关于胞内受体介导的作用机制描述错误的是","o":["启动DNA转录，促进mRNA形成","诱导新蛋白质生成","细胞内受体是指定位在细胞质或细胞核中的受体","胞内受体介导的过程中细胞内会产生第二信使","可直接进入细胞内与胞质受体结合"],"a":3,"e":"胞内受体最终转入胞核启动DNA转录、促进mRNA形成并诱导新蛋白质生成，此过程不产生第二信使；第二信使由膜受体激活效应器酶生成。"},{"q":"体内组织器官主要依靠糖的有氧氧化供能的是","o":["心肌和平滑肌","心肌和骨骼肌","平滑肌和消化腺","脑和心肌","肾和肾上腺"],"a":3,"e":"脑组织主要依赖葡萄糖的有氧氧化供能，低血糖或缺氧时易出现脑功能障碍；心肌同样以有氧氧化为主要供能方式。成熟红细胞缺乏有氧氧化酶系，主要依靠无氧氧化供能。"},{"q":"剧烈运动中，骨骼肌温度的升高将对氧解离曲线产生的影响是","o":["无影响","左移，从而减少骨骼肌毛细血管中氧的释放","右移，从而减少骨骼肌毛细血管中氧的释放","左移，从而增加骨骼肌毛细血管中氧的释放","右移，从而增加骨骼肌毛细血管中氧的释放"],"a":4,"e":"温度升高时Hb对O2的亲和力降低，P50增大，氧解离曲线右移，促进O2释放。剧烈运动时骨骼肌产热增多、温度升高，使骨骼肌毛细血管处氧释放增加。"},{"q":"一条神经干中许多纤维在同时传导兴奋时互不干扰，其主要原因是","o":["髓鞘对电流的绝缘作用","细胞膜的膜电阻很大","细胞外液对电流的短路作用","生物电很微弱，干扰也很微弱","动作电位只沿膜内侧传向远处"],"a":2,"e":"神经纤维被相对大容量的细胞外液浸泡，局部电流在细胞外液内向各方向均匀分散并迅速衰减，效应如同接地，故同时传导兴奋时互不干扰。"},{"q":"肾上腺素的生理作用不包括","o":["使心跳加快，心肌收缩力增强，心输出量增加","使皮肤与肾脏的小动脉收缩，骨骼肌的小动脉与冠状动脉舒张","可加速肝糖原分解","大剂量引起血压下降，小剂量引起全部血管收缩，血压升高","使支气管平滑肌舒张"],"a":3,"e":"肾上腺素小剂量以兴奋β2受体为主使骨骼肌、肝血管舒张，大剂量时α受体也兴奋引起血管收缩、血压升高，并非大剂量降压、小剂量使全部血管收缩。"},{"q":"目前认为控制生物节律的主要核团是","o":["松果体","下丘脑室旁核","下丘脑视交叉上核","下丘脑视上核","外侧膝状体"],"a":2,"e":"下丘脑视交叉上核是哺乳动物控制日节律的关键部位，使内源性日节律适应外界昼夜节律，其机制与调控松果体褪黑素分泌有关。松果体为受其调控的效应结构。"},{"q":"影响PTH分泌最重要的因素是","o":["血磷浓度","血钙离子浓度","血镁离子浓度","血中儿茶酚胺浓度","血中前列腺素浓度"],"a":1,"e":"血钙水平是调节PTH分泌最主要的因素，血钙降低可直接促进PTH的合成和分泌。血磷、血镁等仅通过改变血钙间接影响PTH分泌。"},{"q":"胃酸的生理作用不包括","o":["激活胃蛋白酶原，并为胃蛋白酶提供一个酸性作用环境","杀死进入胃内的细菌","促进胰液和胆汁的分泌","促进维生素B12的吸收","与钙和铁结合，形成可溶性盐，促进钙和铁的吸收"],"a":3,"e":"维生素B12的吸收依赖胃壁细胞分泌的内因子，而非胃酸。胃酸可激活胃蛋白酶原、杀菌、促进胰液和胆汁分泌，并与钙、铁结合形成可溶性盐促进其吸收。"},{"q":"发生突触前抑制的关键结构基础是","o":["轴突-胞体型突触","轴突-轴突型突触","轴突-树突型突触","缝隙连接","胞体-胞体型突触"],"a":1,"e":"经典的突触前抑制发生于轴突-轴突-胞体式联系中，即突触前末梢A与另一轴突末梢B形成轴突-轴突式突触，故其关键结构基础是轴突-轴突型突触。"},{"q":"甲状腺激素负反馈调节主要作用部位是","o":["下丘脑促垂体区","腺垂体","神经垂体","下丘脑室旁核","下丘脑视上核"],"a":1,"e":"血中TH浓度升高时主要负反馈作用于腺垂体TSH细胞，下调TRH受体数量及对TRH的敏感性，并直接抑制TSH的合成与分泌。"},{"q":"食物的氧热价是指","o":["1g食物氧化时所释放的能量","1g食物燃烧时所释放的能量","食物氧化消耗1L氧气所释放的能量","氧化1g食物、消耗1L氧气时所释放的能量","食物氧化释放1L二氧化碳时所产生的能量"],"a":2,"e":"氧热价指某种食物氧化时消耗1L O2所产生的热量，反映耗氧量与产热量之间的关系。1g食物氧化释放的能量为食物的生物热价。"},{"q":"体内PCO2最高的部位是","o":["组织液","细胞内液","静脉血液","动脉血液","外周毛细血管血液"],"a":1,"e":"CO2由细胞有氧代谢产生，故细胞内液PCO2最高，可高达50mmHg以上，并顺分压差依次向组织液、血液扩散。"},{"q":"下列有关ABO血型系统的叙述，正确的是","o":["新生儿血浆中存在IgG型抗A或抗B抗体","新生儿血浆中存在IgM型抗A或抗B抗体","新生儿红细胞上A或B抗原的含量与成人相同","新生儿血浆中存在的抗A或抗B抗体是自己产生的","新生儿体内的A或B抗原只存在于红细胞上"],"a":0,"e":"新生儿体液免疫尚未成熟，自身不产生ABO血型抗体，血浆中的抗A或抗B抗体为来自母体的IgG型抗体。天然抗体属IgM，不能通过胎盘。"},{"q":"副交感舒血管纤维末梢释放的神经递质是","o":["去甲肾上腺素","肾上腺素","乙酰胆碱","P物质","血管活性肠肽"],"a":2,"e":"副交感舒血管纤维属胆碱能纤维，末梢释放乙酰胆碱使血管舒张。去甲肾上腺素为交感缩血管纤维递质。"},{"q":"细胞膜内、外，正常的Na＋和K＋浓度的维持主要是由于","o":["膜在安静时对K＋的通透性高","膜在兴奋时对Na＋的通透性增加","Na＋、K＋易化扩散的结果","膜上Na＋-K＋泵的作用","Na＋外流，K＋内流"],"a":3,"e":"正确答案是膜上Na⁺-K⁺泵的作用。细胞膜两侧Na⁺、K⁺浓度差由钠泵活动形成和维持，每分解一分子ATP将3个Na⁺移出、2个K⁺移入，从而建立并保持这种梯度。安静时K⁺通透性高和兴奋时Na⁺通透性增加只是梯度驱动的跨膜扩散，不能维持浓度差。"},{"q":"不影响糖代谢的激素是","o":["甲状腺激素","生长激素","皮质醇","胰岛素","甲状旁腺激素"],"a":4,"e":"正确答案是甲状旁腺激素。PTH的靶器官主要是肾脏和骨，通过影响肾小管钙磷重吸收和促进骨钙入血调节血钙血磷稳态，不参与糖代谢调节。甲状腺激素、生长激素、皮质醇和胰岛素均对糖代谢有明确影响。"},{"q":"在外周感觉传入神经，神经元的动作电位一般首先发生在","o":["胞体","轴突末梢","轴突始段","周围突距离胞体最近的第1个郎飞结","周围突距离远端末梢最近的第1个郎飞结"],"a":4,"e":"正确答案是周围突距离远端末梢最近的第1个郎飞结。感受器电位以电紧张形式扩布，到达感觉神经第一个郎飞结时去极化达阈电位即爆发动作电位；该处电压门控钠通道密度明显高于感受器部位。"},{"q":"能使动脉血压波幅增大的原因是","o":["心动过速","房室瓣狭窄","主动脉瓣狭窄","大动脉硬化","小动脉硬化"],"a":3,"e":"正确答案是大动脉硬化。主动脉和大动脉的弹性贮器作用可减小动脉血压在心动周期中的波动幅度，大动脉硬化使弹性贮器作用减弱，收缩压升高、舒张压降低，血压波幅增大。小动脉硬化主要使外周阻力增大而升高平均动脉压。"},{"q":"青春期的启动与下列哪种物质的脉冲性释放有关","o":["GHRH","TRH","CRH","GnRH","PRH"],"a":3,"e":"正确答案是GnRH。下丘脑被认为是青春期的始动者，GnRH神经元成熟后呈脉冲式释放，经垂体门脉系统促进腺垂体分泌FSH和LH，从而启动性成熟。"},{"q":"突触传递中，影响神经末梢递质释放量的关键因素是","o":["传到末梢的动作电位幅度","末梢膜电位的水平","末梢内线粒体的数量","末梢内囊泡的数量","进入末梢内的钙离子量"],"a":4,"e":"正确答案是进入末梢内的钙离子量。递质释放量主要决定于进入突触前末梢的Ca²⁺量，凡促进末梢Ca²⁺内流的因素均增加递质释放，抑制Ca²⁺内流则减少释放。动作电位幅度通过改变Ca²⁺内流间接起作用。"},{"q":"具有分泌肾素功能的结构是","o":["致密斑","系膜细胞","颗粒细胞","间质细胞","近髓肾单位"],"a":2,"e":"正确答案是颗粒细胞。球旁细胞也称颗粒细胞，是入球小动脉管壁中特殊分化的平滑肌细胞，内含分泌颗粒，可分泌肾素。致密斑为化学感受器，不分泌肾素。"},{"q":"心内兴奋传导最易发生阻滞的部位是","o":["窦房结","房室交界","左、右束支","浦肯野纤维","房室束"],"a":1,"e":"正确答案是房室交界。兴奋在房室交界区传导速度最慢，形成PR段，故最易发生传导阻滞，临床上PR间期延长常见于房室传导阻滞。"},{"q":"调节胰高血糖素分泌的最重要因素是","o":["生长激素分泌量","血中氨基酸浓度","胰岛素分泌量","生长抑素分泌量","血糖浓度"],"a":4,"e":"血糖水平是调节胰高血糖素分泌的最重要因素。低血糖时胰高血糖素分泌增加，促进肝糖原分解使血糖升高，故正确答案为血糖浓度。"},{"q":"某人因肾病长期大量用糖皮质激素治疗，该患者不会因此而出现","o":["血糖升高","蛋白质合成增加","面部和躯干脂肪合成增加","红细胞、血小板增多","淋巴细胞减少"],"a":1,"e":"糖皮质激素抑制肝外组织蛋白质合成、加速其分解，长期大量使用不会出现蛋白质合成增加。GC还升高血糖、引起脂肪向躯干面部重新分布、使红细胞和血小板增多、淋巴细胞减少。"},{"q":"胰高血糖素对糖代谢作用的靶器官是","o":["肌肉","小肠","肝","大脑","肾"],"a":2,"e":"胰高血糖素的主要靶器官是肝脏，与肝细胞膜受体结合后激活糖原磷酸化酶、脂肪酶和糖异生相关酶，促进肝糖原分解和糖异生而升高血糖。"},{"q":"震颤麻痹的主要症状之一是","o":["感觉迟钝","肌张力增强","意向性震颤","运动共济失调","身体平衡失调"],"a":1,"e":"震颤麻痹（帕金森病）因黑质多巴胺能神经元变性，对新纹状体的抑制减弱，表现为肌张力增高、运动减少和静止性震颤。意向性震颤和共济失调见于小脑病变。"},{"q":"心交感神经兴奋后，对心肌细胞的影响是","o":["肌质网释放钙离子减少","肌质网对钙离子的摄取减慢","自律细胞4期If电流减少","P细胞动作电位0期速度和幅度加大","平台期钙离子内流减少"],"a":3,"e":"心交感神经兴奋释放去甲肾上腺素，作用于β1受体使慢反应自律细胞（P细胞）0期Ca2+内流增强，0期去极化速度和幅度加大，自律性升高。同时肌质网对Ca2+摄取加快、释放增多。"},{"q":"机体的内环境是指","o":["体液","细胞内液","细胞外液","血浆","组织液"],"a":2,"e":"生理学中把细胞外液称为内环境，因为体内细胞直接接触和生存的环境就是细胞外液。血浆和组织液均属细胞外液，范围过窄。"},{"q":"下列物质属于第二信使的是","o":["AC和GC","IP3和DG","PKA和PKC","PLC和PLA","CaM和CaMK"],"a":1,"e":"IP3和DG是受体-G蛋白-PLC通路产生的第二信使，IP3动员Ca2+释放，DG激活PKC。AC、GC为酶，PKA、PKC为蛋白激酶，均非第二信使。"},{"q":"地震被困于废墟下3天未进食的情况下，机体主要的供能物质是","o":["葡萄糖","肝糖原","肌糖原","脂肪","蛋白质"],"a":3,"e":"长期饥饿时糖原耗尽，机体主要依靠脂肪分解供能，呼吸商接近0.70。脂肪是体内主要的储能物质，供能占机体消耗能量的30%～50%。"},{"q":"正常人体内环境的理化特性经常保持","o":["固定不变","相对恒定","随机多变","绝对平衡","与外界一致"],"a":1,"e":"内环境稳态是指内环境理化性质相对恒定的动态平衡状态，而非静止不变的固定状态。稳态在各种生理活动调节下局限于一定范围内变动，是机体自我调节的结果。"},{"q":"血流阻力主要来自","o":["大动脉","小动脉、微动脉","中动脉","微静脉","毛细血管"],"a":1,"e":"血流阻力与血管半径的四次方成反比，小动脉和微动脉口径小、血流阻力最大，是产生外周阻力的主要部位。大动脉为弹性储器血管，主要起缓冲血压作用。"},{"q":"下列各项生物电的表现，异相睡眠区别于觉醒的是","o":["脑电波呈δ波","肌电明显减弱","眼电明显减弱","心电明显减弱","脑电波呈α波"],"a":1,"e":"异相睡眠时脑电呈低幅高频去同步化快波，与觉醒相似，但骨骼肌反射和肌紧张进一步减弱，肌电明显减弱。觉醒时肌电活动较强，故肌电减弱是二者的关键区别。"},{"q":"作用于二级支气管以下部位的感受器而引起咳嗽反射的有效刺激是","o":["机械牵张","温度改变","刺激性气味","二氧化碳浓度升高","缺氧"],"a":2,"e":"咳嗽反射的传入神经为迷走神经，其感受器分布于喉、气管和支气管黏膜，对机械性和化学性刺激敏感。刺激性气味可刺激呼吸道黏膜感受器而触发咳嗽反射。"},{"q":"在动物实验中，当动脉血压在80～180mmHg之间波动时肾血流并不随动脉血压的增高而增加，此时肾血流保持相对稳定。若要证明这是肾脏自身调节的结果，应采用的研究方法是","o":["急性离体动物实验","急性在体动物实验","慢性离体实验","慢性动物实验","动物细胞培养"],"a":0,"e":"肾血流自身调节在去神经离体肾灌注实验中仍存在，说明其不依赖神经和体液因素，属肌源性。急性离体动物实验可排除神经体液影响，是证明自身调节的经典方法。"},{"q":"血清与血浆的最主要区别在于血清缺乏","o":["纤维蛋白","纤维蛋白原","凝血酶","血小板","凝血因子"],"a":1,"e":"血液凝固时纤维蛋白原转变为纤维蛋白并参与血凝块形成，故血清中缺乏纤维蛋白原。血清与血浆的最主要区别在于血清缺乏纤维蛋白原。"},{"q":"远端小管和集合管所分泌的氨主要来自","o":["精氨酸","甘氨酸","丙氨酸","谷氨酰胺","亮氨酸"],"a":3,"e":"近端小管、髓袢升支粗段和远曲小管上皮细胞内的谷氨酰胺在谷氨酰胺酶作用下脱氨生成NH4+，是肾小管泌氨的主要来源。"},{"q":"A型标准血清与B型血液混合时可引起","o":["血液凝固","红细胞凝集","红细胞叠连","红细胞收缩","无反应"],"a":1,"e":"A型标准血清含抗B凝集素，与B型红细胞膜上的B凝集原相遇发生抗原-抗体反应，使红细胞凝集成簇，本质为红细胞凝集。"},{"q":"既能储存能量又能直接供能的物质是","o":["脂肪","葡萄糖","ATP","ADP","磷酸肌酸"],"a":2,"e":"ATP既是直接的供能物质，又是能量储存的重要形式，兼具储存能量与直接供能两种功能。脂肪和磷酸肌酸只储存能量，不能直接供能。"},{"q":"心电图中可以看到的变化是","o":["窦房结去极化","窦房结复极化","心房肌去极化","房室结去极化","房室束去极化"],"a":2,"e":"P波反映左、右两心房的去极化过程，是常规体表心电图可记录到的变化。窦房结体积小、综合电位小，其去极化在体表心电图上记录不到。"},{"q":"胆碱能M型受体存在于","o":["所有副交感节后纤维支配的效应器上","神经-肌接头的后膜上","交感、副交感神经节细胞的突触后膜上","所有副交感神经节后纤维支配的效应器上及汗腺、骨骼肌血管上","大多数副交感神经节后纤维支配的效应器上及汗腺、骨骼肌血管上"],"a":4,"e":"M受体分布于大多数副交感节后纤维支配的效应细胞、汗腺细胞和骨骼肌血管平滑肌细胞，激活后产生M样作用。骨骼肌终板膜上为N2受体，神经节细胞突触后膜上为N1受体。"},{"q":"下列情况下能量代谢率最低的是","o":["室温在20～25°C","熟睡时","进食12小时后","安静时","运动后休息时"],"a":1,"e":"熟睡时各种生理功能活动减弱至更低水平，能量代谢率进一步降低，低于基础代谢率。基础代谢率是人体清醒时的最低能量代谢水平。"},{"q":"眼尽最大能力调节时所能看清物体的最近距离称为","o":["远点","节点","后主焦点","前主焦点","近点"],"a":4,"e":"眼视近物时，物体能被清晰成像在视网膜上的最近点称为近点，反映晶状体的调节能力。远点是人眼不作任何调节时所能看清物体的最远距离。"},{"q":"下列有关微循环的描述正确的是","o":["直捷通路不能与外周组织进行物质交换","动-静脉短路可与外周组织进行少量的物质交换","当环境温度升高时，直捷通路大量开放以增加散热","毛细血管血压取决于毛细血管前、后阻力的比值","微循环的血流量主要受交感神经和迷走神经的调控"],"a":3,"e":"毛细血管血压取决于毛细血管前、后阻力的比值，比值变小时毛细血管血压升高。动-静脉短路基本无物质交换，环境温度升高时开放的是动-静脉短路而非直捷通路。"},{"q":"心室肌细胞绝对不应期的产生是由于","o":["Na＋通道处于激活状态","Na＋通道处于备用状态","Na＋通道处于失活状态","Ca2＋通道处于激活状态","Ca2＋通道处于失活状态"],"a":2,"e":"绝对不应期内引起动作电位0期的钠通道处于失活状态，不能对传来的冲动发生反应，是不应期产生的内在原因。"},{"q":"抑制钠泵的活动会导致","o":["细胞内Na+浓度降低","细胞内K+浓度增加","细胞内Ca2+浓度增加","增加Na+-葡萄糖同向转运","增加Na+-Ca2+交换"],"a":2,"e":"抑制钠泵使胞内Na+浓度升高，Na+-Ca2+交换减少，胞内Ca2+浓度增加，心肌收缩力增强。洋地黄即通过此机制治疗收缩性心力衰竭。"},{"q":"硫氧嘧啶类药物可用于治疗甲状腺功能亢进，这是由于它能","o":["抑制甲状腺腺泡上皮细胞中的TPO活性","抑制肠吸收碘","抑制甲状腺的聚碘作用","抑制甲状腺激素的释放","促进甲状腺激素的灭活"],"a":0,"e":"硫氧嘧啶类药物通过抑制甲状腺过氧化物酶（TPO）活性而抑制甲状腺激素合成，TPO是催化TH合成的关键酶。该药不影响聚碘和激素释放，故不能选抑制聚碘或释放的选项。"},{"q":"临床上用α2受体激动剂（可乐定）治疗高血压是由于它能","o":["抑制心肌收缩力","减慢心率","舒张阻力血管","增加肾排水量","抑制突触前膜释放递质"],"a":4,"e":"可乐定激动突触前α2自身受体，抑制突触前膜对去甲肾上腺素的进一步释放，从而降低交感张力、降低血压。其降压并非通过直接抑制心肌收缩力或舒张阻力血管实现。"},{"q":"血中二氧化碳分压升高使呼吸运动增强，其主要刺激是","o":["脑脊液中氢离子浓度增加","动脉血中氧分压降低","动脉血中氢离子浓度增加","脑脊液中氧分压降低","脑脊液中二氧化碳分压升高"],"a":0,"e":"血液CO2易透过血-脑屏障，使脑脊液中H+浓度升高，而中枢化学感受器的生理性刺激是脑脊液和局部细胞外液中的H+，故主要通过此途径兴奋呼吸。血液H+不易透过血-脑屏障，主要经外周化学感受器起作用。"},{"q":"环境温度升高，超过体表温度时，机体维持体温正常的生理活动为","o":["交感神经兴奋，汗腺分泌","交感神经兴奋，皮肤血管平滑肌收缩","寒战","肾上腺素、甲状腺激素分泌明显增加","副交感神经兴奋，全身血管舒张，散热量增加"],"a":0,"e":"环境温度超过体表温度时，蒸发散热成为主要散热方式，交感神经兴奋使汗腺分泌增加以促进散热。此时皮肤血管舒张而非收缩，寒战为寒冷时产热反应。"},{"q":"细胞在安静时对钠离子的通透性","o":["为零","约为钾离子通透性的2倍","约为钾离子通透性的1/2","约为钾离子通透性的1/100～1/50","约为钾离子通透性的1/1000"],"a":3,"e":"安静时细胞膜对K+的通透性明显大于对Na+的通透性，两者通透性之比约为1/100～1/50，故静息电位接近EK。"},{"q":"消化道平滑肌的紧张性和自动节律性主要依赖于","o":["交感神经的支配","副交感神经的支配","壁内神经丛的作用","平滑肌本身的特性","食物消化产物的刺激作用"],"a":3,"e":"消化道平滑肌离体后仍能自动进行节律性收缩，并经常保持微弱持续收缩的紧张性，说明其紧张性和自律性源于平滑肌细胞本身的特性，而非神经支配。"},{"q":"某患者血沉增快，若将该患者的红细胞置于正常人血浆中，其红细胞沉降的速度将","o":["增快","下降","正常","无变化","先增快后恢复正常"],"a":2,"e":"血沉增快主要取决于血浆成分改变，纤维蛋白原、球蛋白增多可中和红细胞表面负电荷而促进叠连。将患者红细胞置于正常人血浆中，叠连条件不复存在，沉降率恢复正常。"},{"q":"肝素抗凝的主要机制是","o":["抑制凝血酶原的激活","抑制FⅩ的激活","促进纤维蛋白吸附凝血酶","增强抗凝血酶的活性","抑制血小板聚集"],"a":3,"e":"肝素主要通过增强抗凝血酶对凝血酶的灭活而发挥间接抗凝作用，缺乏抗凝血酶时其抗凝作用很弱。肝素本身不直接抑制凝血因子激活或血小板聚集。"},{"q":"限制性通气不足的原因是","o":["肺泡扩张受限","肺泡壁厚度增加","气道阻力增高","肺泡面积减少","肺泡通气与血流比例失调"],"a":0,"e":"限制性通气不足指肺和胸廓扩张受限所致的通气障碍，呼吸肌麻痹、肺和胸廓弹性变化及气胸均可引起肺扩张受限。肺泡壁厚度增加、气道阻力增高、通气血流比例失调分别属于换气障碍或阻塞性通气不足。"},{"q":"胃蛋白酶原转变为胃蛋白酶的激活物是","o":["Cl-","Na+","K+","HCl","内因子"],"a":3,"e":"胃蛋白酶原由主细胞分泌，进入胃腔后在HCl作用下脱去小分子肽段转变为有活性的胃蛋白酶。内因子由壁细胞分泌，作用是保护维生素B12。"},{"q":"根据球-管平衡现象，近端小管的重吸收率约为肾小球滤过率的","o":["1/5","1/3","1/2","2/3","4/5"],"a":3,"e":"近端小管对Na+和水的重吸收率总是占肾小球滤过率的65%～70%，即定比重吸收，约相当于2/3，此现象称为球-管平衡，其意义在于保持尿量和尿Na+的相对稳定。"},{"q":"下列哪种肺容量在严重哮喘病患者降低最为显著","o":["肺活量","肺容量","用力呼气量","深吸气量","补呼气量"],"a":2,"e":"严重哮喘属阻塞性通气障碍，气道狭窄使呼气阻力增大，用力呼气量（尤其FEV1）显著降低。肺活量测定不限制呼气时间，早期可仍正常，不能敏感反映气道通畅程度。"},{"q":"关于兴奋性突触传递的叙述，错误的是","o":["突触前轴突末梢去极化","Ca2+由膜外进入突触前膜内","突触小泡释放递质，并与突触后膜受体结合","突触后膜对Na+、K+ 、Ca2+，特别是对K+的通透性升高","突触后膜电位除极化达阈值时，引起突触后神经元发放冲动"],"a":3,"e":"兴奋性突触传递时突触后膜对Na+和K+通透性升高，以Na+内流为主，产生去极化的兴奋性突触后电位。对Ca2+通透性升高并以K+通透性为主是抑制性突触后电位的特点。"},{"q":"下列为快痛特点的是","o":["定位不明确","为“烧灼痛”","主要投射到扣带回","主要投射到皮层第一和第二感觉区","常伴有明显的不愉快情绪"],"a":3,"e":"快痛定位明确、发生和消退均快，主要经特异性投射系统到达大脑皮层第一和第二感觉区。定位不明确、呈烧灼痛、投射到扣带回并伴不愉快情绪均为慢痛特点。"},{"q":"分娩前没有乳汁分泌，是因为","o":["血中催乳素浓度过低","乳腺细胞上催乳素受体的数目不足","缺乏缩宫素的刺激","血中雌激素和孕激素水平很高","催乳素释放因子分泌不足"],"a":3,"e":"妊娠期血中雌激素和孕激素水平很高，可抑制PRL的泌乳作用，故乳腺虽具备泌乳能力却不泌乳。分娩后雌、孕激素水平骤降，PRL方能始动和维持泌乳。"},{"q":"人体单位时间内的基础代谢率","o":["与身高成正比","与体重成正比","与体表面积成正比","与身高和体重的乘积成正比","与上述各因素都无关"],"a":2,"e":"基础代谢率与体表面积成正比，而不与体重或身高成正比，故以单位时间单位体表面积的产热量表示。心输出量在安静时同样与体表面积成正比。"},{"q":"关于交感缩血管神经的描述，正确的是","o":["只有某些特殊部位的血管才受交感缩血管神经支配","兴奋时通常引起血管舒张","节后纤维释放肾上腺素","交感缩血管神经的紧张性变化时，对心和脑的血流量影响很大","在α受体为主的血管，交感缩血管神经兴奋时引起血管收缩"],"a":4,"e":"交感缩血管神经节后纤维释放去甲肾上腺素，与血管平滑肌α受体结合较强，引起血管收缩。体内几乎所有血管均受其支配，其紧张性变化对心脑血管影响较小。"},{"q":"血小板减少导致皮肤出现自发性出血斑点的主要原因是","o":["血小板不能聚集成团","血小板不能释放足够的血管活性物质","不能修复和保持血管内皮细胞完整性","血凝块回缩障碍","血小板黏附减少"],"a":2,"e":"血小板可黏附于受损内皮下组织并释放活性物质，维持血管壁完整性；血小板减少时毛细血管脆性增高，出现自发性出血斑点。"},{"q":"给骨骼肌连续刺激时，如果后1次刺激所引起的收缩过程出现在前1次刺激所引起的收缩过程的收缩期内，所产生收缩总和是","o":["单收缩","不完全强直收缩","完全强直收缩","等张收缩","等长收缩"],"a":2,"e":"后一次收缩叠加在前一次收缩的收缩期，产生的收缩总和为完全强直收缩；叠加在舒张期则为不完全强直收缩。"},{"q":"关于胰岛素分泌调节的叙述，错误的是","o":["血糖降低时胰岛素分泌增加","进食时肠道抑胃肽分泌，促进胰岛素分泌","胰高血糖素直接或间接的促进胰岛素分泌","迷走神经兴奋时分泌增加，交感神经兴奋时分泌减少","胰生长抑素在胰岛局部发挥，抑制胰岛素分泌"],"a":0,"e":"血糖水平是调节胰岛素分泌的最重要因素，血糖降低时胰岛素分泌减少而非增加。进食时抑胃肽等胃肠激素促进胰岛素分泌，迷走神经兴奋促进、交感神经抑制其分泌。"},{"q":"关于唾液的描述，下列哪项是正确的","o":["进食时唾液分泌的调节不依赖于体液调节","唾液不能排泄汞","只有食物刺激口腔感受器才能刺激唾液分泌","唾液中的消化酶可以消化脂类物质","迷走神经促进唾液的分泌，但是交感神经抑制唾液的分泌"],"a":0,"e":"唾液分泌主要依靠神经调节，包括条件反射和非条件反射，不依赖体液调节。唾液可排泄汞等物质，食物的性状、颜色、气味等也可引起分泌。"},{"q":"肾清除率最低的物质是","o":["菊粉","碘锐特","肌酐","尿素","葡萄糖"],"a":4,"e":"葡萄糖可经肾小球自由滤过，但被肾小管全部重吸收，其清除率几近于零，为最低。菊粉清除率等于肾小球滤过率，碘锐特反映肾血浆流量。"},{"q":"父母一方为A型，另一方为B型，其子女可能的血型为","o":["只有AB型","只有A型或B型","只可能是A型、B型、AB型","A型、B型、AB型、O型都有可能","只可能是AB型或O型"],"a":3,"e":"A型父母基因型可为AA或AO，B型可为BB或BO，双方均可能携带O基因，故子女可为A型、B型、AB型或O型。"},{"q":"脊髓闰绍细胞构成的抑制称为","o":["周围性抑制","侧支性抑制","除极化抑制","回返性抑制","交互性抑制"],"a":3,"e":"闰绍细胞构成的抑制是兴奋性神经元经轴突侧支兴奋抑制性中间神经元，再反过来抑制自身，属回返性抑制，意义在于及时终止神经元活动并使活动同步化。"},{"q":"心室射血的后负荷是指","o":["心室内压","主动脉血压","主动脉脉压","总外周阻力","中心静脉压"],"a":1,"e":"心室收缩时须克服大动脉血压才能射血，故大动脉血压（主动脉血压）是心室收缩的后负荷。其增高时等容收缩期延长、射血期缩短，搏出量减少。"},{"q":"在骨骼肌兴奋-收缩耦联中起关键作用的离子是","o":["Na＋","Ca2＋","Cl-","K＋","Mg2＋"],"a":1,"e":"Ca2+是骨骼肌兴奋-收缩耦联的关键耦联因子，耦联发生部位为三联体结构。动作电位沿横管传至肌质网，触发Ca2+释放，胞质Ca2+浓度升高引起肌丝滑行。"},{"q":"调节人体生理功能的生物信息传递系统包括","o":["神经系统和免疫系统","内分泌系统和免疫系统","神经系统和内分泌系统","中枢神经系统和外周神经系统","第一信号系统和第二信号系统"],"a":2,"e":"人体功能调节的生物信息传递系统为神经系统和内分泌系统，二者相辅相成共同维持内环境稳态。下丘脑是神经系统与内分泌系统活动相互联络的重要枢纽。"},{"q":"内环境的稳态是指","o":["细胞内液的各种理化性质保持不变","细胞外液的各种理化性质保持不变","细胞内液的各种理化性质在一定范围内变动又保持相对稳定","细胞外液的各种理化性质在一定范围内变动又保持相对稳定","细胞内液和细胞外液中各种成分基本保持相同"],"a":3,"e":"稳态指内环境即细胞外液的各种理化性质在一定范围内变动而达到的动态平衡，并非静止不变。稳态的维持是机体自我调节的结果，是正常生命活动的必要条件。"},{"q":"突触后抑制的产生是由于","o":["兴奋性递质破坏过多","兴奋性递质释放过少","抑制性中间神经元兴奋","抑制性中间神经元产生了抑制","兴奋性中间神经元活动抑制"],"a":2,"e":"突触后抑制由抑制性中间神经元兴奋、释放抑制性递质引起，使突触后膜氯通道开放、Cl-内流而产生IPSP。传入侧支抑制和回返性抑制均属此类。"},{"q":"可引起基础代谢率升高的是","o":["垂体性肥胖症","病理性饥饿","Addison病","肾病综合征","甲状腺功能亢进"],"a":4,"e":"甲状腺激素可提高机体代谢率，甲状腺功能亢进时TH分泌过多，基础代谢率升高，BMR是检测甲状腺功能的重要指标。长期饥饿所致营养不良则使BMR降低。"},{"q":"下列脑电波中，频率最快，波幅最小的是","o":["α波","β波","θ波","δ波","棘慢波"],"a":1,"e":"β波频率为14～30Hz、幅度5～20μV，是新皮层处于紧张活动状态的标志，为各基本脑电波中频率最快、波幅最小者。α波频率8～13Hz、幅度20～100μV。"},{"q":"在日常生活当中，下列哪种情况会促进唾液分泌","o":["睡眠","恶心","疲劳","失水","恐惧"],"a":1,"e":"食管、胃和十二指肠上部受刺激可引起唾液分泌增多，吞咽刺激性食物或恶心时唾液分泌增加，其意义在于稀释或中和刺激性物质。"},{"q":"患者CO中毒后，血液运输氧的能力严重降低，这是因为","o":["CO降低Hb对O2的亲和力","CO使Hb分子结构向紧密型转变","CO使Hb分子中的Fe2＋氧化成了Fe3＋","CO与Hb亲和力远远高于O2，并妨碍O2与Hb的解离","CO使氧解离曲线右移"],"a":3,"e":"CO与Hb的亲和力是O2的250倍，可占据O2结合位点形成HbCO，且使氧解离曲线左移妨碍O2解离，故既妨碍结合又妨碍解离。CO中毒时血液PO2正常，不出现发绀。"},{"q":"副交感神经兴奋可引起","o":["瞳孔扩大","糖原分解","胃肠运动增强","骨骼肌血管舒张","竖毛肌收缩"],"a":2,"e":"副交感神经兴奋可增强胃肠运动和分泌，教材指出刺激下丘脑内侧部引起胃肠蠕动增强。瞳孔扩大、糖原分解、竖毛肌收缩均为交感神经兴奋的表现。"},{"q":"与心输出量和心指数有关的正确说法是","o":["心输出量=心率×搏出量","心输出量是每分钟由两侧心室输出的血液量","心输出量是一次心搏由两侧心室射出的血液量","心指数是单位体重计算的心输出量","20岁左右青年的静息心指数最高"],"a":0,"e":"心输出量等于心率与搏出量的乘积，是每分钟由一侧心室射出的血量。心指数是以单位体表面积计算的心输出量，而非单位体重。"},{"q":"下列关于突触可塑性的描述，错误的是","o":["功能与形态均可改变","可发生在突触前或突触后","普遍存在于中枢神经系统","突触传递效率改变较持久","是神经系统发育成熟后的表现"],"a":4,"e":"突触可塑性普遍存在于中枢神经系统，与神经系统发育及学习记忆等高级功能密切相关，并非成熟后才出现的表现。其包括突触效能、形态和数量的持久改变。"},{"q":"小血管损伤后止血栓正确定位于损伤部位，是由于血小板的哪种生理特性","o":["吸附","黏附","聚集","收缩","释放"],"a":1,"e":"血小板黏附是指血小板与非血小板表面（如内皮下胶原）的黏着，可识别损伤部位，使止血栓正确定位。聚集是血小板之间的相互黏着。"},{"q":"下列哪项是胰高血糖素的作用","o":["抑制磷脂酶C","抑制腺苷酸环化酶","抑制胰岛素的分泌","促进肝脏的糖异生","促进肌肉的糖原分解"],"a":3,"e":"胰高血糖素的主要靶器官是肝脏，可促进肝糖原分解、减少肝糖原合成并增强糖异生，从而提高血糖。它不促进肌肉糖原分解。"},{"q":"椭圆囊和球囊囊斑的适宜刺激是","o":["旋转加速运动","旋转匀速运动","直线加速运动","直线匀速运动","直立静止状态"],"a":2,"e":"椭圆囊和球囊囊斑的适宜刺激是直线加速度运动，旋转加速运动则由半规管壶腹嵴感受。囊斑毛细胞纤毛排列方向不同，可感受不同方向的重力及变速刺激。"},{"q":"因在幼年期缺乏而导致患侏儒症的激素是","o":["T3","ACTH","GH","PRL","OT"],"a":2,"e":"幼年期生长激素（GH）分泌不足可致生长停滞、身材矮小，即侏儒症。T3缺乏主要影响脑发育，ACTH、PRL、OT与身材生长无直接关系。"},{"q":"全血的黏滞性主要取决于","o":["血浆蛋白含量","血细胞比容","白细胞数量","红细胞的叠连","NaCl的浓度"],"a":1,"e":"全血的黏度主要决定于血细胞比容的高低，血细胞比容是决定血液黏滞度最重要的因素。血浆黏度才主要取决于血浆蛋白含量。"},{"q":"突触蛋白（synapsin）在轴浆高钙离子条件下被磷酸化，发生变构，其主要作用是","o":["解除突触囊泡锚定在细胞骨架丝上","帮助突触囊泡着位在活化区","促进v-SNARE与t-SNARE结合","消除对融合的钳制作用","开大融合孔以利于递质出胞"],"a":0,"e":"正确答案是解除突触囊泡锚定在细胞骨架丝上。静息时突触蛋白将囊泡锚定于细胞骨架丝，轴浆Ca2+升高后突触蛋白被Ca2+-CaM-CaMKⅡ磷酸化，囊泡即从细胞骨架丝上解离而动员。着位由Rab3/Rab27及SNARE复合物介导，非突触蛋白作用。"},{"q":"促代谢型受体是指","o":["电压门控通道","离子通道型受体","G蛋白耦联受体","化学门控通道","N2型ACh受体阳离子通道"],"a":2,"e":"促代谢型受体即G蛋白耦联受体，配体激活后经G蛋白引发级联反应完成跨膜信号转导。电压门控通道、化学门控通道及N2型ACh受体均属离子通道型受体，介导促离子型信号转导。"},{"q":"排便反射的初级中枢位于","o":["脊髓腰骶段","脊髓胸段","延髓","脑桥","大脑皮质"],"a":0,"e":"排便反射的初级中枢位于脊髓腰骶段，冲动经盆神经和腹下神经传入，并受大脑皮层控制。"},{"q":"下列关于简化眼的描述，错误的是","o":["一种假想的模型而非真实眼","光线仅在入单球界面时折射一次","折射界面的曲率半径为5mm","与人眼充分调节时的折光系统等效","可用于计算视网膜像的大小"],"a":3,"e":"简化眼由一个前后径20mm的单球面折光体构成，光线仅在入单球界面时折射一次，曲率半径5mm，可用于计算视网膜像大小。简化眼与正常眼不作调节时的折光系统等效，而非与充分调节时等效。"},{"q":"下列关于肠神经系统的叙述，错误的是","o":["是指消化道壁内的神经丛","能独立行使其功能","不受外来神经的调节","含有大量的神经纤维和神经元","参与消化道运动和消化液分泌的调节"],"a":2,"e":"肠神经系统指消化道壁内的黏膜下神经丛和肌间神经丛，含大量神经元和神经纤维，能独立调节胃肠运动、分泌、血流量及水电解质转运。在整体情况下外来神经对内在神经丛具有调节作用。"},{"q":"铁的摄入量不足将导致","o":["再生障碍性贫血","缺铁性贫血","溶血性贫血","巨幼细胞贫血","珠蛋白生成障碍性贫血"],"a":1,"e":"铁是合成血红蛋白的必需原料，摄入不足或吸收障碍时血红蛋白合成减少，引起缺铁性贫血。叶酸和维生素B12缺乏影响DNA合成，导致巨幼细胞贫血。"},{"q":"动物实验中，静脉注射乙酰胆碱后，引起动脉血压下降的主要原因是","o":["心肌细胞传导减慢","心肌收缩力减弱","心率减慢，心输出量下降","静脉回流减慢","后负荷增大"],"a":2,"e":"乙酰胆碱主要激动心脏M受体，使心率减慢、心肌收缩力减弱、传导减慢，心输出量减少而血压下降，其中心率减慢致心输出量下降为主要原因。静脉注射乙酰胆碱还舒张血管，但血压下降主因是心脏抑制。"},{"q":"治疗严重哮喘发作喘息，医生应使用","o":["α1-肾上腺素能受体拮抗剂","β1-肾上腺素能受体拮抗剂","β2-肾上腺素能受体激动剂","M-胆碱能受体激动剂","N-胆碱能受体激动剂"],"a":2,"e":"支气管平滑肌以β2受体为主，激动后舒张，故β2受体激动剂可缓解哮喘发作时的支气管痉挛。α1拮抗剂和β1拮抗剂不能舒张支气管，M受体激动剂反而使支气管收缩。"},{"q":"肾小管分泌氢离子增多时可减少","o":["钠的重吸收","钾的分泌","氨的分泌","氯的排泄","尿素的排泄"],"a":1,"e":"肾小管分泌H+增多时，小管液中H+与K+竞争同一分泌机制，H+分泌增加则K+分泌减少。H+分泌增多还可促进NH3分泌以缓冲H+，故氨的分泌不减少。"},{"q":"能直接刺激肾上腺皮质球状带细胞分泌醛固酮的是","o":["血管紧张素Ⅰ","血管紧张素原","血管紧张素Ⅱ","促肾上腺皮质激素","肾素"],"a":2,"e":"血管紧张素Ⅱ是直接刺激肾上腺皮质球状带合成和分泌醛固酮的激素。血管紧张素Ⅰ需经血管紧张素转换酶作用生成血管紧张素Ⅱ后才具备此作用，肾素是催化血管紧张素原生成血管紧张素Ⅰ的酶。"},{"q":"血浆的pH值主要取决于下列哪个缓冲对","o":["碳酸氢钾/碳酸","磷酸氢二钾/磷酸二氢钾","碳酸氢钠/碳酸","磷酸氢二钠/磷酸二氢钠","蛋白质-钠盐/蛋白质"],"a":2,"e":"血浆中最重要的缓冲对是NaHCO3/H2CO3，其比值决定血浆pH。二者比值维持在20:1时血浆pH约为7.4，该缓冲对含量最多、缓冲能力最强。"},{"q":"下列关于小脑对肌紧张调节的描述，正确的是","o":["前叶蚓部具有易化肌紧张的作用","前叶两侧部具有抑制肌紧张的作用","易化区和抑制区在前叶均呈正立式空间分布","进化过程中，前叶的易化作用逐渐占主要地位","半球中间部也有抑制肌紧张的作用"],"a":3,"e":"小脑对肌紧张的调节中，前叶蚓部抑制肌紧张，前叶两侧部易化肌紧张；进化过程中小脑抑制肌紧张的作用逐渐减退，易化作用逐渐增强。前叶两侧部的空间安排为倒置。"},{"q":"有关自主性体温调节，下列哪项是错误的","o":["主要作用是维持体温的稳定","有下丘脑调节中枢的参与","是行为性体温调节的基础","不属于体温自身调节系统","使机体深部温度维持在一个稳定的水平"],"a":3,"e":"自主性体温调节是在体温调节中枢控制下通过增减皮肤血流量、出汗、战栗等生理反应维持体温相对稳定，属于体温的自身调节系统，是行为性体温调节的基础。"},{"q":"下列哪项与血-睾屏障的功能无关","o":["对生精细胞具有保护作用","营造精子生成所需的微环境","防止抗精子自身免疫反应","参与雄激素合成和分泌","对生精细胞的支持作用"],"a":3,"e":"血-睾屏障由支持细胞间紧密连接构成，可营造生精微环境、保护生精细胞并防止抗精子自身免疫反应。雄激素由睾丸间质细胞合成和分泌，与血-睾屏障功能无关。"},{"q":"在一般的生理情况下，每分解一分子ATP，钠泵运转可使","o":["2个钠离子移出膜外","2个钾离子移出膜内","2个钠离子移出膜外，同时有2个钾离子移入膜内","3个钠离子移出膜外，同时有2个钾离子移入膜内","2个钠离子移出膜外，同时有3个钾离子移入膜内"],"a":3,"e":"钠泵每分解一分子ATP，逆浓度差将3个Na+移出胞外、2个K+移入胞内，产生一个净正电荷外移而具有生电效应。"},{"q":"由于毛细血管后阻力增大而导致组织液生成增多的是","o":["右心衰引起的全身水肿","肾小球肾病性全身水肿","慢性肝病性全身水肿","丝虫病象皮腿局部水肿","局部炎症性水肿"],"a":0,"e":"微静脉收缩使毛细血管后阻力升高，毛细血管血压升高，组织液生成增多。右心衰竭时体循环静脉压升高，毛细血管有效流体静压增高，引起全身性水肿。"},{"q":"下列功能中，大脑优势半球占优势的是","o":["空间辨认","深度知觉","语言活动","触觉认识","音乐欣赏"],"a":2,"e":"习惯使用右手的成年人语言活动中枢主要在左侧大脑皮层，左侧半球为语言优势半球。空间辨认、深度知觉、音乐欣赏等以右侧半球占优势。"},{"q":"生理状态下，能促进肝外组织蛋白质分解的激素是","o":["糖皮质激素","生长激素","胰岛素","甲状腺激素","雄激素"],"a":0,"e":"糖皮质激素可促进肝外组织（肌肉等）蛋白质分解，抑制蛋白质合成。生长激素虽促进蛋白质合成，胰岛素也促进合成，甲状腺激素以促进代谢为主。"},{"q":"下列关于外周化学感受器的描述，正确的是","o":["O2含量的降低是外周化学感受器的敏感刺激","外周化学感受器对动脉血中H+浓度的增加不敏感","PCO2的升高是外周化学感受器的敏感刺激","外周化学感受器的适宜刺激是动脉血中的血红蛋白含量","颈动脉体中起感受器作用的部分是Ⅱ型细胞"],"a":2,"e":"CO2较易进入外周化学感受器细胞使细胞内H+升高，故PCO2升高是外周化学感受器的敏感刺激。低O2也是有效刺激，但并非“敏感刺激”的表述；颈动脉体中起感受作用的是Ⅰ型细胞。"},{"q":"骨髓受X射线损害将导致","o":["再生障碍性贫血","缺铁性贫血","溶血性贫血","巨幼红细胞性贫血","地中海贫血"],"a":0,"e":"X射线等物理因素可损伤造血干细胞及造血微环境，引起再生障碍性贫血，表现为全血细胞减少。缺铁性贫血、巨幼红细胞性贫血分别由铁和叶酸/维生素B12缺乏引起。"},{"q":"对肺泡气体分压变化起缓冲作用的是","o":["补吸气量","补呼气量","深吸气量","功能余气量","余气量"],"a":3,"e":"功能余气量是平静呼气末存留于肺内的气体量，其稀释作用可缓冲呼吸过程中肺泡气PO2和PCO2的变化幅度。余气量仅为功能余气量的一部分，缓冲作用由功能余气量完成。"},{"q":"下列有关γ运动神经元的描述，错误的是","o":["胞体较α运动神经元为小","其轴突经前根支配梭内肌","末梢释放乙酰胆碱","兴奋性较低","主要功能是调节肌梭对牵张刺激的敏感性"],"a":3,"e":"γ运动神经元兴奋性较α运动神经元高，常以较高频率持续放电，故“兴奋性较低”错误。其胞体较小，轴突经前根支配梭内肌，末梢释放乙酰胆碱，功能是调节肌梭对牵张刺激的敏感性。"},{"q":"腋窝是临床上最常用的测定体温的部位，下面哪项要求对用腋窝温度代表体温的影响不大","o":["夹紧","保持腋窝干燥","平卧","测定10分钟","保持安静"],"a":2,"e":"腋窝温度测量要求上臂夹紧、腋窝干燥、保持安静并测定足够时间（约10分钟），体位平卧与否对腋温读数影响不大。腋温低于直肠温度，需正确操作方能代表体温。"},{"q":"关于脑干网状结构上行激动系统正确的是","o":["通过丘脑特异投射系统发挥作用","被兴奋后脑电波呈现同步化慢波","可维持大脑皮层的兴奋状态","投射至特定的脑区域","是一个多突触接替的系统，不易受药物的影响"],"a":2,"e":"脑干网状结构上行激动系统经丘脑非特异投射系统弥散投射至大脑皮层，维持和改变大脑皮层兴奋状态。该系统为多突触接替，易受药物影响，兴奋后脑电呈同步化快波。"},{"q":"红细胞沉降率的快慢主要取决于红细胞的","o":["体积","表面积","数量","比重","叠连的加速或抑制"],"a":4,"e":"红细胞沉降率快慢取决于红细胞叠连的加速或抑制，叠连后总表面积与总体积之比减小、摩擦力减小而沉降加快。决定叠连的因素在于血浆成分变化，而非红细胞本身。"},{"q":"引起氧解离曲线右移的因素是","o":["PCO2升高","2,3-DPG降低","pH升高","温度降低","吸入气CO浓度升高"],"a":0,"e":"PCO2升高使Hb对O2亲和力降低、P50增大，氧解离曲线右移。pH升高、温度降低、2,3-DPG降低均使曲线左移；CO中毒影响Hb携O2量而不改变曲线位置。"},{"q":"单纯扩散、易化扩散和主动转运的共同特点是","o":["要消耗能量","顺浓度梯度","需要膜蛋白帮助","转运的物质都是小分子","有饱和性"],"a":3,"e":"单纯扩散、易化扩散和主动转运的对象均为小分子或离子，大分子物质经膜泡运输转运。主动转运逆浓度梯度并耗能，单纯扩散不需膜蛋白，易化扩散无饱和性之说并不成立。"},{"q":"下列哪种情况下ADH的分泌将会减少","o":["大出血","大量出汗","严重呕吐或腹泻","大量饮清水","血糖浓度升高"],"a":3,"e":"大量饮清水后血浆晶体渗透压降低，抗利尿激素分泌减少，集合管对水重吸收减少，尿量增加，即水利尿。大出血、大量出汗、严重呕吐腹泻均使血浆晶体渗透压升高而促进ADH释放。"},{"q":"与ACTH分泌调节无关的是","o":["下丘脑促肾上腺皮质激素释放激素的作用","糖皮质激素的反馈调节作用","醛固酮的反馈调节作用","下丘脑-腺垂体-肾上腺皮质轴的调节作用","与光照无关的日周期变化"],"a":2,"e":"ACTH分泌受下丘脑CRH促进、糖皮质激素负反馈抑制，并呈与光照无关的日周期波动。醛固酮主要受血K+和肾素-血管紧张素系统调节，对ACTH分泌无反馈作用。"},{"q":"调节胰岛素分泌最重要的刺激因素是","o":["血中氨基酸水平","血糖水平","血中脂肪酸水平","乙酰胆碱","胰高血糖素"],"a":1,"e":"血糖水平是调节胰岛素分泌的最重要因素，血糖升高直接刺激胰岛β细胞分泌胰岛素。氨基酸、脂肪酸、乙酰胆碱和胰高血糖素也有作用，但均非最重要因素。"},{"q":"关于肾脏逆流倍增机制对尿液浓缩能力的叙述，正确的是","o":["与髓袢的长度无关","与肾髓质部血流速度无关","与髓袢肾小管的流速无关","取决于近端小管对水的通透性","取决于血中抗利尿激素的浓度"],"a":4,"e":"集合管对水的通透性取决于血中抗利尿激素浓度，ADH增加则水重吸收增多、尿液浓缩。肾髓质渗透梯度还与髓袢长度、髓质血流及小管流速有关，逆流倍增本身不取决于近端小管对水的通透性。"},{"q":"消化道平滑肌细胞动作电位产生的离子基础是","o":["K+内流","Na+内流","Ca2+内流","Ca2+与K+内流","Cl-的外流"],"a":2,"e":"消化道平滑肌细胞动作电位去极化主要依赖Ca2+内流，故锋电位上升慢、幅度低且大小不等。复极化由K+外流所致，慢波去极化与钙激活氯通道引起Cl-外流有关。"},{"q":"下列因素可导致脑血管舒张的是","o":["平均动脉压下降","H+浓度下降","CO2分压降低","腺苷生成减少","K+通道激活"],"a":4,"e":"低氧的舒血管效应与NO、腺苷释放和钾通道激活有关，K+通道激活使脑血管舒张。CO2分压升高、H+浓度升高引起脑血管舒张，而平均动脉压下降时脑血流自身调节使血管舒张并非由所给机制直接说明。"},{"q":"正常人吸入下列哪种混合气体时，肺通气量明显增加","o":["21%O2和79%N2","19%O2和81%N2","20%CO2和80%O2","3%CO2和97%O2","0、5%CO2和99、5%O2"],"a":3,"e":"3%CO2和97%O2使动脉血PCO2升高，兴奋呼吸中枢，肺通气量明显增加。吸入气CO2增至4%时肺通气量可加倍；20%CO2则抑制中枢，出现CO2麻醉。"},{"q":"氨基酸和葡萄糖在小肠的吸收机制是","o":["渗透和滤过","原发性主动转运","入胞作用","继发性主动转运","易化扩散"],"a":3,"e":"小肠黏膜刷状缘吸收氨基酸和葡萄糖均依赖Na+顺电化学梯度提供的能量，属继发性主动转运。哇巴因抑制钠泵后该转运逐渐减弱，说明其能量间接来自钠泵。"},{"q":"人体在寒冷中的反应有","o":["交感神经紧张性增强","皮肤血流量增加","代谢降低","甲状腺激素分泌减少","交感神经紧张性减弱"],"a":0,"e":"寒冷环境中交感神经紧张性增强，皮肤血管收缩、血流量减少，皮肤温度降低以减少散热。同时代谢增强、甲状腺激素分泌增多产热。"},{"q":"以下运动障碍表现中最符合“不全麻痹”概念的是","o":["肌肉张力消失","肌肉强直","巴宾斯基征阳性","腱反射亢进","肌肉力量下降"],"a":4,"e":"轻瘫指单纯运动传出通路损伤所致运动能力减弱，表现为肌肉力量下降，常伴肌张力降低，无腱反射亢进和巴宾斯基征阳性。"},{"q":"蛙的有髓神经纤维动作电位的锋电位持续时间约2毫秒，从理论上讲，1秒内所产生的动作电位次数不可能超过多少次","o":["100","200","300","400","500"],"a":4,"e":"绝对不应期约2ms，此期内不能产生新的动作电位，故动作电位最大频率不超过每秒500次。"},{"q":"使糜蛋白酶原活化的物质是","o":["糜蛋白酶本身","胰蛋白酶","肠激酶","盐酸","胰淀粉酶"],"a":1,"e":"糜蛋白酶原主要在胰蛋白酶作用下转化为有活性的糜蛋白酶。肠激酶特异性激活胰蛋白酶原，对糜蛋白酶原无直接激活作用。"},{"q":"抗利尿激素主要影响的水通道蛋白是","o":["水通道蛋白-1","水通道蛋白-2","水通道蛋白-3","水通道蛋白-4","都有影响"],"a":1,"e":"抗利尿激素与主细胞基底侧膜V2受体结合，促使含AQP2的囊泡镶嵌到顶端膜，增加顶端膜对水的通透性，故主要影响水通道蛋白-2。"},{"q":"巨大爆炸声响时，迅速张口有利于保护","o":["前庭膜","鼓膜","基底膜","蜗窗膜","耳蜗"],"a":1,"e":"咽鼓管在吞咽、张口时开放，使鼓室内压与外界大气压相等，维持鼓膜两侧压力平衡，避免巨大爆炸声压致鼓膜损伤。中耳肌反射需40～160毫秒，对突发爆炸声保护作用不大。"},{"q":"下列食物的特殊动力效应最大的是","o":["糖","蛋白质","脂肪","混合食物","糖和脂肪"],"a":1,"e":"蛋白质的特殊动力效应约为30%，为三种主要营养物质中最大，糖和脂肪均低于此。"},{"q":"胃期胃液分泌的特点是","o":["胃液的酸度含量较高而酶含量较低","胃液的酸度低而酶含量也低","胃液的酸度含量较高而酶含量更高","胃液的酶含量较高而酸度更高","胃液的酶含量较高而酸度较低"],"a":0,"e":"胃期胃液分泌量约占总分泌量60%，酸度和胃蛋白酶含量均很高，但酶含量相对低于头期。"},{"q":"切除双侧肾上腺后动物死亡的主要原因是缺乏","o":["肾上腺素","肾素","去甲肾上腺素","肾上腺皮质激素","血管紧张素"],"a":3,"e":"肾上腺皮质激素是维持生命所必需，缺乏糖皮质激素致代谢紊乱、耐受力下降，缺乏盐皮质激素致水盐代谢紊乱、循环血量不足而死亡。"},{"q":"肺心病病人的血液黏稠、红细胞数量增多，是由于","o":["血氧饱和度降低","H＋增多","纤溶酶减少","纤维蛋白原增多","红细胞生成酶增多"],"a":0,"e":"肺心病致肺通气与换气障碍，动脉血氧分压降低使血氧饱和度降低，机体代偿性红细胞生成增多、血液黏稠。"},{"q":"下列有关交感神经系统的描述，不正确的是","o":["交感神经分布广泛","交感节前纤维往往和多个节内神经元发生突触联系","交感神经系统可促使机体适应环境的急变","交感神经系统可使肝糖原分解加速","交感神经系统的意义主要在于保护机体、休整恢复"],"a":4,"e":"保护机体、休整恢复、促进消化、积蓄能量是副交感神经系统的意义，交感神经系统在于动员机体适应环境的急变。"},{"q":"衡量肺通气潜能的指标是","o":["肺通气量","肺泡通气量","用力肺活量","用力呼气量","通气储量百分比"],"a":4,"e":"通气储量百分比由平静每分通气量与最大通气量比较得出，反映通气功能的储备能力，正常值≥93%。"},{"q":"甲状腺激素能降低以下哪项","o":["糖酵解","糖原异生","血浆胆固醇的水平","血浆氨基酸水平","血浆游离脂肪酸浓度"],"a":2,"e":"甲状腺激素既促进胆固醇合成，又增加LDL受体使胆固醇从血中清除，净效应为降低血清胆固醇水平。"},{"q":"异相睡眠区别于慢波睡眠的特点是","o":["感觉功能和肌张力更加增强","可出现阵发性副交感兴奋表现","多梦","生长素分泌增多","代谢率降低"],"a":2,"e":"异相睡眠脑电呈去同步化快波，常伴梦境，而慢波睡眠时GH分泌陡增、代谢率降低。"},{"q":"氧解离曲线是表示下列哪种关系的曲线","o":["血红蛋白含量与血氧含量","血红蛋白氧饱和度与血氧分压","血红蛋白氧饱和度与血红蛋白氧含量","血红蛋白浓度与血红蛋白氧容量","血红蛋白浓度与血红蛋白氧含量"],"a":1,"e":"氧解离曲线表示血液PO2与Hb氧饱和度之间的关系，呈S形，反映不同PO2下O2与Hb的结合与解离情况。"},{"q":"请问下列哪种情况可引起右室容量负荷增大","o":["肺动脉高压","肺动脉栓塞","室间隔缺损","心肌炎","肺动脉瓣狭窄"],"a":2,"e":"室间隔缺损时左心室血液经缺损分流至右心室，使右心室舒张期充盈量增加，即右室容量负荷增大。肺动脉高压、肺动脉栓塞和肺动脉瓣狭窄均增加右室压力负荷。"},{"q":"可直接抑制胰岛素分泌的激素是","o":["生长激素","生长抑素","抑胃肽","皮质醇","胰高血糖素"],"a":1,"e":"胰岛δ细胞分泌的生长抑素通过旁分泌方式抑制β细胞分泌胰岛素。胰高血糖素则通过旁分泌刺激β细胞分泌胰岛素。"},{"q":"平静呼吸时，在下列时相中肺内压低于大气压的是","o":["吸气初","吸气末","呼气初","呼气末","停止呼吸时"],"a":0,"e":"吸气初肺容积增大，肺内压降至低于大气压，外界气体流入肺内；吸气末肺内压与大气压相等，气流暂停。"},{"q":"下列选项中，属于人类脊髓小脑损伤所特有的症状是","o":["偏瘫","静止性震颤","意向性震颤","肌张力增强","身体平衡失调"],"a":2,"e":"脊髓小脑损伤后，患者不能完成精巧动作，肌肉在动作进行过程中抖动而把握不住方向，尤其精细动作终末出现震颤，称为意向性震颤。静止性震颤见于帕金森病。"},{"q":"传入侧支性抑制和回返性抑制均属于","o":["突触前抑制","突触后抑制","外周性抑制","负反馈抑制","交互性抑制"],"a":1,"e":"传入侧支抑制和回返性抑制均由抑制性中间神经元释放抑制性递质，使突触后膜产生IPSP，故均属突触后抑制。"},{"q":"实验切断双侧颈迷走神经后，兔的呼吸","o":["频率加快，幅度减小","频率加快，幅度增大","频率和幅度均不变","频率减慢，幅度减小","频率减慢，幅度增大"],"a":4,"e":"切断双侧颈迷走神经后，肺扩张反射的传入中断，吸气向呼气的转换减慢，吸气延长加深，呼吸变得深而慢，即频率减慢、幅度增大。"},{"q":"CO2的扩散系数约是O2的20倍，主要是由于","o":["CO2的分子量大","CO2的分子量小","CO2的溶解度大","CO2的溶解度小","呼吸膜两侧分压差大"],"a":2,"e":"CO2在血浆中的溶解度约为O2的24倍，故其扩散系数约为O2的20倍，溶解度大是主要原因。"},{"q":"心肌缺氧引起冠脉舒张，在该反应中起主要作用的是","o":["前列腺素","乳酸","氢离子","组胺","腺苷"],"a":4,"e":"腺苷是心肌缺氧时冠脉舒张的主要介质。冠脉周围间质细胞中的5′-核苷酸酶将AMP分解产生腺苷，腺苷具有强烈舒张小动脉作用，是心、脑血流自身调节的主要介质。"},{"q":"人体内O2和CO2进出细胞膜是通过下列哪种方式","o":["单纯扩散","易化扩散","原发性主动转运","继发性主动转运","出胞或入胞"],"a":0,"e":"O2和CO2脂溶性强，以单纯扩散方式跨越呼吸膜和组织毛细血管壁，属被动转运、不耗能。肺换气和组织换气即通过单纯扩散完成。"},{"q":"下列关于糖在小肠被吸收的叙述，正确的是","o":["单糖是小肠吸收的唯一形式","单糖的吸收都与钠离子同向转运","果糖的吸收速度比葡萄糖快","果糖的吸收速度比半乳糖慢","毒毛花苷可抑制果糖的吸收"],"a":3,"e":"单糖吸收速率以半乳糖和葡萄糖最快，果糖次之，故果糖比半乳糖慢。葡萄糖和半乳糖经SGLT-1继发性主动转运，果糖不依赖Na+同向转运。"},{"q":"血细胞比容主要指的是","o":["红细胞与血浆容积之比","红细胞与白细胞容积之比","血细胞在血液中所占的重量百分比","红细胞的容积","血细胞在血液中所占的容积百分比"],"a":4,"e":"血细胞比容指血细胞在血液中所占的容积百分比，正常男性40%～50%、女性37%～48%。因白细胞和血小板容积占比极小，它可反映红细胞的相对浓度。"},{"q":"婴幼儿时期甲状腺分泌不足可产生","o":["侏儒症","肢端肥大症","向心性肥胖","呆小症","糖尿病"],"a":3,"e":"甲状腺激素是胎儿和婴幼儿脑与骨骼发育所必需，婴幼儿期分泌不足导致呆小症，表现为体格发育落后和智力低下。"},{"q":"下列对血管升压素的叙述，正确的是","o":["又叫抗利尿激素","在下丘脑合成，腺垂体释放","收缩血管作用较强，是调节血压的主要体液因子","循环血量增多时，其分泌量增多","机体失血时，其分泌量减少"],"a":0,"e":"血管升压素即抗利尿激素，为九肽激素，由下丘脑合成、神经垂体释放。它主要调节血浆晶体渗透压和循环血量，循环血量增多时分泌减少。"},{"q":"有关脂肪的消化和吸收的叙述，正确的是","o":["胆盐能使脂肪水解","胆汁中含有脂肪酶，因而能分解脂肪","小肠内的脂肪小滴就是乳糜微粒","脂肪形成乳糜微粒转运至乳糜管","部分胆盐在十二指肠内吸收"],"a":3,"e":"长链脂肪酸和一酰甘油在肠上皮细胞内重新合成甘油三酯，与载脂蛋白组装成乳糜微粒，经出胞进入淋巴循环即乳糜管。胆盐只起乳化作用，不含脂肪酶。"},{"q":"静脉注射肝素所引起的体内抗凝作用大于其体外抗凝作用，这主要是因为肝素","o":["体外迅速灭活","在体内增强抗凝血酶的活性","在体内抑制凝血因子的产生","在体内促进抗凝血酶的产生","在体外与抗凝血酶的亲和性低"],"a":1,"e":"肝素本身抗凝作用弱，主要通过与抗凝血酶结合使其灭活凝血酶及FⅩa等的作用增强约2000倍而间接抗凝；体内尚可促进内皮TFPI释放，故体内作用强于体外。"},{"q":"下列关于胃排空的描述，正确的是","o":["扩张胃可抑制胃排空","胃内压不是胃排空的动力","胃排空的调节无激素参与","胃排空速度与胃内容物的体积呈直线关系","胃排空的速度与胃内容物的种类无关"],"a":3,"e":"胃排空速度与胃内容物的体积呈直线关系。教材指出排空速度取决于食物的物理性状和化学组成，胃内因素促进排空，十二指肠内因素抑制排空。扩张胃通过迷走反射增强胃运动而促进排空。"},{"q":"下列各项中，能使通气/血流比值升高的是","o":["肺水肿","肺气肿","哮喘发作","肺纤维化","肺毛细血管阻塞"],"a":4,"e":"肺毛细血管阻塞使肺血流量减少，通气/血流比值增大。肺气肿时肺泡壁破坏、毛细血管床减少，比值也可增大，但教材以肺毛细血管关闭和阻塞为扩散面积减小的典型原因。"},{"q":"对雄激素分泌减少导致生育力降低的男性患者，临床上治疗主要采用的激素是","o":["雄激素","糖皮质激素","FSH","hCG","GnRH"],"a":3,"e":"hCG结构与作用均与LH相似，可刺激睾丸间质细胞分泌睾酮，适用于有生育要求的雄激素减少患者。直接补充雄激素会负反馈抑制下丘脑和腺垂体，加重生精障碍。"},{"q":"下列哪种情况不能使血流阻力增大","o":["血流黏度增加","红细胞比容增加","血液温度升高","血管收缩","由层流变成湍流"],"a":2,"e":"血液温度升高使血液黏度降低，血流阻力减小。血流阻力与血液黏度成正比，红细胞比容增加、血管收缩及湍流形成均使阻力增大。"},{"q":"主动吸收胆盐和维生素B12的部位是","o":["十二指肠","回肠末端","空肠","结肠上段","结肠下段"],"a":1,"e":"回肠具有吸收胆盐和维生素B12的独特功能，其吸收部位在回肠末端。空肠切除后剩余回肠可部分代偿，而回肠切除后空肠难以弥补其功能。"},{"q":"下列关于小脑功能的描述，正确的是","o":["前庭小脑主要调节肌紧张","脊髓小脑主要与维持身体平衡有关","皮层小脑主要执行精巧运动","脊髓小脑主要协调随意运动","皮层小脑主要完成本体感受传入冲动信息的处理"],"a":3,"e":"脊髓小脑调节进行中的运动，协助大脑皮层对随意运动进行适时控制，使运动协调准确。前庭小脑维持身体平衡，皮层小脑参与精巧运动的策划和程序编制。"},{"q":"血浆胶体渗透压降低时可引起","o":["组织液减少","组织液增多","尿少","红细胞萎缩","红细胞膨胀和破裂"],"a":1,"e":"血浆胶体渗透压是限制组织液生成的主要力量，其降低使有效滤过压增大，组织液生成增多。毛细血管血压升高或毛细血管通透性增高同样导致组织液增多。"},{"q":"肾脏血流中的钾离子在肾单位和集合管中","o":["仅滤过","仅滤过和重吸收","仅滤过和分泌","滤过、重吸收和分泌","滤过、重吸收和代谢"],"a":3,"e":"钾离子可自由经肾小球滤过，其中约65%～70%在近端小管被重吸收，且肾小管和集合管可分泌钾，故钾经历滤过、重吸收和分泌三个环节。"},{"q":"腺垂体分泌的激素不包括","o":["生长素","缩宫素","卵泡刺激素","促甲状腺激素","黄体生成素"],"a":1,"e":"缩宫素由下丘脑视上核和室旁核神经元合成，经下丘脑-垂体束运送至神经垂体储存和释放，不属于腺垂体分泌的激素。生长素、卵泡刺激素、促甲状腺激素和黄体生成素均由腺垂体分泌。"},{"q":"尿素通透性最高的部位是","o":["髓袢降支细段","集合管内髓部","远曲小管","近端小管","髓袢升支粗段"],"a":1,"e":"内髓部集合管末端依赖抗利尿激素调控的尿素通道蛋白UT-A1和UT-A3，对尿素高度通透，是尿素通透性最高的部位。髓袢升支细段至外髓部集合管对尿素不通透。"},{"q":"关于输血的原则，错误的是","o":["必须保证ABO血型相合","输同型血经交叉配血试验主、次侧均不凝集为首选","紧急情况下O型血可少量缓慢接受其他型血液","紧急情况下A型血可少量缓慢输入给AB型血液","反复输血的病人必须保证Rh血型相合"],"a":2,"e":"O型血血浆含抗A和抗B抗体，能凝集其他血型受血者的红细胞，故O型血不能接受其他型血液，只能少量输给其他血型者。紧急情况下可将A型血少量缓慢输给AB型受血者，属配血基本相合。"},{"q":"通常引起GH分泌显著增加的机体状况是","o":["觉醒状态","轻度运动","进餐期间","慢波睡眠","异相睡眠"],"a":3,"e":"慢波睡眠时GH分泌陡增，入睡后约1小时血中GH浓度达高峰，夜间GH分泌量约占全天的70%。觉醒状态和异相睡眠时GH分泌均明显减少。"},{"q":"以下不经过特异性投射系统传入的感觉是","o":["视觉","嗅觉","听觉","味觉","本体感觉"],"a":1,"e":"丘脑是各种感觉传入的重要中继站，嗅觉除外，嗅觉冲动不经丘脑特异感觉接替核，故不通过特异性投射系统传入。视觉、听觉、味觉和本体感觉均经特异性投射系统传至大脑皮层。"},{"q":"红细胞渗透脆性指的是","o":["红细胞对高渗盐溶液的抵抗力","红细胞在低渗盐溶液中膨胀破裂的特性","红细胞在生理盐溶液中破裂的特性","红细胞耐受机械撞击的能力","红细胞相互撞击破裂的特性"],"a":1,"e":"红细胞在低渗盐溶液中发生膨胀破裂的特性称红细胞渗透脆性，简称脆性。衰老红细胞对低渗盐溶液抵抗力低，即脆性高。"},{"q":"下列功能中，脑干网状结构上行激动系统所具有的是","o":["形成模糊感觉","激发情绪反应","具有唤醒作用","维持身体平衡","增加肌紧张度"],"a":2,"e":"脑干网状结构上行激动系统经非特异性投射系统弥散投射至大脑皮层，维持和改变大脑皮层兴奋状态，具有唤醒作用。该系统无专一感觉传导功能，不能引起特定感觉。"},{"q":"关于血浆晶体渗透压说法正确的是","o":["当血浆晶体渗透压降低，会使红细胞膨胀、破裂","高于组织液晶体渗透压","对维持血浆容量有重要作用","由离子和大分子胶体物质形成","约占血浆总渗透压的50%"],"a":0,"e":"血浆晶体渗透压主要由Na+、Cl-等晶体物质形成，占血浆总渗透压的绝大部分，对维持细胞内外水平衡起重要作用。晶体渗透压降低时水进入红细胞，使其膨胀甚至破裂。"},{"q":"心室肌细胞动作电位平台期的离子跨膜流动是","o":["Na+内流，Cl-外流","Na+内流，K+外流","Na+内流，Cl-内流","Ca2+内流，K+外流","K+内流，Ca2+外流"],"a":3,"e":"心室肌细胞平台期由Ca2+内流与K+外流共同形成，两者时间过程相近，使膜电位维持在零电位附近。平台期Ca2+内流触发心肌细胞兴奋-收缩耦联。"},{"q":"平静呼气末存留于肺内的气量称为","o":["潮气量","余气量","补呼气量","功能余气量","补吸气量"],"a":3,"e":"功能余气量指平静呼气末尚存留于肺内的气体量，为余气量与补呼气量之和，正常成人约2500ml。余气量是最大呼气末残留的气量，与题干所述时相不同。"},{"q":"类固醇激素调控靶细胞功能的机制是","o":["主要是膜受体机制","主要是核受体机制，也有膜受体机制","主要是膜受体机制，也有核受体机制","热休克蛋白机制","仅为核受体机制"],"a":1,"e":"类固醇激素为脂溶性小分子，主要进入胞内与核受体结合，调节靶基因转录；同时也可通过膜受体发挥快速效应。教材指出脂氧合酶代谢产物等既可通过膜受体也可通过胞内核受体发挥作用。"},{"q":"应用阿托品后可出现的生理活动改变是","o":["心率减慢","气道阻力增加","闭汗","肠蠕动增加","缩瞳"],"a":2,"e":"阿托品阻断汗腺的M受体，使交感胆碱能纤维促汗腺分泌的作用被抑制而闭汗。阿托品阻断心迷走神经可使心率加快而非减慢，对气道、肠蠕动和瞳孔的作用与选项所述方向相反。"},{"q":"交感神经兴奋引起的心率加快，由下列哪种受体介导","o":["α1肾上腺素能受体","α2肾上腺素能受体","β1肾上腺素能受体","β2肾上腺素能受体","M胆碱能受体"],"a":2,"e":"心交感神经节后纤维释放去甲肾上腺素，作用于心肌β1受体，引起正性变时、变力和变传导作用，使心率加快。该效应可被β1受体拮抗剂美托洛尔阻断。"},{"q":"肾素-血管紧张素系统激活时以下减少或降低的是","o":["动脉血压","静脉紧张性","醛固醇分泌","肾上腺素分泌","肾脏的钠盐排出量"],"a":4,"e":"血管紧张素Ⅱ可刺激肾上腺皮质球状带分泌醛固酮，促进肾保钠排钾，使肾脏钠盐排出量减少。RAS激活还使血管收缩、血压升高、静脉紧张性增强。"},{"q":"炎热的夏天，气温达到40℃，户外活动时人体依靠什么方式散热维持体温的稳定","o":["辐射散热","传导散热","对流散热","蒸发散热","辐射和对流散热"],"a":3,"e":"环境温度等于或高于皮肤温度时，辐射、传导、对流散热均失效，蒸发成为机体唯一有效的散热方式。40℃气温下户外活动主要依靠出汗蒸发散热。"},{"q":"调节肾脏钠和钾排泌的激素是","o":["抗利尿激素","心房钠尿肽","血管紧张素","醛固酮","肾上腺素"],"a":3,"e":"醛固酮是调节肾钠、钾排出量最重要的体液因素，通过促进肾保钠排钾精确调控血钠和血钾浓度。抗利尿激素主要调节水的重吸收，心房钠尿肽则促进水钠排出。"},{"q":"感受器的结构多种多样，最简单的感受器是","o":["肌梭","环层小体","鲁菲尼小体","游离感觉神经末梢","颈动脉体化学感受器"],"a":3,"e":"感受器结构多样，最简单的感受器是游离神经末梢，如痛觉和温度觉感受器。肌梭、环层小体等均为结构较复杂、有附属结构的感受装置。"},{"q":"肾小球滤过一般只发生在入球端毛细血管段的主要原因是","o":["毛细血管内胶体渗透压逐渐升高","囊内压逐渐升高","毛细血管内晶体渗透压逐渐升高","肾小囊内胶体渗透压逐渐降低","毛细血管血压降低"],"a":0,"e":"肾小球毛细血管内血浆胶体渗透压从入球端向出球端不断升高，使有效滤过压逐渐下降至零，滤过停止。囊内压、晶体渗透压和毛细血管血压均非滤过限于入球端的主要原因。"},{"q":"引起逆行性失忆症的原因是","o":["由前额叶白质切断术消除","对阻断多巴胺受体的药物有反应","通常由头部打击引起","可由抗利尿激素治疗所引起","由于脑干损伤引起"],"a":2,"e":"逆行性遗忘症指不能回忆脑损伤前一段时间的经历，通常由头部打击等脑外伤引起。顺行性遗忘症多见于慢性酒精中毒等，与脑干损伤无关。"},{"q":"在下列组织中，代谢产热功能最强的是","o":["心肌","骨骼肌","平滑肌","脑","褐色脂肪组织"],"a":4,"e":"非战栗产热又称代谢性产热，作用最强的组织是褐色脂肪组织，其通过解耦联蛋白提高代谢率产热。骨骼肌以战栗产热为主。"},{"q":"胰岛素受体具有酪氨酸蛋白激酶活性的结构域位于受体的哪一部分","o":["α亚单位的N端","α亚单位的C端","β亚单位N端膜外部分","β亚单位的中间跨膜部分","β亚单位C端膜内部分"],"a":4,"e":"胰岛素受体β亚单位C端膜内结构域具有酪氨酸激酶活性，α亚单位位于膜外负责与胰岛素结合。β亚单位N端为膜外结构域，中间为跨膜结构域。"},{"q":"下列哪一项不属于激素的相互作用","o":["协调作用","拮抗作用","信使作用","允许作用","竞争作用"],"a":2,"e":"激素的相互作用包括协同作用、拮抗作用、允许作用和竞争作用。信使作用指激素作为信息传递分子，不属于激素间的相互作用形式。"},{"q":"血细胞的细胞外液是指","o":["体液","细胞内液","细胞外液","血浆","血液"],"a":3,"e":"血细胞直接生活的细胞外液是血浆，血浆构成血细胞的细胞外液环境。体液包括细胞内液和细胞外液，范围过大。"},{"q":"容量血管指的是","o":["肺动脉","毛细血管","微静脉","中动脉","静脉"],"a":4,"e":"静脉数量多、管壁薄、口径大、可扩张性大，容量大，故称容量血管，兼具血液储存库作用。微静脉仅影响毛细血管前后阻力比值。"},{"q":"耳蜗螺旋器毛细胞的听毛发生弯曲时，可产生","o":["耳蜗静息电位","耳蜗微音器电位","行波运动","动作电位","内淋巴电位"],"a":1,"e":"耳蜗受声刺激时毛细胞听毛弯曲产生感受器电位，其复合表现为耳蜗微音器电位，与声波频率和幅度一致。行波运动是基底膜的振动形式，非毛细胞产生的电位。"},{"q":"心房收缩挤入心室的血量约占心室总充盈量的","o":["1/10","1/6","1/5","1/4","1/3"],"a":3,"e":"心房收缩挤入心室的血量约占心室总充盈量的25%，即1/4。全心舒张期内回流入心室的血液约占75%，心房收缩仅起辅助充盈作用。"},{"q":"关于促肾上腺皮质激素的分泌，下列各项错误的是","o":["在应激状态下分泌增多","受下丘脑促肾上腺皮质激素释放激素的调节","受糖皮质激素的负反馈调节","受醛固酮的负反馈调节","长期大量使用糖皮质激素的患者，其分泌减少"],"a":3,"e":"醛固酮主要受血K+、血Na+浓度及AngⅡ、AngⅢ调节，ACTH仅在应激时促进其分泌，醛固酮不反馈调节ACTH分泌。ACTH受下丘脑CRH调节及糖皮质激素负反馈抑制。"},{"q":"关于搏出量储备，下列说法错误的是","o":["搏出量储备可分为收缩期储备和舒张期储备","提高射血分数可增加收缩期储备","增强心肌收缩能力可增加收缩期储备","增加舒张末期容积可增加舒张期储备","舒张期储备较收缩期储备大"],"a":4,"e":"收缩期储备可达35～40ml，舒张期储备仅约15ml，收缩期储备明显大于舒张期储备。收缩期储备通过增强心肌收缩力和提高射血分数实现，舒张期储备通过增加舒张期末容积获得。"},{"q":"外周化学感受器感受的适宜刺激是下列哪种因素的变化","o":["动脉血氧分压","动脉血氧含量","动脉血氧容量","动脉血氧饱和度","动脉血血红蛋白含量"],"a":0,"e":"外周化学感受器的适宜刺激是动脉血氧分压降低，而非氧含量、氧容量或氧饱和度。动脉血PO2下降可刺激外周化学感受器反射性增强呼吸。"},{"q":"自主神经系统活动的特点是","o":["自主神经系统的活动与效应器本身的功能状态有关","自主神经系统根据主观意识对效应器官发放不同频率的冲动","交感和副交感对组织器官的支配作用往往相互协同","交感神经系统的活动一般比较广泛，不同部分的交感神经对相同刺激的反应方式和程度相同","副交感神经系统的活动一般比较广泛"],"a":0,"e":"自主神经系统活动与效应器本身的功能状态有关，同一递质可因效应器表达的受体不同而产生不同效应。交感与副交感对多数器官的支配往往相互拮抗。"},{"q":"雌激素的生理作用不包括","o":["促进卵泡发育","促进子宫内膜分化","促进乳房脂肪沉积","促进阴道上皮细胞增生","促进输卵管发育"],"a":1,"e":"促进子宫内膜分化（蜕膜化）是孕激素的作用，雌激素主要促进子宫内膜增生。雌激素还促进卵泡发育、乳房脂肪沉积、阴道上皮增生及输卵管发育。"},{"q":"临床上不用异丙肾上腺素喷雾剂治疗支气管哮喘，原因是它","o":["同时激活α1受体，引起血压升高","同时激活α2受体，引起血压降低","同时激活β1受体，引起心脏活动加强","激活β2受体作用过强，引起通气过度","同时激活β3受体，引起脂肪代谢紊乱"],"a":2,"e":"异丙肾上腺素对β1和β2受体均有强激动作用，兴奋β2受体舒张支气管的同时激动β1受体使心率加快、心肌收缩力增强，易诱发心律失常，故不作喷雾剂常规使用。"},{"q":"下列神经中，属于肾上腺素能纤维的是","o":["支配肾上腺髓质的神经","骨骼肌交感舒血管神经","交感缩血管神经","骨骼肌运动神经","支配大部分汗腺的神经"],"a":2,"e":"交感缩血管神经节后纤维释放去甲肾上腺素，属肾上腺素能纤维。骨骼肌舒血管神经释放乙酰胆碱，支配汗腺的交感纤维也释放乙酰胆碱。"},{"q":"下列各种功能活动所消耗的能量中，最终不能转化为体热的是","o":["心脏泵血并推动血液流动","细胞合成某种蛋白质","肌肉收缩对外界物体做功","兴奋在神经纤维上传导","内、外分泌腺体的分泌活动"],"a":2,"e":"肌肉收缩对外界物体做功时，能量以机械功形式传给外界物体，最终不能转化为体热。心脏泵血、蛋白质合成、神经传导和腺体分泌所消耗的能量最终均转化为热能。"},{"q":"血中二氧化碳分压升高使呼吸运动加强，主要通过刺激下列哪一部位而实现","o":["脑桥呼吸相关神经元","中枢化学敏感区","延髓呼吸神经元","颈动脉窦和主动脉弓","颈动脉体和主动脉体"],"a":1,"e":"CO2可迅速通过血-脑屏障，使脑脊液和局部细胞外液中H+浓度升高，刺激中枢化学感受器，这是CO2引起肺通气加强的主要途径。外周化学感受器仅在PCO2突然升高时参与快速反应。"},{"q":"根据激素作用原理论述中的第二信使学说，可以看作第一信使的物质是","o":["含氮激素","甾体激素","类固醇激素","cAMP","钙离子"],"a":0,"e":"第二信使学说中，激素作为第一信使与膜受体结合后产生cAMP等细胞内信使分子。含氮激素多经膜受体发挥作用，属第一信使；cAMP为第二信使。"},{"q":"由膜固有电学性质决定，而非离子通道激活的膜电位是","o":["动作电位","局部反应","终板电位","电紧张电位","突触后电位"],"a":3,"e":"电紧张电位完全由膜的被动电学特性决定，其产生没有离子通道激活和膜电导改变。局部反应、终板电位和突触后电位均涉及离子通道开放。"},{"q":"某患者被诊断为Addison病（醛固酮分泌不足），此患者可出现","o":["低血钠、低血钾和酸中毒","高血钠、低血钾和碱中毒","低血钠、高血钾和酸中毒","高血钠、高血钾和碱中毒","高血钠、低血钾和酸中毒"],"a":2,"e":"醛固酮分泌不足时，肾小管保Na+排K+作用减弱，出现低血钠、高血钾，并因H+排出减少而发生酸中毒。高血钠、低血钾和碱中毒见于醛固酮增多症。"},{"q":"机体受到刺激而发生应激反应的系统是","o":["交感-肾上腺髓质系统","下丘脑-腺垂体-肾上腺皮质系统","下丘脑-腺垂体-甲状腺系统","下丘脑-腺垂体-性腺系统","下丘脑-神经垂体系统"],"a":1,"e":"应激时中枢神经系统增强CRH-ACTH-GC系统活动，ACTH和糖皮质激素分泌明显增多，且不受负反馈抑制，故下丘脑-腺垂体-肾上腺皮质系统是应激反应的核心系统。"},{"q":"外源性凝血途径的始动因子是","o":["FⅠ","FⅡ","FⅢ","FⅦ","FⅩ"],"a":2,"e":"组织因子（FⅢ）是生理性凝血反应的启动物，与FⅦa结合成复合物后激活FⅩ，从而启动外源性凝血途径。FⅦ为参与该复合物形成的凝血因子，并非始动因子。"},{"q":"当氧分压为40mmHg时，100ml血液中含有的O2量最接近","o":["4ml","6ml","8ml","10ml","12ml"],"a":4,"e":"静脉血PO2为40mmHg时，Hb氧饱和度约75%，Hb氧含量约为14.4ml/100ml血液，最接近12ml。"},{"q":"血中氢离子浓度升高使呼吸运动增强，主要通过刺激下列哪一部位而实现","o":["延髓呼吸中枢","脑桥呼吸中枢","中枢化学敏感区","颈动脉体和主动脉体","颈动脉窦和主动脉弓"],"a":3,"e":"H⁺浓度升高主要刺激外周化学感受器颈动脉体和主动脉体，经窦神经和迷走神经传入延髓，反射性增强呼吸。中枢化学感受器对H⁺不敏感，H⁺不易透过血脑屏障。"},{"q":"与胞质中cAMP生成有直接关系的膜效应器酶是","o":["磷脂酶A","腺苷酸环化酶","磷脂酶C","蛋白激酶","鸟苷酸环化酶"],"a":1,"e":"腺苷酸环化酶是G蛋白效应器酶，催化ATP生成cAMP，直接决定胞质cAMP的生成。磷脂酶C生成IP₃和DAG，鸟苷酸环化酶生成cGMP。"},{"q":"下列不是促胰液素作用的是","o":["促进胃酸分泌","促进胰液中水和HCO3-的大量分泌","促进肝细胞分泌胆汁","促进小肠液的分泌","保护小肠黏膜"],"a":0,"e":"促胰液素刺激胰液及胆汁中HCO₃⁻分泌，抑制胃酸分泌和胃肠运动。促进胃酸分泌的是促胃液素，故“促进胃酸分泌”不是促胰液素的作用。"},{"q":"葡萄糖或氨基酸逆浓度梯度跨细胞膜转运的方式是","o":["单纯扩散","经载体易化扩散","经通道易化扩散","原发性主动转运","继发性主动转运"],"a":4,"e":"葡萄糖、氨基酸逆浓度梯度跨膜利用Na⁺顺浓度梯度释放的能量，属继发性主动转运，其能量间接来自钠泵建立的Na⁺梯度。"},{"q":"尿的浓缩与稀释主要取决于","o":["肾小球滤过率","血浆胶体渗透压","抗利尿激素分泌量","肾素分泌量","醛固酮分泌量"],"a":2,"e":"抗利尿激素是决定集合管上皮细胞对水通透性的关键激素，其分泌量增减直接决定尿液浓缩或稀释。血浆晶体渗透压是调节其分泌最重要的因素。"},{"q":"关于肾上腺髓质激素的叙述，下列各项错误的是","o":["肾上腺素和去甲肾上腺素都是由髓质分泌的","髓质激素的化学本质是类固醇","肾上腺素受体有α和β两大类","去甲肾上腺素升血压作用强于肾上腺素","肾上腺髓质激素的分泌受交感神经支配"],"a":1,"e":"肾上腺髓质激素为儿茶酚胺类，包括肾上腺素和去甲肾上腺素，化学本质不是类固醇；肾上腺皮质激素才是类固醇激素。"},{"q":"血浆清除率是指肾脏在单位时间内","o":["将血浆中某物质完全清除出去的能力","将血浆中某物质完全清除出去的速率","将血浆中某物质完全清除出去的容量","将血浆中某物质完全清除出去的血浆毫升数","将肾小球滤出的某物质完全清除出去的能力"],"a":3,"e":"清除率指两肾每分钟能将多少毫升血浆中所含某物质完全清除，即完全清除该物质的血浆毫升数，是推算值而非真实清除容量。"},{"q":"下列哪种激素来自下丘脑","o":["TSH","LH","FSH","ACTH","GnRH"],"a":4,"e":"GnRH由下丘脑GnRH神经元分泌，调节腺垂体释放LH和FSH。TSH、ACTH来自腺垂体，LH、FSH亦为腺垂体激素。"},{"q":"下列情况使呼吸商变小的是","o":["肺通气过度","肌肉剧烈运动","糖在体内转化为脂肪","肺通气不足","酸中毒"],"a":3,"e":"肺通气不足时CO2排出减少，呼吸商变小。肌肉剧烈运动时糖无氧氧化加强、乳酸增多，CO2排出明显增加，呼吸商变大。"},{"q":"Hb的构型由R型变为T型时","o":["氧离曲线左移","Hb与O2的亲和力降低","Hb与H+结合能力降低","Hb与CO2结合能力降低","P50降低"],"a":1,"e":"Hb由R型转为T型时对O2的亲和力降低，R型Hb对O2的亲和力为T型的500倍。酸度增加促进盐键形成，使Hb向T型转变，氧离曲线右移、P50升高。"},{"q":"以下按研究对象所处的环境划分的生理学科为","o":["人体生理学","呼吸生理学","肾脏生理学","高原生理学","动物生理学"],"a":3,"e":"按研究对象所处环境状态不同，生理学分为太空生理学、潜水生理学、高原生理学等，高原生理学属此类。人体生理学、动物生理学按研究对象划分，呼吸生理学、肾脏生理学按器官系统划分。"},{"q":"在牵张反射的相关的神经支配中，外周神经末梢呈螺旋状的是","o":["Ⅰa类纤维","Ⅰb类纤维","Ⅱ类纤维","β运动神经元末梢","γ运动神经元末梢"],"a":0,"e":"肌梭的传入神经纤维有Ⅰa和Ⅱ类纤维，其中Ⅰa类纤维末梢呈螺旋状环绕于肌梭感受装置。Ⅰb类纤维来自腱器官，γ运动神经元末梢支配梭内肌。"},{"q":"关于基底膜振动的正确叙述是","o":["不同频率的声音在同一部位产生最大振动","声音频率越高，最大振动越近顶部","对于特定频率的振动，在基底膜上有一特定的行波传播范围和最大振幅区","声音频率越低，最大振动越近底部","不同频率的声波引起的行波是从基底膜底不同部位开始的"],"a":2,"e":"行波学说认为每一声波频率在基底膜上都有特定的行波传播范围和最大振幅区，该区毛细胞受刺激最强。声波频率越高最大振幅越靠近蜗底，频率越低越靠近蜗顶，且各频率行波均从基底膜底部开始。"},{"q":"钙通道阻断剂维拉帕米对浦肯野细胞动作电位的影响是","o":["0期去极化幅度降低","0期去极化速度减慢","1期复极化时程缩短","2期复极化时程缩短","3期复极化时程缩短"],"a":3,"e":"维拉帕米阻断L型钙通道，减少2期Ca2+内流，使2期平台期缩短。浦肯野细胞0期去极化由快钠通道介导，故0期幅度和速度不受影响。"},{"q":"下列关于神经纤维兴奋传导特征的描述，正确的是","o":["只能从胞体至末梢单向传导","神经干中各纤维之间互不干扰","只要结构完整就能正常传导兴奋","不受内环境因素变化的影响","连续刺激时，传导能力很快下降"],"a":1,"e":"神经纤维传导兴奋具有绝缘性，即一根神经干内各纤维同时传导兴奋时互不干扰。传导呈双向性，且依赖结构和功能完整，并受内环境因素影响。"},{"q":"下列哪种物质可减小气道阻力","o":["乙酰胆碱","儿茶酚胺","内皮素","组胺","白三烯"],"a":1,"e":"儿茶酚胺可使气道平滑肌舒张，减小气道阻力。组胺、白三烯、内皮素均使气道平滑肌收缩，乙酰胆碱亦引起支气管收缩。"},{"q":"胃的容受性舒张的实现是通过","o":["交感神经","迷走神经","壁内神经丛","抑胃肽","促胰液素"],"a":1,"e":"容受性舒张通过迷走-迷走反射实现，其传出纤维为迷走神经抑制性纤维，节后纤维释放VIP和NO使胃平滑肌舒张。"},{"q":"终板膜上与终板电位产生有关的离子通道是","o":["电压门控钠离子通道","电压门控钾离子通道","电压门控钙离子通道","化学门控非特异性镁通道","化学门控钠离子和钾离子通道"],"a":4,"e":"终板膜上的N2型ACh受体属化学门控通道，对Na+和K+均通透，ACh结合后引起终板电位。电压门控钠通道参与动作电位而非终板电位。"},{"q":"某种食物氧化时，消耗1L氧所产生的热量称为","o":["氧热价","食物的热价","物理热价","非蛋白呼吸商","呼吸商"],"a":0,"e":"氧热价指某种食物氧化时消耗1L O2所产生的热量，反映耗氧量与产热量的关系。食物热价指1g食物氧化释放的能量。"},{"q":"大脑皮层处于紧张活动时脑电活动主要表现为","o":["α波","β波","δ波","棘波","θ波"],"a":1,"e":"β波频率14～30Hz，在额叶和顶叶较显著，是新皮层处于紧张活动状态的标志；α波见于清醒安静闭眼时。"},{"q":"下列哪种激素对儿茶酚胺心血管效应起允许作用","o":["甲状腺激素","生长激素","糖皮质激素","醛固酮","抗利尿激素"],"a":2,"e":"糖皮质激素本身无缩血管作用，但其存在是儿茶酚胺充分发挥心血管效应的必要条件，此即允许作用。"},{"q":"在血液中影响PTH分泌的最关键元素是","o":["磷","钙","镁","钠","氯"],"a":1,"e":"血钙水平是调节PTH分泌的最主要因素，血钙降低可促进PTH的合成和分泌。"},{"q":"经载体易化扩散的特点是","o":["逆浓度梯度转运","转运过程消耗生物能","是气体分子和类固醇激素的转运方式","转运物浓度越高，转运速度越快，呈线性增加","两种结构相似的物质同时转运时会发生竞争性抑制"],"a":4,"e":"经载体易化扩散时，结构相似的物质可竞争同一载体而相互抑制。该转运顺浓度梯度、不耗能，且具饱和现象，速度不呈线性增加。"},{"q":"压力感受性反射最敏感的动脉血压波动范围是","o":["＜50mmHg","50～100mmHg","100mmHg左右","100～150mmHg","＞150mmHg"],"a":2,"e":"压力感受性反射在动脉血压平均压约100mmHg时最敏感，偏离该水平后敏感性下降。"},{"q":"催化花生四烯酸转变为廿烷酸衍生物的关键酶是","o":["环加氧酶","磷脂酶A2","磷脂酶C","血栓烷合成酶","前列环素合成酶"],"a":0,"e":"环加氧酶（COX）是催化花生四烯酸转变为类花生酸衍生物的关键酶，包括COX-1和COX-2两种同工酶。磷脂酶A2作用于花生四烯酸的释放环节，并非催化其转变为廿烷酸衍生物。"},{"q":"以下关于心肌收缩特点的描述，错误的是","o":["肌质网发达","收缩对细胞外Ca2+依赖性大","呈“全或无”式收缩","不发生完全强直收缩","长度-张力曲线一般不出现降支"],"a":0,"e":"心肌细胞肌质网不如骨骼肌发达，贮存Ca2+量较少，故心肌收缩对细胞外Ca2+高度依赖。心肌收缩呈“全或无”式、不发生完全强直收缩，长度-张力曲线一般不出现降支。"},{"q":"1位32岁健康女性在进行有氧运动中，会出现下列哪项情况","o":["PaO2升高","动脉血乳酸水平上升","动脉血pH降低","PaCO2降低","呼吸运动加深加快"],"a":4,"e":"运动时呼吸加深加快，肺通气量增加，O2摄入和CO2排出相应增多。有氧运动时PaO2通常维持正常，PaCO2可因通气增强而略降，但呼吸加深加快是确定出现的反应。"},{"q":"某患者检测血型时，红细胞与B型血的血清发生凝集，而其血清与B型血的红细胞不发生凝集，分析该患者的血型为","o":["A型","B型","O型","AB型","Rh阳性"],"a":3,"e":"红细胞与B型血清（含抗A抗体）凝集，说明红细胞含A抗原；血清与B型红细胞不凝集，说明血清无抗B抗体。含A抗原而无抗B抗体者为AB型。"},{"q":"在视5m以内近物时，人眼所进行的最重要的调节是","o":["角膜曲率增加","晶状体变凸","瞳孔近反射","瞳孔对光反射","眼轴会聚"],"a":1,"e":"眼视近物时发生晶状体变凸、瞳孔缩小和视轴会聚的近反射，其中最主要的是晶状体变凸，使折光能力增强，物像前移至视网膜。"},{"q":"胃黏膜屏障的作用一般是指","o":["防止H+由胃腔侵入黏膜","防止胃蛋白酶消化胃黏膜","防止Ca2+从黏膜向胃肠弥散","防止Cl-由胃腔侵入黏膜","防止细菌侵入黏膜"],"a":0,"e":"胃黏膜屏障指胃黏膜上皮细胞顶端膜与相邻细胞侧膜间的紧密连接，可防止胃腔内H+向黏膜上皮细胞内扩散。黏液-碳酸氢盐屏障则主要防止H+直接侵蚀和胃蛋白酶消化。"},{"q":"下列关于胆汁生理作用的描述，错误的是","o":["胆盐、胆固醇、卵磷脂都可乳化脂肪","胆汁可与脂肪酸结合，促进脂肪酸的吸收","胆汁可促进脂溶性维生素的吸收","胆汁的消化酶可促进脂肪的消化","胆汁在十二指肠可中和一部分胃酸"],"a":3,"e":"胆汁是唯一不含消化酶的消化液，其促进脂肪消化依靠胆盐、卵磷脂和胆固醇的乳化作用，而非消化酶。胆盐可与脂肪酸结合形成混合微胶粒促进吸收，并促进脂溶性维生素吸收、中和部分胃酸。"},{"q":"关于体温的正常生理变动，正确的是","o":["新生儿体温最稳定","老年人体温偏高","午后1～6时体温最低","通常成年女性的体温略低于男性","育龄期女性黄体期基础体温偏高"],"a":4,"e":"育龄期女性基础体温随月经周期变动，排卵后黄体期孕激素作用于下丘脑使体温调定点上移，基础体温升高0.3～0.6℃。新生儿体温调节能力差，老年人因BMR低体温偏低。"},{"q":"抑制性突触后电位的产生，是由于突触后膜提高了下列哪种离子的通透性","o":["氯离子","钙离子","钠离子","镁离子","氢离子"],"a":0,"e":"抑制性突触后电位是突触后膜对氯离子通透性升高、氯离子内流引起超极化所致。钠离子通透性升高则产生去极化的兴奋性突触后电位。"},{"q":"血液中CO2运输的主要形式是","o":["物理溶解","氨基甲酰血红蛋白","碳酸氢盐","氧合血红蛋白","去氧血红蛋白"],"a":2,"e":"血液中CO2主要以碳酸氢盐形式运输，在红细胞内碳酸酐酶催化下CO2与H2O生成H2CO3并解离为HCO3-。物理溶解和氨基甲酰血红蛋白所占比例小。"},{"q":"心动周期中，主动脉压最低见于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":4,"e":"等容收缩期室内压急剧升高，当超过主动脉压时半月瓣开放，故主动脉压最低点出现在半月瓣开放前的等容收缩期末。"},{"q":"关于动脉脉搏的描述，正确的是","o":["动脉脉搏图记录的是外周肱动脉的脉搏波形图","射血速度加快时，脉搏图波形上升支变平坦","主动脉瓣关闭不全患者脉搏图波性较正常人波形平缓","外周阻力增大或心输出量增多时，降中峡位置降低","老年人动脉脉搏图的每个波形所占的时间要比青年人的长"],"a":4,"e":"动脉脉搏波沿动脉管壁传播，老年人动脉硬化使脉搏波传播速度加快，波长缩短，故每个波形所占时间比青年人长。上升支由心室快速射血形成，射血加快时上升支更陡。"},{"q":"大脑皮层功能一侧优势指的是","o":["一侧大脑半球神经元特别多","一侧大脑半球经常强烈兴奋","人类脑的语言功能向一侧半球集中的现象","人类脑的功能全部集中在一侧半球","人类脑的非语词性的认知功能向一侧半球集中的现象"],"a":2,"e":"大脑皮层功能一侧优势指人类语言功能主要集中于左侧大脑半球的现象，左侧为语言优势半球。非语词性认知功能以右侧半球占优势，但并非全部功能集中于一侧。"},{"q":"凝血因子FⅧ的作用是","o":["激活FⅨ","使FⅩa对FⅡ的激活加快","使FⅨa对FⅩ的激活加快","使FⅡa对FⅠ的激活加快","使FⅨ活化成FⅨa的速度加快"],"a":2,"e":"FⅧa作为辅因子与FⅨa在活化血小板膜磷脂表面结合成因子Ⅹ酶复合物，使FⅨa对FⅩ的激活速度提高约20万倍。"},{"q":"感觉的特异投射系统能引起特定感觉的主要原因是","o":["发自丘脑特异感觉接替核","中间不换元，直接投射到大脑皮层","与大脑皮层有点对点的投射关系","投射纤维主要终止于皮层的第四层","很少受内环境理化因素的影响"],"a":2,"e":"特异投射系统投射纤维点对点地终止于大脑皮层特定区域，引起特定感觉。非特异投射系统弥散投射，与皮层无点对点关系，只维持觉醒。"},{"q":"内环境中最活跃的部分是","o":["组织液","血浆","细胞内液","脑脊液","淋巴液"],"a":1,"e":"血浆与组织液、淋巴液同属细胞外液，血浆因不断循环流动而成为内环境中最活跃的部分。组织液不能自由流动，相对稳定。"}];
